@Test
public void testFileSystemFromUri() throws Exception {
    String localFsClass = "LocalFileSystem";
    String remoteFsHost = "127.0.0.5:8080";
    String fileUri = "hdfs://" + remoteFsHost + "/bulk-xyx/file1.rf";
    // There was a bug in the code where the default hadoop file system was always used. This test
    // checks that the hadoop filesystem used it based on the URI and not the default filesystem. In
    // this env the default file system is the local hadoop file system.
    var exception = assertThrows(ConnectException.class, () -> RFile.newWriter().to(fileUri).build());
    assertTrue(exception.getMessage().contains("to " + remoteFsHost + " failed on connection exception: java.net.ConnectException: Connection refused"));
    // Ensure the DistributedFileSystem was used.
    assertTrue(Arrays.stream(exception.getStackTrace()).anyMatch(ste -> ste.getClassName().contains(DistributedFileSystem.class.getName())));
    assertTrue(Arrays.stream(exception.getStackTrace()).noneMatch(ste -> ste.getClassName().contains(localFsClass)));
    var exception2 = assertThrows(RuntimeException.class, () -> {
        var scanner = RFile.newScanner().from(fileUri).build();
        scanner.iterator();
    });
    assertTrue(exception2.getMessage().contains("to " + remoteFsHost + " failed on connection exception: java.net.ConnectException: Connection refused"));
    assertTrue(Arrays.stream(exception2.getCause().getStackTrace()).anyMatch(ste -> ste.getClassName().contains(DistributedFileSystem.class.getName())));
    assertTrue(Arrays.stream(exception2.getCause().getStackTrace()).noneMatch(ste -> ste.getClassName().contains(localFsClass)));
    // verify the assumptions this test is making about the local filesystem being the default.
    var exception3 = assertThrows(IllegalArgumentException.class, () -> FileSystem.get(new Configuration()).open(new Path(fileUri)));
    assertTrue(exception3.getMessage().contains("Wrong FS: " + fileUri + ", expected: file:///"));
    assertTrue(Arrays.stream(exception3.getStackTrace()).anyMatch(ste -> ste.getClassName().contains(localFsClass)));
}

