@Test
public void testBinSplit() throws Exception {
    // try binning mutations and ranges when a tablet splits
    for (int i = 0; i < 3; i++) {
        // when i == 0 only test binning mutations
        // when i == 1 only test binning ranges
        // when i == 2 test both
        KeyExtent ke1 = createNewKeyExtent("foo", null, null);
        TServers tservers = new TServers();
        ClientTabletCacheImpl metaCache = createLocators(tservers, "tserver1", "tserver2", "foo", ke1, "l1");
        List<Mutation> ml = createNewMutationList(createNewMutation("a", "cf1:cq1=v1", "cf1:cq2=v2"), createNewMutation("m", "cf1:cq1=v3", "cf1:cq2=v4"), createNewMutation("z", "cf1:cq1=v5"));
        Map<String, Map<KeyExtent, List<String>>> emb = createServerExtentMap(createServerExtent("a", "l1", ke1), createServerExtent("m", "l1", ke1), createServerExtent("z", "l1", ke1));
        if (i == 0 || i == 2) {
            runTest(metaCache, ml, emb);
        }
        List<Range> ranges = createNewRangeList(new Range(new Text("a")), new Range(new Text("m")), new Range(new Text("z")));
        Map<String, Map<KeyExtent, List<Range>>> expected1 = createExpectedBinnings(createRangeLocation("l1", createNewKeyExtent("foo", null, null), ranges));
        if (i == 1 || i == 2) {
            runTest(ranges, metaCache, expected1);
        }
        KeyExtent ke11 = createNewKeyExtent("foo", "n", null);
        KeyExtent ke12 = createNewKeyExtent("foo", null, "n");
        setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke12, "l2");
        metaCache.invalidateCache(ke1);
        emb = createServerExtentMap(createServerExtent("z", "l2", ke12));
        if (i == 0 || i == 2) {
            runTest(metaCache, ml, emb, "a", "m");
        }
        Map<String, Map<KeyExtent, List<Range>>> expected2 = createExpectedBinnings(createRangeLocation("l2", createNewKeyExtent("foo", null, "n"), createNewRangeList(new Range(new Text("z")))));
        if (i == 1 || i == 2) {
            runTest(ranges, metaCache, expected2, createNewRangeList(new Range(new Text("a")), new Range(new Text("m"))));
        }
        setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke11, "l3");
        emb = createServerExtentMap(createServerExtent("a", "l3", ke11), createServerExtent("m", "l3", ke11), createServerExtent("z", "l2", ke12));
        if (i == 0 || i == 2) {
            runTest(metaCache, ml, emb);
        }
        Map<String, Map<KeyExtent, List<Range>>> expected3 = createExpectedBinnings(createRangeLocation("l2", createNewKeyExtent("foo", null, "n"), createNewRangeList(new Range(new Text("z")))), createRangeLocation("l3", createNewKeyExtent("foo", "n", null), createNewRangeList(new Range(new Text("a")), new Range(new Text("m")))));
        if (i == 1 || i == 2) {
            runTest(ranges, metaCache, expected3);
        }
    }
}

