@Test
public void testLostLock() throws Exception {
    final HashSet<String> activeLocks = new HashSet<>();
    TServers tservers = new TServers();
    ClientTabletCacheImpl metaCache = createLocators(tservers, "tserver1", "tserver2", "foo", new TabletServerLockChecker() {

        @Override
        public boolean isLockHeld(String tserver, String session) {
            return activeLocks.contains(tserver + ":" + session);
        }

        @Override
        public void invalidateCache(String server) {
        }
    });
    KeyExtent ke1 = createNewKeyExtent("foo", null, null);
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke1, "L1", "5");
    activeLocks.add("L1:5");
    locateTabletTest(metaCache, "a", ke1, "L1");
    locateTabletTest(metaCache, "a", ke1, "L1");
    activeLocks.clear();
    locateTabletTest(metaCache, "a", null, null);
    locateTabletTest(metaCache, "a", null, null);
    locateTabletTest(metaCache, "a", null, null);
    clearLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke1, "5");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke1, "L2", "6");
    activeLocks.add("L2:6");
    locateTabletTest(metaCache, "a", ke1, "L2");
    locateTabletTest(metaCache, "a", ke1, "L2");
    clearLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke1, "6");
    locateTabletTest(metaCache, "a", ke1, "L2");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke1, "L3", "7");
    locateTabletTest(metaCache, "a", ke1, "L2");
    activeLocks.clear();
    locateTabletTest(metaCache, "a", null, null);
    locateTabletTest(metaCache, "a", null, null);
    activeLocks.add("L3:7");
    locateTabletTest(metaCache, "a", ke1, "L3");
    locateTabletTest(metaCache, "a", ke1, "L3");
    List<Mutation> ml = createNewMutationList(createNewMutation("a", "cf1:cq1=v1", "cf1:cq2=v2"), createNewMutation("w", "cf1:cq3=v3"));
    Map<String, Map<KeyExtent, List<String>>> emb = createServerExtentMap(createServerExtent("a", "L3", ke1), createServerExtent("w", "L3", ke1));
    runTest(metaCache, ml, emb);
    clearLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke1, "7");
    runTest(metaCache, ml, emb);
    activeLocks.clear();
    emb.clear();
    runTest(metaCache, ml, emb, "a", "w");
    runTest(metaCache, ml, emb, "a", "w");
    KeyExtent ke11 = createNewKeyExtent("foo", "m", null);
    KeyExtent ke12 = createNewKeyExtent("foo", null, "m");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke11, "L1", "8");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke12, "L2", "9");
    runTest(metaCache, ml, emb, "a", "w");
    activeLocks.add("L1:8");
    emb = createServerExtentMap(createServerExtent("a", "L1", ke11));
    runTest(metaCache, ml, emb, "w");
    activeLocks.add("L2:9");
    emb = createServerExtentMap(createServerExtent("a", "L1", ke11), createServerExtent("w", "L2", ke12));
    runTest(metaCache, ml, emb);
    List<Range> ranges = createNewRangeList(new Range("a"), createNewRange("b", "o"), createNewRange("r", "z"));
    Map<String, Map<KeyExtent, List<Range>>> expected = createExpectedBinnings(createRangeLocation("L1", ke11, createNewRangeList(new Range("a"), createNewRange("b", "o"))), createRangeLocation("L2", ke12, createNewRangeList(createNewRange("b", "o"), createNewRange("r", "z"))));
    runTest(ranges, metaCache, expected);
    activeLocks.remove("L2:9");
    expected = createExpectedBinnings(createRangeLocation("L1", ke11, createNewRangeList(new Range("a"))));
    runTest(ranges, metaCache, expected, createNewRangeList(createNewRange("b", "o"), createNewRange("r", "z")));
    activeLocks.clear();
    expected = createExpectedBinnings();
    runTest(ranges, metaCache, expected, createNewRangeList(new Range("a"), createNewRange("b", "o"), createNewRange("r", "z")));
    clearLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke11, "8");
    clearLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke12, "9");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke11, "L3", "10");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke12, "L4", "11");
    runTest(ranges, metaCache, expected, createNewRangeList(new Range("a"), createNewRange("b", "o"), createNewRange("r", "z")));
    activeLocks.add("L3:10");
    expected = createExpectedBinnings(createRangeLocation("L3", ke11, createNewRangeList(new Range("a"))));
    runTest(ranges, metaCache, expected, createNewRangeList(createNewRange("b", "o"), createNewRange("r", "z")));
    activeLocks.add("L4:11");
    expected = createExpectedBinnings(createRangeLocation("L3", ke11, createNewRangeList(new Range("a"), createNewRange("b", "o"))), createRangeLocation("L4", ke12, createNewRangeList(createNewRange("b", "o"), createNewRange("r", "z"))));
    runTest(ranges, metaCache, expected);
}

@Test
public void testCachingUnhosted() throws Exception {
    // this test caching tablets without a location
    TServers tservers = new TServers();
    ClientTabletCacheImpl metaCache = createLocators(tservers, "tserver1", "tserver2", "foo");
    var ke1 = createNewKeyExtent("foo", "g", null);
    var ke2 = createNewKeyExtent("foo", "m", "g");
    var ke3 = createNewKeyExtent("foo", "r", "m");
    var ke4 = createNewKeyExtent("foo", null, "r");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke1, null, null);
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke2, null, null);
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke3, "L2", "I2");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke4, "L2", "I2");
    locateTabletTest(metaCache, "a", false, ke1, null, LocationNeed.NOT_REQUIRED);
    locateTabletTest(metaCache, "a", false, null, null, LocationNeed.REQUIRED);
    locateTabletTest(metaCache, "n", false, ke3, "L2", LocationNeed.NOT_REQUIRED);
    locateTabletTest(metaCache, "n", false, ke3, "L2", LocationNeed.REQUIRED);
    var r1 = new Range(null, "a");
    var r2 = new Range("d", "o");
    List<Range> ranges = List.of(r1, r2);
    Set<Pair<CachedTablet, Range>> actual = new HashSet<>();
    var failures = metaCache.findTablets(context, ranges, (tl, r) -> actual.add(new Pair<>(tl, r)), LocationNeed.NOT_REQUIRED);
    assertEquals(List.of(), failures);
    var tl1 = new CachedTablet(ke1, TabletAvailability.ONDEMAND, false);
    var tl2 = new CachedTablet(ke2, TabletAvailability.ONDEMAND, false);
    var tl3 = new CachedTablet(ke3, "L2", "I2", TabletAvailability.ONDEMAND, false);
    var expected = Set.of(new Pair<>(tl1, r1), new Pair<>(tl1, r2), new Pair<>(tl2, r2), new Pair<>(tl3, r2));
    assertEquals(expected, actual);
    actual.clear();
    failures = metaCache.findTablets(context, ranges, (tl, r) -> actual.add(new Pair<>(tl, r)), LocationNeed.REQUIRED);
    assertEquals(new HashSet<>(ranges), new HashSet<>(failures));
    assertEquals(Set.of(), actual);
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke1, "L3", "I3");
    // the cache contains ke1 w/o a location, even though the location is now set we should get the
    // cached version w/o the location
    locateTabletTest(metaCache, "a", false, ke1, null, LocationNeed.NOT_REQUIRED);
    // the cache contains an extent w/o a location this should force it to clear
    locateTabletTest(metaCache, "a", false, ke1, "L3", LocationNeed.REQUIRED);
    // now that the location is cached, should see it
    locateTabletTest(metaCache, "a", false, ke1, "L3", LocationNeed.NOT_REQUIRED);
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke2, "L4", "I4");
    // even though the location is set for ke2 the cache should have ke2 w/o a location and that
    // should be seeen
    actual.clear();
    failures = metaCache.findTablets(context, ranges, (tl, r) -> actual.add(new Pair<>(tl, r)), LocationNeed.NOT_REQUIRED);
    assertEquals(List.of(), failures);
    tl1 = new CachedTablet(ke1, "L3", "I3", TabletAvailability.ONDEMAND, false);
    expected = Set.of(new Pair<>(tl1, r1), new Pair<>(tl1, r2), new Pair<>(tl2, r2), new Pair<>(tl3, r2));
    assertEquals(expected, actual);
    // this should cause the location for ke2 to be pulled into the cache
    actual.clear();
    failures = metaCache.findTablets(context, ranges, (tl, r) -> actual.add(new Pair<>(tl, r)), LocationNeed.REQUIRED);
    assertEquals(List.of(), failures);
    tl2 = new CachedTablet(ke2, "L4", "I4", TabletAvailability.ONDEMAND, false);
    expected = Set.of(new Pair<>(tl1, r1), new Pair<>(tl1, r2), new Pair<>(tl2, r2), new Pair<>(tl3, r2));
    assertEquals(expected, actual);
    // should still see locations in cache
    actual.clear();
    failures = metaCache.findTablets(context, ranges, (tl, r) -> actual.add(new Pair<>(tl, r)), LocationNeed.NOT_REQUIRED);
    assertEquals(List.of(), failures);
    assertEquals(expected, actual);
    // ensure bin mutations works when the cache contains an entry w/o a location
    deleteLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke2, "I4");
    metaCache.invalidateCache(ke2);
    locateTabletTest(metaCache, "i", false, ke2, null, LocationNeed.NOT_REQUIRED);
    // one mutation should fail because there is no location for ke2
    List<Mutation> ml = createNewMutationList(createNewMutation("a", "cf1:cq1=v1", "cf1:cq2=v2"), createNewMutation("i", "cf1:cq1=v3", "cf1:cq2=v4"));
    Map<String, Map<KeyExtent, List<String>>> emb = createServerExtentMap(createServerExtent("a", "L3", ke1));
    runTest(metaCache, ml, emb, "i");
    // set location for ke2 and both mutations should bin.. the cached entry for ke2 w/o a location
    // should be jettisoned
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke2, "L4", "I4");
    emb = createServerExtentMap(createServerExtent("a", "L3", ke1), createServerExtent("i", "L4", ke2));
    runTest(metaCache, ml, emb);
}

/**
 * This test ensures the cache does not query the metadata table more than is needed. This
 * behavior is very important for performance.
 */
@Test
public void testLookupCounts() throws Exception {
    List<KeyExtent> lookups = new ArrayList<>();
    TServers tservers = new TServers();
    tservers.lookupConsumer = (src, row) -> lookups.add(src.getExtent());
    ClientTabletCacheImpl metaCache = createLocators(tservers, "tserver1", "tserver2", "foo");
    var ke1 = createNewKeyExtent("foo", "g", null);
    var ke2 = createNewKeyExtent("foo", "m", "g");
    var ke3 = createNewKeyExtent("foo", "r", "m");
    var ke4 = createNewKeyExtent("foo", null, "r");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke1, null, null);
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke2, null, null);
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke3, null, null);
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke4, null, null);
    List<Mutation> ml = new ArrayList<>();
    for (char c = 'a'; c <= 'z'; c++) {
        ml.add(createNewMutation("" + c, "cf1:cq1=v3", "cf1:cq2=v4"));
    }
    Map<String, TabletServerMutations<Mutation>> binnedMutations = new HashMap<>();
    List<Mutation> afailures = new ArrayList<>();
    assertEquals(List.of(), lookups);
    metaCache.binMutations(context, ml, binnedMutations, afailures);
    assertTrue(binnedMutations.isEmpty());
    assertEquals(ml.size(), afailures.size());
    // since all tablets are in the same metadata table, should only see one lookup to the metadata
    // table
    assertEquals(List.of(ROOT_TABLE_EXTENT, METADATA_TABLE_EXTENT), lookups);
    // since tablets had no locations, attempting to binMutations again should go back to the
    // metadata table once
    lookups.clear();
    binnedMutations.clear();
    afailures.clear();
    metaCache.binMutations(context, ml, binnedMutations, afailures);
    assertTrue(binnedMutations.isEmpty());
    assertEquals(ml.size(), afailures.size());
    assertEquals(List.of(METADATA_TABLE_EXTENT), lookups);
    // test binning ranges
    var range1 = createNewRange("a", "c");
    var range2 = createNewRange("h", "o");
    var range3 = createNewRange("x", "z");
    var ranges = List.of(range1, range2, range3);
    // binning ranges should do a single metadata lookup since location is required and what is
    // currently cached has no location
    BiConsumer<CachedTablet, Range> rangeConsumer = (t, r) -> fail("Tablet have no locations, so should not bin");
    lookups.clear();
    var failures = metaCache.findTablets(context, ranges, rangeConsumer, LocationNeed.REQUIRED);
    assertEquals(3, failures.size());
    assertEquals(List.of(METADATA_TABLE_EXTENT), lookups);
    // should do a single metadata lookup since the cached entries have no location
    lookups.clear();
    failures = metaCache.findTablets(context, ranges, rangeConsumer, LocationNeed.REQUIRED);
    assertEquals(3, failures.size());
    assertEquals(List.of(METADATA_TABLE_EXTENT), lookups);
    // since location is not required and the currently cached entries have no locations the
    // following should not do metadata lookups
    Map<KeyExtent, List<Range>> seen = new HashMap<>();
    rangeConsumer = (t, r) -> {
        seen.computeIfAbsent(t.getExtent(), k -> new ArrayList<>()).add(r);
        assertTrue(t.getTserverLocation().isEmpty());
    };
    lookups.clear();
    failures = metaCache.findTablets(context, ranges, rangeConsumer, LocationNeed.NOT_REQUIRED);
    assertEquals(List.of(), lookups);
    assertEquals(Map.of(ke1, List.of(range1), ke2, List.of(range2), ke3, List.of(range2), ke4, List.of(range3)), seen);
    assertEquals(0, failures.size());
    // set locations
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke1, "T1", "I1");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke2, "T2", "I2");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke3, "T3", "I3");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke4, "T3", "I3");
    // now that locations are set, all mutations should bin.. should only do one metadata lookup to
    // get the locations
    lookups.clear();
    binnedMutations.clear();
    afailures.clear();
    assertEquals(List.of(), lookups);
    metaCache.binMutations(context, ml, binnedMutations, afailures);
    assertEquals(Set.of("T1", "T2", "T3"), binnedMutations.keySet());
    assertEquals(7, binnedMutations.get("T1").getMutations().get(ke1).size());
    assertEquals(6, binnedMutations.get("T2").getMutations().get(ke2).size());
    assertEquals(5, binnedMutations.get("T3").getMutations().get(ke3).size());
    assertEquals(8, binnedMutations.get("T3").getMutations().get(ke4).size());
    assertEquals(0, afailures.size());
    assertEquals(List.of(METADATA_TABLE_EXTENT), lookups);
    // binning mutations again should do zero metadata lookups
    lookups.clear();
    binnedMutations.clear();
    afailures.clear();
    metaCache.binMutations(context, ml, binnedMutations, afailures);
    assertEquals(Set.of("T1", "T2", "T3"), binnedMutations.keySet());
    assertEquals(7, binnedMutations.get("T1").getMutations().get(ke1).size());
    assertEquals(6, binnedMutations.get("T2").getMutations().get(ke2).size());
    assertEquals(5, binnedMutations.get("T3").getMutations().get(ke3).size());
    assertEquals(8, binnedMutations.get("T3").getMutations().get(ke4).size());
    assertEquals(0, afailures.size());
    assertEquals(List.of(), lookups);
    // since the cached entries have locations there should be no metadata lookups when binning
    // ranges
    seen.clear();
    rangeConsumer = (t, r) -> {
        seen.computeIfAbsent(t.getExtent(), k -> new ArrayList<>()).add(r);
        assertTrue(t.getTserverLocation().isPresent());
    };
    lookups.clear();
    failures = metaCache.findTablets(context, ranges, rangeConsumer, LocationNeed.REQUIRED);
    assertEquals(List.of(), lookups);
    assertEquals(Map.of(ke1, List.of(range1), ke2, List.of(range2), ke3, List.of(range2), ke4, List.of(range3)), seen);
    assertEquals(0, failures.size());
}

@Test
public void testMultithreadedLookups() throws Exception {
    // This test ensures that when multiple threads all attempt to lookup data that is not currently
    // in the cache that the minimal amount of metadata lookups are done. Should only see one
    // concurrent lookup per metadata tablet and no more or less.
    KeyExtent mte1 = new KeyExtent(AccumuloTable.METADATA.tableId(), new Text("foo;m"), null);
    KeyExtent mte2 = new KeyExtent(AccumuloTable.METADATA.tableId(), null, new Text("foo;m"));
    var ke1 = createNewKeyExtent("foo", "m", null);
    var ke2 = createNewKeyExtent("foo", "q", "m");
    var ke3 = createNewKeyExtent("foo", null, "q");
    TServers tservers = new TServers();
    List<KeyExtent> lookups = Collections.synchronizedList(new ArrayList<>());
    AtomicInteger activeLookups = new AtomicInteger(0);
    AtomicBoolean sawTwoActive = new AtomicBoolean(false);
    tservers.lookupConsumer = (src, row) -> {
        if (!src.getExtent().equals(ROOT_TABLE_EXTENT)) {
            lookups.add(src.getExtent());
            // increment the total number of threads currently doing metadata lookups
            activeLookups.incrementAndGet();
            try {
                while (!sawTwoActive.get()) {
                    // sleep to simulate metadata lookup that takes time, this gives threads time to pile up
                    // waiting for the metadata lookup
                    Thread.sleep(100);
                    // wait until two threads are doing metadata lookups
                    if (activeLookups.get() == 2) {
                        sawTwoActive.set(true);
                    } else {
                        // Should never see more than two threads in here because the cache should not do more
                        // than one lookup per metadata tablet at a time and there are two metadata tablets.
                        assertTrue(activeLookups.get() <= 2);
                    }
                }
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            } finally {
                activeLookups.decrementAndGet();
            }
        }
    };
    TestCachedTabletObtainer ttlo = new TestCachedTabletObtainer(tservers);
    RootClientTabletCache rtl = new TestRootClientTabletCache();
    ClientTabletCacheImpl rootTabletCache = new ClientTabletCacheImpl(AccumuloTable.METADATA.tableId(), rtl, ttlo, new YesLockChecker());
    ClientTabletCacheImpl metaCache = new ClientTabletCacheImpl(TableId.of("foo"), rootTabletCache, ttlo, new YesLockChecker());
    setLocation(tservers, "tserver1", ROOT_TABLE_EXTENT, mte1, "tserver2");
    setLocation(tservers, "tserver1", ROOT_TABLE_EXTENT, mte2, "tserver3");
    setLocation(tservers, "tserver2", mte1, ke1, "tserver7");
    setLocation(tservers, "tserver3", mte2, ke2, "tserver8");
    setLocation(tservers, "tserver3", mte2, ke3, "tserver9");
    var executor = Executors.newCachedThreadPool();
    List<Future<CachedTablet>> futures = new ArrayList<>();
    // start 64 threads all trying to lookup data in the cache, should see only two threads do a
    // concurrent lookup in the metadata table and no more or less.
    List<String> rowsToLookup = new ArrayList<>();
    for (int i = 0; i < 64; i++) {
        String lookup = (char) ('a' + (i % 26)) + "";
        rowsToLookup.add(lookup);
    }
    Collections.shuffle(rowsToLookup);
    for (var lookup : rowsToLookup) {
        var future = executor.submit(() -> {
            var loc = metaCache.findTablet(context, new Text(lookup), false, LocationNeed.REQUIRED);
            if (lookup.compareTo("m") <= 0) {
                assertEquals("tserver7", loc.getTserverLocation().orElseThrow());
            } else if (lookup.compareTo("q") <= 0) {
                assertEquals("tserver8", loc.getTserverLocation().orElseThrow());
            } else {
                assertEquals("tserver9", loc.getTserverLocation().orElseThrow());
            }
            return loc;
        });
        futures.add(future);
    }
    for (var future : futures) {
        assertNotNull(future.get());
    }
    assertTrue(sawTwoActive.get());
    // The second metadata tablet (mte2) contains two user tablets (ke2 and ke3). Depending on which
    // of these two user tablets is looked up in the metadata table first will see a total of 2 or 3
    // lookups. If the location of ke2 is looked up first then it will get the locations of ke2 and
    // ke3 from mte2 and put them in the cache. If the location of ke3 is looked up first then it
    // will only get the location of ke3 from mte2 and not ke2.
    assertTrue(lookups.size() == 2 || lookups.size() == 3, lookups::toString);
    assertEquals(1, lookups.stream().filter(metadataExtent -> metadataExtent.equals(mte1)).count(), lookups::toString);
    var mte2Lookups = lookups.stream().filter(metadataExtent -> metadataExtent.equals(mte2)).count();
    assertTrue(mte2Lookups == 1 || mte2Lookups == 2, lookups::toString);
    executor.shutdown();
}

@Test
public void testNonBlocking() throws Exception {
    // Tests that when two threads query the cache and one needs to read from metadata table and one
    // does not, that the one that does not is not blocked. This test ensures that when data is in
    // cache it can always be accessed immediately.
    List<KeyExtent> lookups = new ArrayList<>();
    TServers tservers = new TServers();
    // This lock is used by the test to cause a metadata lookup to block
    var lookupLock = new ReentrantLock();
    tservers.lookupConsumer = (src, row) -> {
        lookupLock.lock();
        try {
            lookups.add(src.getExtent());
        } finally {
            lookupLock.unlock();
        }
    };
    ClientTabletCacheImpl metaCache = createLocators(tservers, "tserver1", "tserver2", "foo");
    var ke1 = createNewKeyExtent("foo", "g", null);
    var ke2 = createNewKeyExtent("foo", "m", "g");
    var ke3 = createNewKeyExtent("foo", "r", "m");
    var ke4 = createNewKeyExtent("foo", null, "r");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke1, "tserver3");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke2, "tserver4");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke3, "tserver5");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke4, "tserver6");
    assertEquals("tserver3", metaCache.findTablet(context, new Text("a"), false, LocationNeed.REQUIRED).getTserverLocation().orElseThrow());
    assertEquals("tserver4", metaCache.findTablet(context, new Text("h"), false, LocationNeed.REQUIRED).getTserverLocation().orElseThrow());
    assertEquals("tserver5", metaCache.findTablet(context, new Text("n"), false, LocationNeed.REQUIRED).getTserverLocation().orElseThrow());
    assertEquals("tserver6", metaCache.findTablet(context, new Text("s"), false, LocationNeed.REQUIRED).getTserverLocation().orElseThrow());
    // clear this extent from cache to cause it to be looked up again in the metadata table
    metaCache.invalidateCache(ke2);
    var executor = Executors.newCachedThreadPool();
    // acquire this lock to simulate a metadata table lookup blocking
    lookupLock.lock();
    // verify test assumption
    assertEquals(0, lookupLock.getQueueLength());
    // start a background task that will read from the metadata table
    var lookupFuture = executor.submit(() -> metaCache.findTablet(context, new Text("h"), false, LocationNeed.REQUIRED).getTserverLocation().orElseThrow());
    // wait for the background thread to get stuck waiting on the lock
    while (lookupLock.getQueueLength() == 0) {
        Thread.sleep(5);
    }
    // The lookup task should be blocked trying to get location from the metadata table
    assertFalse(lookupFuture.isDone());
    assertEquals(1, lookupLock.getQueueLength());
    // should be able to get the tablet locations that are still in the cache w/o blocking
    assertEquals("tserver3", metaCache.findTablet(context, new Text("a"), false, LocationNeed.REQUIRED).getTserverLocation().orElseThrow());
    assertEquals("tserver5", metaCache.findTablet(context, new Text("n"), false, LocationNeed.REQUIRED).getTserverLocation().orElseThrow());
    assertEquals("tserver6", metaCache.findTablet(context, new Text("s"), false, LocationNeed.REQUIRED).getTserverLocation().orElseThrow());
    // The lookup task should still be blocked
    assertFalse(lookupFuture.isDone());
    assertEquals(1, lookupLock.getQueueLength());
    // allow the metadata lookup running in background thread to proceed.
    lookupLock.unlock();
    // The future should be able to run and complete
    assertEquals("tserver4", lookupFuture.get());
    // verify test assumptions
    assertTrue(lookupFuture.isDone());
    assertEquals(0, lookupLock.getQueueLength());
}

@Test
public void testInvalidation() throws Exception {
    // Test invalidation methods on the cache. Other test methods call the invalidate methods and
    // assume it works, but do not verify its working as expected. Want to verify two things in this
    // test. First verify that invalidation only invalidates what was requested and no more. Second
    // verify that invalidation causes a metadata read on subsequent cache accesses.
    List<String> lookups = new ArrayList<>();
    TServers tservers = new TServers();
    tservers.lookupConsumer = (src, row) -> {
        if (src.getExtent().equals(METADATA_TABLE_EXTENT)) {
            lookups.add(row.toString());
        }
    };
    ClientTabletCacheImpl metaCache = createLocators(tservers, "tserver1", "tserver2", "foo");
    var ke1 = createNewKeyExtent("foo", "g", null);
    var ke2 = createNewKeyExtent("foo", "m", "g");
    var ke3 = createNewKeyExtent("foo", "r", "m");
    var ke4 = createNewKeyExtent("foo", null, "r");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke1, "tserver3");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke2, "tserver4");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke3, "tserver5");
    setLocation(tservers, "tserver2", METADATA_TABLE_EXTENT, ke4, "tserver3");
    // Do cache lookups in reverse order to force a metadata lookup for each row. The cache will
    // read ahead when doing metadata lookups and want to avoid that in this case.
    Map<String, String> expectedLocations = new LinkedHashMap<>();
    expectedLocations.put("s", "tserver3");
    expectedLocations.put("n", "tserver5");
    expectedLocations.put("h", "tserver4");
    expectedLocations.put("a", "tserver3");
    checkLocations(expectedLocations, metaCache);
    assertEquals(Set.of("foo;s", "foo;n", "foo;h", "foo;a"), Set.copyOf(lookups));
    // invalidate one extent from the metadata table, should only read that extent from metadata
    // table
    metaCache.invalidateCache(ke2);
    lookups.clear();
    checkLocations(expectedLocations, metaCache);
    assertEquals(Set.of("foo;h"), Set.copyOf(lookups));
    // invalidate two extents
    metaCache.invalidateCache(List.of(ke2, ke4));
    lookups.clear();
    checkLocations(expectedLocations, metaCache);
    assertEquals(Set.of("foo;h", "foo;s"), Set.copyOf(lookups));
    // invalidate everything in cache
    metaCache.invalidateCache();
    lookups.clear();
    checkLocations(expectedLocations, metaCache);
    assertEquals(Set.of("foo;s", "foo;n", "foo;h", "foo;a"), Set.copyOf(lookups));
    // when nothing was invalidated, should see no metadata lookups
    lookups.clear();
    checkLocations(expectedLocations, metaCache);
    assertEquals(Set.of(), Set.copyOf(lookups));
}

@Test
public void testComparator() {
    Condition c1 = new Condition("a", "b");
    Condition c2 = new Condition("a", "c");
    Condition c3 = new Condition("b", "c");
    Condition c4 = new Condition("a", "b").setTimestamp(5);
    Condition c5 = new Condition("a", "b").setTimestamp(6);
    Condition c6 = new Condition("a", "b").setVisibility(new ColumnVisibility("A&B"));
    Condition c7 = new Condition("a", "b").setVisibility(new ColumnVisibility("A&C"));
    Comparator<Condition> comparator = ConditionalWriterImpl.CONDITION_COMPARATOR;
    assertEquals(0, comparator.compare(c1, c1));
    assertTrue(comparator.compare(c1, c2) < 0);
    assertTrue(comparator.compare(c2, c1) > 0);
    assertTrue(comparator.compare(c1, c3) < 0);
    assertTrue(comparator.compare(c3, c1) > 0);
    assertTrue(comparator.compare(c1, c4) < 0);
    assertTrue(comparator.compare(c4, c1) > 0);
    assertTrue(comparator.compare(c5, c4) < 0);
    assertTrue(comparator.compare(c4, c5) > 0);
    assertTrue(comparator.compare(c1, c7) < 0);
    assertTrue(comparator.compare(c7, c1) > 0);
    assertTrue(comparator.compare(c6, c7) < 0);
    assertTrue(comparator.compare(c7, c6) > 0);
}

