    assertEquals("foo", ke.tableId().canonical());
    assertNull(ke.prevEndRow());
    flattenedExtent = new Text("foo<");
    ke = KeyExtent.fromMetaRow(flattenedExtent);
    assertNull(ke.endRow());
    assertEquals("foo", ke.tableId().canonical());
    assertNull(ke.prevEndRow());
