@Test
public void testClip() {
    // Test extent will null end/prevEnd and infinite range matches original
    ke = new KeyExtent(TableId.of("1"), null, null);
    Range range = new Range();
    KeyExtent expected = ke;
    KeyExtent clipped = ke.clip(range);
    assertEquals(expected, clipped);
    // Test extent with null end/prevEnd with a range, should match the range
    expected = new KeyExtent(TableId.of("1"), new Text("r_0001"), new Text("r_0000"));
    ke = new KeyExtent(TableId.of("1"), null, null);
    range = new Range("r_0000", false, "r_0001", true);
    clipped = ke.clip(range);
    assertEquals(expected, clipped);
    // Test resulting extent is narrowed, the overlapping rows are 4 - 7
    expected = new KeyExtent(TableId.of("1"), new Text("r_0007"), new Text("r_0003"));
    ke = new KeyExtent(TableId.of("1"), new Text("r_0007"), new Text("r_0000"));
    range = new Range("r_0003", false, "r_0009", true);
    clipped = ke.clip(range);
    assertEquals(expected, clipped);
    // Test disjoint
    ke = new KeyExtent(TableId.of("1"), new Text("r_0007"), new Text("r_0005"));
    range = new Range("r_0002", false, "r_0004", true);
    clipped = ke.clip(range, true);
    assertNull(clipped);
    final Range r = range;
    assertThrows(IllegalArgumentException.class, () -> ke.clip(r));
    // Invalid row ranges
    assertThrows(IllegalArgumentException.class, () -> ke.clip(new Range("r_0002", true, "r_0004", true)));
    assertThrows(IllegalArgumentException.class, () -> ke.clip(new Range(new Key("r_0002", "cf_0002"), false, new Key("r_0003", "cf_0003"), true)));
    // Test empty row to make sure isExclusiveKey() checks length
    assertThrows(IllegalArgumentException.class, () -> ke.clip(new Range(new Key("r_0004").followingKey(PartialKey.ROW), true, new Key("").followingKey(PartialKey.ROW), false)));
}

@Test
public void testDeletedCompare() {
    final byte[] row = "r1".getBytes(UTF_8);
    final byte[] cf = "cf".getBytes(UTF_8);
    final byte[] cq = "cq".getBytes(UTF_8);
    Key k1 = new Key(row, cf, cq, new byte[0], 0, false);
    Key k2 = new Key(row, cf, cq, new byte[0], 0, false);
    Key k3 = new Key(row, cf, cq, new byte[0], 0, true);
    Key k4 = new Key(row, cf, cq, new byte[0], 0, true);
    assertEquals(k1, k2);
    assertEquals(k3, k4);
    assertTrue(k1.compareTo(k3) > 0);
    assertTrue(k3.compareTo(k1) < 0);
}

@Test
public void testCopyData() {
    byte[] row = "r".getBytes(UTF_8);
    byte[] cf = "cf".getBytes(UTF_8);
    byte[] cq = "cq".getBytes(UTF_8);
    byte[] cv = "cv".getBytes(UTF_8);
    Key k1 = new Key(row, cf, cq, cv, 5L, false, false);
    Key k2 = new Key(row, cf, cq, cv, 5L, false, true);
    assertSame(row, k1.getRowBytes());
    assertSame(cf, k1.getColFamily());
    assertSame(cq, k1.getColQualifier());
    assertSame(cv, k1.getColVisibility());
    assertSame(row, k1.getRowData().getBackingArray());
    assertSame(cf, k1.getColumnFamilyData().getBackingArray());
    assertSame(cq, k1.getColumnQualifierData().getBackingArray());
    assertSame(cv, k1.getColumnVisibilityData().getBackingArray());
    assertNotSame(row, k2.getRowBytes());
    assertNotSame(cf, k2.getColFamily());
    assertNotSame(cq, k2.getColQualifier());
    assertNotSame(cv, k2.getColVisibility());
    assertNotSame(row, k2.getRowData().getBackingArray());
    assertNotSame(cf, k2.getColumnFamilyData().getBackingArray());
    assertNotSame(cq, k2.getColumnQualifierData().getBackingArray());
    assertNotSame(cv, k2.getColumnVisibilityData().getBackingArray());
    assertEquals(k1, k2);
}

