@Test
public void testTypes() {
    LoadPlan loadPlan = LoadPlan.builder().loadFileTo("f1.rf", RangeType.FILE, "1112", "1145").loadFileTo("f2.rf", RangeType.FILE, "abc".getBytes(UTF_8), "def".getBytes(UTF_8)).loadFileTo("f3.rf", RangeType.FILE, new Text("368"), new Text("479")).loadFileTo("f4.rf", RangeType.TABLE, null, "aaa").loadFileTo("f5.rf", RangeType.TABLE, "yyy", null).loadFileTo("f6.rf", RangeType.TABLE, null, "bbb".getBytes(UTF_8)).loadFileTo("f7.rf", RangeType.TABLE, "www".getBytes(UTF_8), null).loadFileTo("f8.rf", RangeType.TABLE, null, new Text("ccc")).loadFileTo("f9.rf", RangeType.TABLE, new Text("xxx"), null).loadFileTo("fa.rf", RangeType.TABLE, "1138", "1147").loadFileTo("fb.rf", RangeType.TABLE, "heg".getBytes(UTF_8), "klt".getBytes(UTF_8)).loadFileTo("fc.rf", RangeType.TABLE, new Text("agt"), new Text("ctt")).addPlan(LoadPlan.builder().loadFileTo("fd.rf", RangeType.TABLE, (String) null, null).build()).build();
    Set<String> expected = new HashSet<>();
    expected.add("f1.rf:FILE:1112:1145");
    expected.add("f2.rf:FILE:abc:def");
    expected.add("f3.rf:FILE:368:479");
    expected.add("f4.rf:TABLE:null:aaa");
    expected.add("f5.rf:TABLE:yyy:null");
    expected.add("f6.rf:TABLE:null:bbb");
    expected.add("f7.rf:TABLE:www:null");
    expected.add("f8.rf:TABLE:null:ccc");
    expected.add("f9.rf:TABLE:xxx:null");
    expected.add("fa.rf:TABLE:1138:1147");
    expected.add("fb.rf:TABLE:heg:klt");
    expected.add("fc.rf:TABLE:agt:ctt");
    expected.add("fd.rf:TABLE:null:null");
    Set<String> actual = loadPlan.getDestinations().stream().map(LoadPlanTest::toString).collect(toSet());
    assertEquals(expected, actual);
    var loadPlan2 = LoadPlan.fromJson(loadPlan.toJson());
    Set<String> actual2 = loadPlan2.getDestinations().stream().map(LoadPlanTest::toString).collect(toSet());
