    // Try different illegal uuids in the fate id
    for (var illegalUuid : List.of("3366-4485-92ab-6961bbd6d3f4", "075cd820-4485-92ab-6961bbd6d3f4", "075cd820-3366-4485-92ab", "075C++20-3366-4485-92ab-6961bbd6d3f4", "075cd820-    -4485-92ab-6961bbd6d3f4", "42b64e8-4307-4f7d-8466-a11e81eb56c7", "842b64e8-307-4f7d-8466-a11e81eb56c7", "842b64e8-4307-f7d-8466-a11e81eb56c7", "842b64e8-4307-4f7d-466-a11e81eb56c7", "842b64e8-4307-4f7d-8466-11e81eb56c7", "842b64e843074f7d8466a11e81eb56c7")) {
