@Test
public void testLock() throws Exception {
    final SomeData data = new SomeData();
    data.write();
    data.read();
    QueueLock qlock = new MockQueueLock();
    final ReadWriteLock locker = new DistributedReadWriteLock(qlock, FateId.from(FateInstanceType.USER, UUID.randomUUID()));
    final Lock readLock = locker.readLock();
    final Lock writeLock = locker.writeLock();
    readLock.lock();
    readLock.unlock();
    writeLock.lock();
    writeLock.unlock();
    readLock.lock();
    readLock.unlock();
    // do a bunch of reads/writes in separate threads, look for inconsistent updates
    Thread[] threads = new Thread[2];
    for (int i = 0; i < threads.length; i++) {
        final int which = i;
        threads[i] = new Thread(() -> {
            if (which % 2 == 0) {
                final Lock wl = locker.writeLock();
                wl.lock();
                try {
                    data.write();
                } finally {
                    wl.unlock();
                }
            } else {
                final Lock rl = locker.readLock();
                rl.lock();
                data.read();
                try {
                    data.read();
                } finally {
                    rl.unlock();
                }
            }
        });
    }
    for (Thread t : threads) {
        t.start();
    }
    for (Thread t : threads) {
        t.join();
    }
}

