@Test
public void testGetCompactors() {
    UUID uuid = UUID.randomUUID();
    String svcLock1 = ServiceLock.ZLOCK_PREFIX + uuid.toString() + "#0000000001";
    String svcLock2 = ServiceLock.ZLOCK_PREFIX + uuid.toString() + "#0000000002";
    var sld1 = new ServiceLockData(uuid, HOSTNAME, ThriftService.COMPACTOR, TEST_RESOURCE_GROUP);
    var sld2 = new ServiceLockData(uuid, HOSTNAME, ThriftService.COMPACTOR, DEFAULT_RESOURCE_GROUP_NAME);
    expect(zc.getChildren(ZCOMPACTORS)).andReturn(List.of(TEST_RESOURCE_GROUP, DEFAULT_RESOURCE_GROUP_NAME)).anyTimes();
    expect(zc.getChildren(ZCOMPACTORS + "/" + TEST_RESOURCE_GROUP)).andReturn(List.of(HOSTNAME, HOSTNAME_NO_LOCK)).anyTimes();
    expect(zc.getChildren(ZCOMPACTORS + "/" + DEFAULT_RESOURCE_GROUP_NAME)).andReturn(List.of(HOSTNAME, HOSTNAME_NO_LOCK)).anyTimes();
    expect(zc.getChildren(ZCOMPACTORS + "/" + TEST_RESOURCE_GROUP + "/" + HOSTNAME_NO_LOCK)).andReturn(List.of()).anyTimes();
    expect(zc.getChildren(ZCOMPACTORS + "/" + DEFAULT_RESOURCE_GROUP_NAME + "/" + HOSTNAME_NO_LOCK)).andReturn(List.of()).anyTimes();
    expect(zc.getChildren(ZCOMPACTORS + "/" + TEST_RESOURCE_GROUP + "/" + HOSTNAME)).andReturn(List.of(svcLock1, svcLock2)).anyTimes();
    expect(zc.getChildren(ZCOMPACTORS + "/" + DEFAULT_RESOURCE_GROUP_NAME + "/" + HOSTNAME)).andReturn(List.of(svcLock1, svcLock2)).anyTimes();
    expect(zc.get(EasyMock.eq(ZCOMPACTORS + "/" + TEST_RESOURCE_GROUP + "/" + HOSTNAME + "/" + svcLock1), EasyMock.isA(ZcStat.class))).andReturn(sld1.serialize()).anyTimes();
    expect(zc.get(EasyMock.eq(ZCOMPACTORS + "/" + DEFAULT_RESOURCE_GROUP_NAME + "/" + HOSTNAME + "/" + svcLock1), EasyMock.isA(ZcStat.class))).andReturn(sld2.serialize()).anyTimes();
    expect(zc.getChildren(ZCOMPACTORS + "/" + TEST_RESOURCE_GROUP + "/localhost:1234")).andReturn(null).anyTimes();
    expect(zc.get(ZCOMPACTORS + "/" + TEST_RESOURCE_GROUP + "/localhost:1234")).andReturn(null).anyTimes();
    replay(zc);
    // query for all
    Set<ServiceLockPath> results = paths.getCompactor(rg -> true, AddressSelector.all(), false);
    assertEquals(4, results.size());
    for (ServiceLockPath path : results) {
        assertEquals(ZCOMPACTORS, path.getType());
        assertTrue(path.getServer().equals(HOSTNAME) || path.getServer().equals(HOSTNAME_NO_LOCK));
        assertTrue(path.getResourceGroup().equals(DEFAULT_RESOURCE_GROUP_NAME) || path.getResourceGroup().equals(TEST_RESOURCE_GROUP));
        assertTrue(path.toString().equals(ZCOMPACTORS + "/" + DEFAULT_RESOURCE_GROUP_NAME + "/" + HOSTNAME) || path.toString().equals(ZCOMPACTORS + "/" + DEFAULT_RESOURCE_GROUP_NAME + "/" + HOSTNAME_NO_LOCK) || path.toString().equals(ZCOMPACTORS + "/" + TEST_RESOURCE_GROUP + "/" + HOSTNAME) || path.toString().equals(ZCOMPACTORS + "/" + TEST_RESOURCE_GROUP + "/" + HOSTNAME_NO_LOCK));
    }
    // query for all with locks
    results = paths.getCompactor(rg -> true, AddressSelector.all(), true);
    assertEquals(2, results.size());
    Iterator<ServiceLockPath> iter = results.iterator();
    var slp1 = iter.next();
    assertEquals(HOSTNAME, slp1.getServer());
    assertEquals(ZCOMPACTORS, slp1.getType());
    if (slp1.getResourceGroup().equals(TEST_RESOURCE_GROUP)) {
        assertEquals(ZCOMPACTORS + "/" + TEST_RESOURCE_GROUP + "/" + HOSTNAME, slp1.toString());
    } else if (slp1.getResourceGroup().equals(DEFAULT_RESOURCE_GROUP_NAME)) {
