        migrations.add(m.getTablet());
    }
    migrationsOut.clear();
    SortedMap<TabletServerId, TServerStatus> current2 = createCurrent(15);
    wait = this.balance(new BalanceParamsImpl(current2, Map.of(Constants.DEFAULT_RESOURCE_GROUP_NAME, current2.keySet()), migrations, migrationsOut, DataLevel.USER, environment.getTableIdMap()));
    assertEquals(20000, wait);
    // should balance four tablets in one of the other tables before reaching max
    assertEquals(4, migrationsOut.size());
    // now balance again passing in the new migrations
    for (TabletMigration m : migrationsOut) {
        migrations.add(m.getTablet());
    }
    migrationsOut.clear();
    SortedMap<TabletServerId, TServerStatus> current3 = createCurrent(15);
    wait = this.balance(new BalanceParamsImpl(current3, Map.of(Constants.DEFAULT_RESOURCE_GROUP_NAME, current3.keySet()), migrations, migrationsOut, DataLevel.USER, environment.getTableIdMap()));
    assertEquals(20000, wait);
    // should balance four tablets in one of the other tables before reaching max
    assertEquals(4, migrationsOut.size());
    // now balance again passing in the new migrations
    for (TabletMigration m : migrationsOut) {
        migrations.add(m.getTablet());
    }
    migrationsOut.clear();
    SortedMap<TabletServerId, TServerStatus> current4 = createCurrent(15);
    wait = this.balance(new BalanceParamsImpl(current4, Map.of(Constants.DEFAULT_RESOURCE_GROUP_NAME, current4.keySet()), migrations, migrationsOut, DataLevel.USER, environment.getTableIdMap()));
    assertEquals(20000, wait);
