public void testRestart() throws InterruptedException {
    Timer timer = Timer.startNew();
    // Perform a longer sleep initially
    Thread.sleep(100);
    Duration firstElapsed = timer.elapsed();
    assertTrue(timer.hasElapsed(Duration.ofMillis(100)), "Should see at least the sleep time has elapsed.");
    timer.restart();
    // Perform a shorter sleep
    Thread.sleep(50);
    Duration secondElapsed = timer.elapsed();
    // Assert that the elapsed time after restart is greater than 0
    assertFalse(secondElapsed.isNegative(), "Elapsed time should be greater than 0 after restarting the timer.");
    assertTrue(secondElapsed.compareTo(firstElapsed) < 0, "Elapsed time after restart should be less than the initial elapsed time.");
}

