@Test
public void testElapsedWithTimeUnit() throws InterruptedException {
    Timer timer = Timer.startNew();
    final int sleepMillis = 50;
    Thread.sleep(sleepMillis);
    long elapsedMillis = timer.elapsed(MILLISECONDS);
    assertTrue(elapsedMillis >= sleepMillis, "Elapsed time in milliseconds is not correct.");
    if (elapsedMillis < 1000) {
        long elapsedSeconds = timer.elapsed(TimeUnit.SECONDS);
        assertEquals(0, elapsedSeconds, "Elapsed time in seconds should be 0 for 50 milliseconds of sleep.");
    }
}

@Test
public void testStartedAfter() throws Exception {
    var timer1 = Timer.startNew();
    Thread.sleep(3);
    var timer2 = Timer.startNew();
    assertTrue(timer2.startedAfter(timer1));
    assertFalse(timer1.startedAfter(timer2));
    Thread.sleep(3);
    timer1.restart();
    assertTrue(timer1.startedAfter(timer2));
    assertFalse(timer2.startedAfter(timer1));
    Thread.sleep(3);
    timer2.restart();
    assertTrue(timer2.startedAfter(timer1));
    assertFalse(timer1.startedAfter(timer2));
}

@Test
public void testByteBufferConstructor() {
    byte[] test = "0123456789".getBytes(UTF_8);
    ByteBuffer bb1 = ByteBuffer.wrap(test);
    UnsynchronizedBuffer.Reader ub = new UnsynchronizedBuffer.Reader(bb1);
    byte[] buf = new byte[10];
    ub.readBytes(buf);
    assertEquals("0123456789", new String(buf, UTF_8));
    ByteBuffer bb2 = ByteBuffer.wrap(test, 3, 5);
    ub = new UnsynchronizedBuffer.Reader(bb2);
    buf = new byte[5];
    // should read data from offset 3 where the byte buffer starts
    ub.readBytes(buf);
    assertEquals("34567", new String(buf, UTF_8));
    buf = new byte[6];
    // the byte buffer has the extra byte, but should not be able to read it...
    final UnsynchronizedBuffer.Reader finalUb = ub;
    final byte[] finalBuf = buf;
    assertThrows(ArrayIndexOutOfBoundsException.class, () -> finalUb.readBytes(finalBuf));
}

