/**
 * Tests several different paths through the getSplits() method by setting different properties
 * and verifying the results.
 */
@Test
public void testGetSplits() throws Exception {
    String table = getUniqueNames(1)[0];
    client.tableOperations().create(table);
    insertData(table, currentTimeMillis());
    Job job = Job.getInstance();
    AccumuloInputFormat.configure().clientProperties(getClientProps()).table(table).auths(Authorizations.EMPTY).scanIsolation(true).store(job);
    // split table
    TreeSet<Text> splitsToAdd = new TreeSet<>();
    for (int i = 0; i < 10000; i += 1000) {
        splitsToAdd.add(new Text(String.format("%09d", i)));
    }
    client.tableOperations().addSplits(table, splitsToAdd);
    // wait for splits to be propagated
    Thread.sleep(500);
    // get splits without setting any range
    // No ranges set on the job so it'll start with -inf
    Collection<Text> actualSplits = client.tableOperations().listSplits(table);
    List<InputSplit> splits = inputFormat.getSplits(job);
    assertEquals(actualSplits.size() + 1, splits.size());
    // set ranges and get splits
    List<Range> ranges = new ArrayList<>();
    for (Text text : actualSplits) {
        ranges.add(new Range(text));
    }
    AccumuloInputFormat.configure().clientProperties(getClientProps()).table(table).auths(Authorizations.EMPTY).ranges(ranges).store(job);
    splits = inputFormat.getSplits(job);
    assertEquals(actualSplits.size(), splits.size());
    // offline mode
    AccumuloInputFormat.configure().clientProperties(getClientProps()).table(table).auths(Authorizations.EMPTY).offlineScan(true).store(job);
    assertThrows(IOException.class, () -> inputFormat.getSplits(job));
    client.tableOperations().offline(table, true);
    splits = inputFormat.getSplits(job);
    assertEquals(actualSplits.size(), splits.size());
    // auto adjust ranges
    ranges = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        // overlapping ranges
        ranges.add(new Range(String.format("%09d", i), String.format("%09d", i + 2)));
    }
    AccumuloInputFormat.configure().clientProperties(getClientProps()).table(table).auths(Authorizations.EMPTY).ranges(ranges).offlineScan(true).store(job);
    splits = inputFormat.getSplits(job);
    assertEquals(2, splits.size());
    AccumuloInputFormat.configure().clientProperties(getClientProps()).table(table).auths(Authorizations.EMPTY).ranges(ranges).autoAdjustRanges(false).offlineScan(true).store(job);
    splits = inputFormat.getSplits(job);
    assertEquals(ranges.size(), splits.size());
    // BatchScan not available for offline scans
    AccumuloInputFormat.configure().clientProperties(getClientProps()).table(table).auths(Authorizations.EMPTY).batchScan(true).offlineScan(true).store(job);
    assertThrows(IllegalArgumentException.class, () -> inputFormat.getSplits(job), "IllegalArgumentException should have been thrown trying to batch scan offline");
    // table online tests
    client.tableOperations().online(table, true);
    AccumuloInputFormat.configure().clientProperties(getClientProps()).table(table).auths(Authorizations.EMPTY).store(job);
    // test for resumption of success
    splits = inputFormat.getSplits(job);
    assertEquals(2, splits.size());
    // BatchScan not available with isolated iterators
    AccumuloInputFormat.configure().clientProperties(getClientProps()).table(table).auths(Authorizations.EMPTY).batchScan(true).scanIsolation(true).store(job);
    assertThrows(IllegalArgumentException.class, () -> inputFormat.getSplits(job), "IllegalArgumentException should have been thrown trying to batch scan with isolation");
    // BatchScan not available with local iterators
    AccumuloInputFormat.configure().clientProperties(getClientProps()).table(table).auths(Authorizations.EMPTY).batchScan(true).localIterators(true).store(job);
    assertThrows(IllegalArgumentException.class, () -> inputFormat.getSplits(job), "IllegalArgumentException should have been thrown trying to batch scan locally");
    AccumuloInputFormat.configure().clientProperties(getClientProps()).table(table).auths(Authorizations.EMPTY).batchScan(true).store(job);
    // Check we are getting back correct type pf split
    splits = inputFormat.getSplits(job);
    for (InputSplit split : splits) {
        assertTrue(split instanceof BatchInputSplit);
    }
    // We should split along the tablet lines
    assertEquals(2, splits.size());
}

