@Test
public void testFromFixed() {
    var sysPropKey = SystemPropKey.of();
    // default
    assertEquals("9997", sysConfig.get(TSERV_CLIENTPORT));
    // fixed sys config
    assertEquals("1234", sysConfig.get(GC_PORT));
    // fixed sys config
    assertEquals("19", sysConfig.get(TSERV_SCAN_MAX_OPENFILES));
    // sys config
    assertEquals("true", sysConfig.get(TABLE_BLOOM_ENABLED));
    // default
    assertEquals(TABLE_BLOOM_SIZE.getDefaultValue(), sysConfig.get(TABLE_BLOOM_SIZE));
    // default
    assertFalse(sysConfig.isPropertySet(TSERV_CLIENTPORT));
    // fixed sys config
    assertTrue(sysConfig.isPropertySet(GC_PORT));
    // fixed sys config
    assertTrue(sysConfig.isPropertySet(TSERV_SCAN_MAX_OPENFILES));
    // sys config
    assertTrue(sysConfig.isPropertySet(TABLE_BLOOM_ENABLED));
    // default
    assertTrue(sysConfig.isPropertySet(TABLE_BLOOM_SIZE));
    reset(propStore);
    VersionedProperties sysUpdateProps = new VersionedProperties(2, Instant.now(), Map.of(GC_PORT.getKey(), "3456", TSERV_SCAN_MAX_OPENFILES.getKey(), "27", TABLE_BLOOM_ENABLED.getKey(), "false", TABLE_BLOOM_SIZE.getKey(), "2048"));
    expect(propStore.get(eq(sysPropKey))).andReturn(sysUpdateProps).anyTimes();
    replay(propStore);
    sysConfig.zkChangeEvent(sysPropKey);
    // default
    assertEquals("9997", sysConfig.get(TSERV_CLIENTPORT));
    // fixed sys config
    assertEquals("1234", sysConfig.get(GC_PORT));
    // fixed sys config
    assertEquals("19", sysConfig.get(TSERV_SCAN_MAX_OPENFILES));
    // sys config
    assertEquals("false", sysConfig.get(TABLE_BLOOM_ENABLED));
    // default
    assertEquals("2048", sysConfig.get(TABLE_BLOOM_SIZE));
    // default
    assertFalse(sysConfig.isPropertySet(TSERV_CLIENTPORT));
    // fixed sys config
    assertTrue(sysConfig.isPropertySet(GC_PORT));
    // fixed sys config
    assertTrue(sysConfig.isPropertySet(TSERV_SCAN_MAX_OPENFILES));
    // sys config
    assertTrue(sysConfig.isPropertySet(TABLE_BLOOM_ENABLED));
    // default
    assertTrue(sysConfig.isPropertySet(TABLE_BLOOM_SIZE));
}

