    m.put(BulkFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile2")).getMetadataText(), new Value(fateId1.canonical()));
    m.put(DataFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile2")).getMetadataText(), new DataFileValue(1, 1).encodeAsValue());
    violations = mc.check(createEnv(), m);
    assertTrue(violations.isEmpty());
    // two files w/ different txid
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile")).getMetadataText(), new Value(fateId1.canonical()));
    m.put(DataFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile")).getMetadataText(), new DataFileValue(1, 1).encodeAsValue());
    m.put(BulkFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile2")).getMetadataText(), new Value(fateId2.canonical()));
    m.put(DataFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile2")).getMetadataText(), new DataFileValue(1, 1).encodeAsValue());
    assertViolation(mc, m, (short) 8);
    // two loaded markers but only one file.
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile")).getMetadataText(), new Value(fateId1.canonical()));
    m.put(DataFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile")).getMetadataText(), new DataFileValue(1, 1).encodeAsValue());
    m.put(BulkFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile2")).getMetadataText(), new Value(fateId1.canonical()));
    assertViolation(mc, m, (short) 8);
    // mutation that looks like split
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile")).getMetadataText(), new Value(fateId1.canonical()));
    ServerColumnFamily.DIRECTORY_COLUMN.put(m, new Value("t-000009x"));
    // Missing split column, should fail
    assertViolation(mc, m, (short) 8);
    // mutation that looks like split
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile")).getMetadataText(), new Value(fateId1.canonical()));
    ServerColumnFamily.DIRECTORY_COLUMN.put(m, new Value("t-000009x"));
    // Add opid column
    ServerColumnFamily.OPID_COLUMN.put(m, new Value("SPLITTING:FATE:META:12345678-9abc-def1-2345-6789abcdef12"));
    violations = mc.check(createEnv(), m);
    assertTrue(violations.isEmpty());
    // mutation that looks like a load
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile")).getMetadataText(), new Value(fateId1.canonical()));
    m.put(CurrentLocationColumnFamily.NAME, new Text("789"), new Value("127.0.0.1:9997"));
    violations = mc.check(createEnv(), m);
    assertTrue(violations.isEmpty());
    // deleting a load flag
    m = new Mutation(new Text("0;foo"));
    m.putDelete(BulkFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile")).getMetadataText());
    violations = mc.check(createEnv(), m);
    assertTrue(violations.isEmpty());
    // Missing beginning of path
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, new Text(StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile")).getMetadata().replace("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile", "/someFile")), new Value(fateId1.canonical()));
    assertViolation(mc, m, (short) 3100);
    // Missing tables directory in path
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, new Text(StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile")).getMetadata().replace("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile", "hdfs://1.2.3.4/accumulo/2a/t-0003/someFile")), new Value(fateId1.canonical()));
    assertViolation(mc, m, (short) 3100);
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile")).getMetadataText(), new Value(fateId1.canonical()));
    assertViolation(mc, m, (short) 8);
    // Bad Json - only path (old format) so should fail parsing
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, new Text("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile"), new Value(fateId1.canonical()));
    assertViolation(mc, m, (short) 3100);
    // Bad Json - test startRow key is missing so validation should fail
    // {"path":"hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile","endRow":""}
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, new Text("{\"path\":\"hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile\",\"endRow\":\"\"}"), new Value(fateId1.canonical()));
    assertViolation(mc, m, (short) 3100);
    // Bad Json - test path key replaced with empty string so validation should fail
    // {"":"hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile","startRow":"","endRow":""}
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, new Text(StoredTabletFile.serialize("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile").replace("path", "")), new Value(fateId1.canonical()));
    assertViolation(mc, m, (short) 3100);
    // Bad Json - test path value missing
    // {"path":"","startRow":"","endRow":""}
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, new Text(StoredTabletFile.of(new Path("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile")).getMetadata().replaceFirst("\"path\":\".*\",\"startRow", "\"path\":\"\",\"startRow")), new Value(fateId1.canonical()));
    assertViolation(mc, m, (short) 3100);
    // Bad Json - test startRow key replaced with empty string so validation should fail
    // {"path":"hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile","":"","endRow":""}
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, new Text(StoredTabletFile.serialize("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile").replace("startRow", "")), new Value(fateId1.canonical()));
    assertViolation(mc, m, (short) 3100);
    // Bad Json - test endRow key missing so validation should fail
    m = new Mutation(new Text("0;foo"));
    m.put(BulkFileColumnFamily.NAME, new Text(StoredTabletFile.serialize("hdfs://1.2.3.4/accumulo/tables/2a/t-0003/someFile").replace("endRow", "")), new Value(fateId1.canonical()));
    assertViolation(mc, m, (short) 3100);
    // Bad Json - endRow will be replaced with encoded row without the exclusive byte 0x00 which is
    // required for an endRow so will fail validation
