@Test
public void testMergeabilityColumn() {
    MetadataConstraints mc = new MetadataConstraints();
    Mutation m;
    List<Short> violations;
    // Delay must be >= 0
    m = new Mutation(new Text("0;foo"));
    TabletColumnFamily.MERGEABILITY_COLUMN.put(m, new Value("{\"delay\":-1,\"steadyTime\":1,\"never\"=false}"));
    assertViolation(mc, m, (short) 4006);
    // SteadyTime must be null if never is true
    m = new Mutation(new Text("0;foo"));
    TabletColumnFamily.MERGEABILITY_COLUMN.put(m, new Value("{\"steadyTime\":1,\"never\"=true}"));
    assertViolation(mc, m, (short) 4006);
    // delay must be null if never is true
    m = new Mutation(new Text("0;foo"));
    TabletColumnFamily.MERGEABILITY_COLUMN.put(m, new Value("{\"delay\":1,\"never\"=true}"));
    assertViolation(mc, m, (short) 4006);
    // SteadyTime must be set if delay is set
    m = new Mutation(new Text("0;foo"));
    TabletColumnFamily.MERGEABILITY_COLUMN.put(m, new Value("{\"delay\":10,\"never\"=false}"));
    assertViolation(mc, m, (short) 4006);
    m = new Mutation(new Text("0;foo"));
    TabletColumnFamily.MERGEABILITY_COLUMN.put(m, TabletMergeabilityMetadata.toValue(TabletMergeabilityMetadata.never()));
    violations = mc.check(createEnv(), m);
    assertTrue(violations.isEmpty());
    m = new Mutation(new Text("0;foo"));
    TabletColumnFamily.MERGEABILITY_COLUMN.put(m, TabletMergeabilityMetadata.toValue(TabletMergeabilityMetadata.always(SteadyTime.from(1, TimeUnit.SECONDS))));
    violations = mc.check(createEnv(), m);
    assertTrue(violations.isEmpty());
    m = new Mutation(new Text("0;foo"));
    TabletColumnFamily.MERGEABILITY_COLUMN.put(m, TabletMergeabilityMetadata.toValue(TabletMergeabilityMetadata.after(Duration.ofDays(3), SteadyTime.from(Duration.ofHours(1)))));
    violations = mc.check(createEnv(), m);
    assertTrue(violations.isEmpty());
}

@Test
public void test() throws Exception {
    ServerMutation m = new ServerMutation(new Text("r1"));
    m.put(new Text("cf1"), new Text("cq1"), new Value("v1"));
    m.put(new Text("cf2"), new Text("cq2"), 56, new Value("v2"));
    m.setSystemTimestamp(42);
    List<ColumnUpdate> updates = m.getUpdates();
    assertEquals(2, updates.size());
    assertEquals("r1", new String(m.getRow(), UTF_8));
    ColumnUpdate cu = updates.get(0);
    assertEquals("cf1", new String(cu.getColumnFamily(), UTF_8));
    assertEquals("cq1", new String(cu.getColumnQualifier(), UTF_8));
    assertEquals("", new String(cu.getColumnVisibility(), UTF_8));
    assertFalse(cu.hasTimestamp());
    assertEquals(42L, cu.getTimestamp());
    ServerMutation m2 = new ServerMutation();
    ReflectionUtils.copy(new Configuration(), m, m2);
    updates = m2.getUpdates();
    assertEquals(2, updates.size());
    assertEquals("r1", new String(m2.getRow(), UTF_8));
    cu = updates.get(0);
    assertEquals("cf1", new String(cu.getColumnFamily(), UTF_8));
    assertEquals("cq1", new String(cu.getColumnQualifier(), UTF_8));
    assertFalse(cu.hasTimestamp());
    assertEquals(42L, cu.getTimestamp());
    cu = updates.get(1);
    assertEquals("r1", new String(m2.getRow(), UTF_8));
    assertEquals("cf2", new String(cu.getColumnFamily(), UTF_8));
    assertEquals("cq2", new String(cu.getColumnQualifier(), UTF_8));
    assertTrue(cu.hasTimestamp());
    assertEquals(56, cu.getTimestamp());
}

