@Test
public void testGetVolumeManagerConfiguration() throws Exception {
    final ConfigurationCopy accumuloConf = new ConfigurationCopy(DefaultConfiguration.getInstance());
    final Configuration hadoopConf = new Configuration();
    final String fileSystem = "file://127.0.0.1/vol1/";
    final Configuration volumeConfig = VolumeManagerImpl.getVolumeManagerConfiguration(accumuloConf, hadoopConf, fileSystem);
    assertSame(volumeConfig, hadoopConf);
    accumuloConf.set(Property.INSTANCE_VOLUME_CONFIG_PREFIX.getKey() + fileSystem + "." + DFS_CLIENT_CACHE_DROP_BEHIND_READS, "true");
    Configuration hadoopConf2 = new Configuration(hadoopConf);
    final Configuration volumeConfig2 = VolumeManagerImpl.getVolumeManagerConfiguration(accumuloConf, hadoopConf2, fileSystem);
    // false because of the additional property
    assertNotSame(volumeConfig2, hadoopConf);
    // false because of the additional property
    assertNotSame(volumeConfig, volumeConfig2);
    assertEquals("true", volumeConfig2.get(DFS_CLIENT_CACHE_DROP_BEHIND_READS));
    final Configuration volumeConfig3 = VolumeManagerImpl.getVolumeManagerConfiguration(accumuloConf, volumeConfig2, fileSystem);
    assertEquals("true", volumeConfig3.get(DFS_CLIENT_CACHE_DROP_BEHIND_READS));
    // false because of the different Hadoop configuration input
    assertNotSame(volumeConfig3, volumeConfig2);
    final Configuration volumeConfig4 = VolumeManagerImpl.getVolumeManagerConfiguration(accumuloConf, hadoopConf2, fileSystem);
    assertEquals("true", volumeConfig4.get(DFS_CLIENT_CACHE_DROP_BEHIND_READS));
    // true because of the same hadoop configuration input
