@Test
public void testRanges() throws IOException {
    TabletManagementIterator iter = new TabletManagementIterator();
    // We don't call init, so expect a IllegalStateException on success and
    // and IllegalArgumentException on failure
    Key goodStartKey = new Key("row");
    Key goodEndKey = new Key("rowEnd");
    Key badStartKey = new Key("row", "colf", "colq", 1234L);
    Key badEndKey = new Key("rowEnd", "colf", "colq", 1234L);
    assertThrows(NullPointerException.class, () -> iter.seek(null, Set.of(), false));
    assertThrows(NullPointerException.class, () -> iter.seek(new Range((Key) null, (Key) null), Set.of(), false));
    assertThrows(NullPointerException.class, () -> iter.seek(new Range(goodStartKey, goodEndKey), Set.of(), false));
    assertTrue(assertThrows(IllegalArgumentException.class, () -> iter.seek(new Range(goodStartKey, badEndKey), Set.of(), false)).getMessage().startsWith("TabletManagementIterator must be seeked"));
    assertTrue(assertThrows(IllegalArgumentException.class, () -> iter.seek(new Range(badStartKey, goodEndKey), Set.of(), false)).getMessage().startsWith("TabletManagementIterator must be seeked"));
    assertTrue(assertThrows(IllegalArgumentException.class, () -> iter.seek(new Range(badStartKey, badEndKey), Set.of(), false)).getMessage().startsWith("TabletManagementIterator must be seeked"));
}

