    secretManager.addKey(authKey2);
    expectLastCall().once();
    expect(secretManager.getCurrentKey()).andReturn(authKey2).once();
    replay(secretManager, zooDistributor);
    // Initialize the state from zookeeper
    keyManager.updateStateFromCurrentKeys();
