    // We don't know the exact lifetime, but we know that it can be no more than what was requested
    assertTrue(approximateLifetime <= cfg.getTokenLifetime(TimeUnit.MILLISECONDS), "Expected lifetime to be on thet order of the token lifetime, but was " + approximateLifetime);
}

