public void testQualifySessionId() throws KeeperException, InterruptedException {
    ClientContext ctx = createMock(ClientContext.class);
    ZooCache zc = createMock(ZooCache.class);
    String type = Constants.ZTSERVERS;
    String group = type + "/" + Constants.DEFAULT_RESOURCE_GROUP_NAME;
    String server = "localhost:12345";
    final long session = 123456789L;
    ServiceLockData sld1 = new ServiceLockData(UUID.randomUUID(), server, ThriftService.TABLET_SCAN, Constants.DEFAULT_RESOURCE_GROUP_NAME);
    String serverPath = group + "/" + server;
    String validZLockEphemeralNode = "zlock#" + UUID.randomUUID() + "#0000000000";
    expect(zc.getChildren(type)).andReturn(List.of(Constants.DEFAULT_RESOURCE_GROUP_NAME)).anyTimes();
    expect(zc.getChildren(group)).andReturn(List.of(server)).anyTimes();
    expect(zc.getChildren(serverPath)).andReturn(Collections.singletonList(validZLockEphemeralNode)).anyTimes();
    expect(zc.get(eq(serverPath + "/" + validZLockEphemeralNode), EasyMock.isA(ZcStat.class))).andReturn(sld1.serialize()).once();
    expect(zc.get(eq(serverPath + "/" + validZLockEphemeralNode), anyObject(ZcStat.class))).andAnswer(() -> {
        ZcStat stat = (ZcStat) getCurrentArguments()[1];
        stat.setEphemeralOwner(session);
        return new byte[0];
    });
    expect(ctx.getServerPaths()).andReturn(new ServiceLockPaths(zc)).anyTimes();
    replay(ctx, zc);
    assertEquals(server + "[" + Long.toHexString(session) + "]", Admin.qualifyWithZooKeeperSessionId(ctx, zc, server));
    verify(ctx, zc);
}

