    toBeRemoved[1] = gce.addCandidate("/+r/t0/F001.rf");
    toBeRemoved[2] = gce.addCandidate("/+r/t0/F002.rf");
    toBeRemoved[3] = gce.addCandidate("/+r/t0/F003.rf");
    gce.addFileReference("+r", null, "/t0/F000.rf");
