    assertEquals(Set.of(file1), job.getFiles());
    assertEquals(10L, queue.getLowestPriority());
    assertEquals(2, queue.getMaxSize());
    assertEquals(0, queue.getDequeuedJobs());
    assertEquals(0, queue.getRejectedJobs());
