    var cid2 = ExternalCompactionId.generate(UUID.randomUUID());
    var cid3 = ExternalCompactionId.generate(UUID.randomUUID());
    var tabletTime = MetadataTime.parse("L30");
    var flushID = OptionalLong.of(40);
    var availability = TabletAvailability.HOSTED;
    var lastLocation = TabletMetadata.Location.last("1.2.3.4:1234", "123456789");
    var suspendingTServer = SuspendingTServer.fromValue(new Value("1.2.3.4:5|56"));
    var mergeability = TabletMergeabilityMetadata.always(SteadyTime.from(1, TimeUnit.SECONDS));
    var tablet1 = TabletMetadata.builder(ke1).putOperation(opid).putDirName("td1").putFile(file3, dfv3).putTime(MetadataTime.parse("L3")).putTabletAvailability(TabletAvailability.HOSTED).putTabletMergeability(mergeability).build(LOCATION, LOGS, FILES, ECOMP, MERGED, COMPACTED, SELECTED, USER_COMPACTION_REQUESTED, LOADED, CLONED);
    var tablet2 = TabletMetadata.builder(ke2).putOperation(opid).putDirName("td2").putFile(file4, dfv4).putTime(MetadataTime.parse("L2")).putTabletAvailability(TabletAvailability.HOSTED).putTabletMergeability(mergeability).build(LOCATION, LOGS, FILES, ECOMP, MERGED, COMPACTED, SELECTED, USER_COMPACTION_REQUESTED, LOADED, CLONED);
    var tabletFiles = Map.of(file1, dfv1, file2, dfv2);
    var unsplittableMeta = UnSplittableMetadata.toUnSplittable(ke3, 1000, 1001, 10, tabletFiles.keySet());
    // Setup the metadata for the last tablet in the merge range, this is that tablet that merge
    // will modify.
    TabletMetadata lastTabletMeta = EasyMock.mock(TabletMetadata.class);
    EasyMock.expect(lastTabletMeta.getTableId()).andReturn(ke3.tableId()).anyTimes();
    EasyMock.expect(lastTabletMeta.getExtent()).andReturn(ke3).atLeastOnce();
