    tabletsToMinorCompact = mgr.tabletsToMinorCompact(tablets(t(k("a"), HALF_GIG, 0), t(k("b"), ONE_GIG + ONE_MEG, 0), t(k("c"), ONE_GIG + (2 * ONE_MEG), 0), t(k("d"), ONE_GIG + (3 * ONE_MEG), 0), t(k("e"), ONE_GIG + (4 * ONE_MEG), 0), t(k("f"), ONE_GIG, ONE_GIG + (5 * ONE_MEG)), t(k("g"), ONE_GIG, 0), t(k("h"), 0, 0), t(k("i"), 0, 0)));
