    assertEquals(0, tabletsToMinorCompact.size());
    // observe adjustment:
    mgr = new LargestFirstMemoryManagerUnderTest();
    mgr.init(context);
    // compact the largest
    tabletsToMinorCompact = mgr.tabletsToMinorCompact(tablets(t(k("a"), QGIG, 0), t(k("b"), QGIG + 1, 0), t(k("c"), QGIG + 2, 0)));
