    assertNoOtherChecksRan(out4, true, Admin.CheckCommand.Check.SYSTEM_CONFIG, Admin.CheckCommand.Check.ROOT_TABLE, Admin.CheckCommand.Check.USER_FILES);
    out1 = out1.replaceAll("\\s+", "");
