// This is an example test showing how to test a conditional
// mutation rejection handler by using a ConditionalWriterInterceptor
@ParameterizedTest
@ValueSource(booleans = { true, false })
public void testUnknownStatus(boolean accepted) throws Exception {
    String[] tableNames = getUniqueNames(2);
    String metadataTable = tableNames[0] + accepted;
    String userTable = tableNames[1] + accepted;
    try (ClientContext client = (ClientContext) Accumulo.newClient().from(getClientProps()).build()) {
        client.tableOperations().create(userTable);
        TestAmple.createMetadataTable(client, metadataTable);
        TableId tableId = TableId.of(client.tableOperations().tableIdMap().get(userTable));
        TestServerAmpleImpl ample = (TestServerAmpleImpl) TestAmple.create(getCluster().getServerContext(), Map.of(DataLevel.USER, metadataTable), () -> withStatus(ACCEPTED, UNKNOWN, 1));
        ample.createMetadataFromExisting(client, tableId);
        // Add a custom interceptor that will replace the result status with UNKNOWN
        // for only the first time the method is called instead of the actual state
        // (which should be accepted)
        //
        // When the result of UNKNOWN is returned, the mutator will trigger a retry
        // and resubmit the mutation. On retry, the mutation should be rejected because
        // the mutation requires an absent operation that will have already been set on
        // the previous submission.
        //
        // This will cause the mutator to check the rejection handler to see if we should actually
        // accept the mutation. This test uses a boolean to run twice to test both the
        // case of when the rejection handle will return true and false so that we can test that
        // the state is correctly set to either ACCEPTED or REJECTED after the rejection handler is
        // executed.
        try (var tabletsMutator = ample.conditionallyMutateTablets()) {
            var mutator = tabletsMutator.mutateTablet(new KeyExtent(tableId, null, null)).requireAbsentOperation();
            var fateId = FateId.from(FateInstanceType.USER, UUID.randomUUID());
            var opid = TabletOperationId.from(TabletOperationType.SPLITTING, fateId);
            mutator.putOperation(opid);
            // If accepted is true then we want to test the ACCEPTED case so return true if
            // the opid matches. If false we want this to fail to test REJECTED, so we return
            // false no matter what
            mutator.submit(afterMeta -> accepted && opid.equals(afterMeta.getOperationId()));
            var results = tabletsMutator.process();
            results.values().forEach(result -> {
                var status = result.getStatus();
                // check the state is correct
                Preconditions.checkState(accepted ? status == Status.ACCEPTED : status == Status.REJECTED, "Failed %s, %s", status, result.getExtent());
            });
        }
    }
}

/**
 * This test ensures that a tablet handles tablet time changing externally (like bulk import could
 * change tablet time).
 */
@Test
public void testTimeChanged() throws Exception {
    String[] tableNames = getUniqueNames(1);
    String metadataTable = tableNames[0];
    var tabletTime = TabletTime.getInstance(new MetadataTime(1, TimeType.LOGICAL));
    long flushNonce = 42L;
    try (var client = Accumulo.newClient().from(getClientProps()).build()) {
        client.tableOperations().create(metadataTable);
        TestAmple.create(getCluster().getServerContext(), Map.of(Ample.DataLevel.USER, metadataTable));
        Ample testAmple = TestAmple.create(getCluster().getServerContext(), Map.of(Ample.DataLevel.USER, metadataTable));
        assertNull(testAmple.readTablet(extent));
        // create tablet in the fake metadata table
        testAmple.mutateTablet(extent).putDirName("dir1").putTime(tabletTime.getMetadataTime()).putLocation(Location.current(tserverInstance)).putPrevEndRow(null).mutate();
        // get the tablets metadata
        var lastMetadata = testAmple.readTablet(extent);
        // update the tablets time, so it will differ
        testAmple.mutateTablet(extent).putTime(tabletTime.getMetadataTime(tabletTime.getTime() + 2)).mutate();
        tabletTime.updateTimeIfGreater(tabletTime.getTime() + 6);
        updateTabletDataFile(testAmple, tabletTime.getTime(), newFile, dfv1, Set.of(), 7L, MinorCompactionReason.SYSTEM, tserverInstance, extent, lastMetadata, tabletTime, flushNonce);
        var updatedMetadata = testAmple.readTablet(extent);
        assertEquals(Set.of(newFile.insert()), updatedMetadata.getFiles());
        assertEquals(tabletTime.getMetadataTime(), updatedMetadata.getTime());
        assertEquals(flushNonce, updatedMetadata.getFlushNonce().orElse(-1));
        client.tableOperations().delete(metadataTable);
    }
}

