/**
 * {@link org.apache.accumulo.test.functional.ScannerIT#testSessionCleanup(ScannerBase.ConsistencyLevel)}
 * is a similar test.
 */
@Test
public void testManyScans() throws Exception {
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        client.tableOperations().create(tableName);
        ReadWriteIT.ingest(client, ROWS, COLS, 50, 0, tableName);
        client.tableOperations().flush(tableName, null, null, true);
        Timer timer = Timer.startNew();
        int count = 0;
        while (count < 200 && timer.elapsed(TimeUnit.MILLISECONDS) < 3000) {
            try (Scanner scanner = createScanner(client, tableName, count)) {
                scanner.setRange(new Range());
                scanner.setReadaheadThreshold(count % 2 == 0 ? 0 : 3);
                for (int j = 0; j < count % 7 + 1; j++) {
                    // only read a little data and quit, this should leave a session open on the tserver
                    scanner.stream().limit(10).forEach(e -> {
                    });
                }
            }
            // when the scanner is closed, all open sessions should be closed
            count++;
        }
        log.debug("Ran {} scans in {} ms", count, timer.elapsed(TimeUnit.MILLISECONDS));
        // The goal of this test it to ensure the scanner client object closes server side scan
        // sessions and not idle session cleanup. To do this the test is making the following
        // assumptions about how Accumulo works to set the timings in this test :
        // 1. Sessions not closed by the scanner will be cleaned up in 20s based on config set before
        // starting test
        // 2. This test creates readahead threads for some scans. The presence of a thread will
        // prevent immediate cleanup of the server side scan session. So when the scanner sends the
        // RPC to close the session if a thread is present, then cleanup will be deferred. A scheduled
        // task in the tserver runs deferred cleanup every TSERV_SESSION_MAXIDLE/2 which is 10s.
        //
        // Putting the assumptions above together we know that if sessions are closed in less than
        // 20s, then they were closed as result of the scanner.close() method initiating an RPC to
        // remove the scan session. The 13s below allows time for the 10s deferred cleanup to run in
        // the case when a thread is present. The 3s cap the test puts on running scans sets the total
        // time the test will allow to 3s+13s=16s which is less than the 20s when idle session clean
        // starts.
        Wait.waitFor(() -> countActiveScans(client, ServerType.TABLET_SERVER, tableName) < 1, 13000, 250, "Found active scans after closing all scanners. Expected to find no scans");
        var elasped = timer.elapsed(TimeUnit.MILLISECONDS);
        if (elasped > 20000) {
            log.warn("Total time since first scan was run {}ms.  Unable to verify that scanner RPC closed " + "sessions, could have been closed by idle session cleanup.", elasped);
        } else {
            log.debug("Total time since first scan was run {}ms.", elasped);
        }
    }
}

@Test
public void testUsingMisconfiguredService() throws Exception {
    final AtomicBoolean shutdownTailer = new AtomicBoolean(false);
    final AtomicBoolean serviceMisconfigured = new AtomicBoolean(false);
    final Thread thread = Threads.createThread("metric-tailer", () -> {
        while (!shutdownTailer.get()) {
            List<String> statsDMetrics = sink.getLines();
            for (String s : statsDMetrics) {
                if (shutdownTailer.get()) {
                    break;
                }
                if (s.startsWith(COMPACTION_SVC_ERRORS.getName())) {
                    Metric m = TestStatsDSink.parseStatsDMetric(s);
                    Integer value = Integer.parseInt(m.getValue());
                    if (value == 0) {
                        serviceMisconfigured.set(false);
                    } else if (value == 1) {
                        serviceMisconfigured.set(true);
                    } else {
                        LOG.error("Invalid value received: " + m.getValue());
                    }
                }
            }
        }
    });
    thread.start();
    String table = getUniqueNames(1)[0];
    // Create a table that is configured to use a compaction service with bad configuration.
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        NewTableConfiguration ntc = new NewTableConfiguration().setProperties(Map.of(Property.TABLE_COMPACTION_DISPATCHER_OPTS.getKey() + "service", "cs1"));
        client.tableOperations().create(table, ntc);
        Wait.waitFor(() -> serviceMisconfigured.get() == true);
        try (var writer = client.createBatchWriter(table)) {
            writer.addMutation(new Mutation("0").at().family("f").qualifier("q").put("v"));
        }
        client.tableOperations().flush(table, null, null, true);
        try (var scanner = client.createScanner(table)) {
            assertEquals("0", scanner.stream().map(e -> e.getKey().getRowData().toString()).collect(MoreCollectors.onlyElement()));
        }
        Future<?> fixerFuture = executorService.submit(() -> {
            try {
                Thread.sleep(2000);
                // Verify the compaction has not run yet, it should not be able to with the bad config.
                try (var scanner = client.createScanner(table)) {
                    assertEquals("0", scanner.stream().map(e -> e.getKey().getRowData().toString()).collect(MoreCollectors.onlyElement()));
                }
                var value = "[{'group':'cs1q1'}]".replaceAll("'", "\"");
                client.instanceOperations().setProperty(CSP + "cs1.planner.opts.groups", value);
                // start the compactor, it was not started initially because of bad config
                ((MiniAccumuloClusterImpl) getCluster()).getConfig().getClusterServerConfiguration().addCompactorResourceGroup("cs1q1", 1);
                ((MiniAccumuloClusterImpl) getCluster()).getClusterControl().start(ServerType.COMPACTOR);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
        Wait.waitFor(() -> serviceMisconfigured.get() == false);
        List<IteratorSetting> iterators = Collections.singletonList(new IteratorSetting(100, EverythingFilter.class));
        client.tableOperations().compact(table, new CompactionConfig().setIterators(iterators).setWait(true));
        // Verify compaction ran.
        try (var scanner = client.createScanner(table)) {
            assertEquals(0, scanner.stream().count());
        }
        fixerFuture.get();
        // misconfigure the service, test how going from good config to bad config works. The test
        // started with an initial state of bad config.
        client.instanceOperations().setProperty(CSP + "cs1.planner.opts.groups", "]o.o[");
        Wait.waitFor(() -> serviceMisconfigured.get() == true);
        try (var writer = client.createBatchWriter(table)) {
            writer.addMutation(new Mutation("0").at().family("f").qualifier("q").put("v"));
        }
        client.tableOperations().flush(table, null, null, true);
        try (var scanner = client.createScanner(table)) {
            assertEquals("0", scanner.stream().map(e -> e.getKey().getRowData().toString()).collect(MoreCollectors.onlyElement()));
        }
        fixerFuture = executorService.submit(() -> {
            try {
                Thread.sleep(2000);
                var value = "[{'group':'cs1q1'}]".replaceAll("'", "\"");
                client.instanceOperations().setProperty(CSP + "cs1.planner.opts.groups", value);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
        Wait.waitFor(() -> serviceMisconfigured.get() == false);
        client.tableOperations().compact(table, new CompactionConfig().setIterators(iterators).setWait(true));
        // Verify compaction ran.
        try (var scanner = client.createScanner(table)) {
            assertEquals(0, scanner.stream().count());
        }
        fixerFuture.get();
    } finally {
        shutdownTailer.set(true);
        thread.join();
    }
}

