@Test
public void testQueueMetrics() throws Exception {
    long highestFileCount = 0L;
    ServerContext context = getCluster().getServerContext();
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        String dir = getDir("/testBulkFile-");
        FileSystem fs = getCluster().getFileSystem();
        fs.mkdirs(new Path(dir));
        // Create splits so there are two groupings of tablets with similar file counts.
        String splitString = "500 1000 1500 2000 3750 5500 7250 9000";
        addSplits(c, tableName, splitString);
        for (int i = 0; i < 100; i++) {
            writeData(dir + "/f" + i + ".", aconf, i * 100, (i + 1) * 100 - 1);
        }
        c.tableOperations().importDirectory(dir).to(tableName).load();
        IteratorSetting iterSetting = new IteratorSetting(100, CompactionIT.TestFilter.class);
        iterSetting.addOption("expectedQ", QUEUE1);
        iterSetting.addOption("modulus", 3 + "");
        CompactionConfig config = new CompactionConfig().setIterators(List.of(iterSetting)).setWait(false);
        c.tableOperations().compact(tableName, config);
        try (TabletsMetadata tm = context.getAmple().readTablets().forTable(tableId).build()) {
            // Get each tablet's file sizes
            for (TabletMetadata tablet : tm) {
                long fileSize = tablet.getFiles().size();
                log.info("Number of files in tablet {}: {}", tablet.getExtent().toString(), fileSize);
                highestFileCount = Math.max(highestFileCount, fileSize);
            }
        }
        verifyData(c, tableName, 0, 100 * 100 - 1, false);
    }
    boolean sawMetricsQ1 = false;
    boolean sawMetricsQ1Size = false;
    while (!sawMetricsQ1 || !sawMetricsQ1Size) {
        while (!queueMetrics.isEmpty()) {
            var qm = queueMetrics.take();
            if (qm.getName().contains(COMPACTOR_JOB_PRIORITY_QUEUE_JOBS_QUEUED.getName()) && qm.getTags().containsValue(QUEUE1_METRIC_LABEL)) {
                if (Integer.parseInt(qm.getValue()) > 0) {
                    sawMetricsQ1 = true;
                }
            }
            if (qm.getName().contains(COMPACTOR_JOB_PRIORITY_QUEUE_JOBS_SIZE.getName()) && qm.getTags().containsValue(QUEUE1_METRIC_LABEL)) {
                if (Integer.parseInt(qm.getValue()) > 0) {
                    sawMetricsQ1Size = true;
                }
            }
        }
        // If metrics are not found in the queue, sleep until the next poll.
        UtilWaitThread.sleep(TestStatsDRegistryFactory.pollingFrequency.toMillis());
    }
    // Set lowest priority to the lowest possible system compaction priority
    long lowestPriority = Short.MIN_VALUE;
    long rejectedCount = 0L;
    boolean sawQueues = false;
    // An empty queue means that the last known value is the most recent.
    while (!queueMetrics.isEmpty()) {
        var metric = queueMetrics.take();
        if (metric.getName().contains(COMPACTOR_JOB_PRIORITY_QUEUE_JOBS_REJECTED.getName()) && metric.getTags().containsValue(QUEUE1_METRIC_LABEL)) {
            rejectedCount = Long.parseLong(metric.getValue());
        } else if (metric.getName().contains(COMPACTOR_JOB_PRIORITY_QUEUE_JOBS_PRIORITY.getName()) && metric.getTags().containsValue(QUEUE1_METRIC_LABEL)) {
            lowestPriority = Math.max(lowestPriority, Long.parseLong(metric.getValue()));
        } else if (metric.getName().contains(COMPACTOR_JOB_PRIORITY_QUEUES.getName())) {
            sawQueues = true;
        } else {
            log.debug("{}", metric);
        }
    }
    // Confirm metrics were generated and in some cases, validate contents.
    assertTrue(rejectedCount > 0L);
    // Priority is the file counts + number of compactions for that tablet.
    // The lowestPriority job in the queue should have been
    // at least 1 count higher than the highest file count.
    TableId tid = context.getTableId(tableName);
    short highestFileCountPrio = CompactionJobPrioritizer.createPriority(getCluster().getServerContext().getNamespaceId(tid), tid, CompactionKind.USER, (int) highestFileCount, 0, context.getTableConfiguration(tid).getCount(Property.TABLE_FILE_MAX));
    assertTrue(lowestPriority > highestFileCountPrio, lowestPriority + " " + highestFileCount + " " + highestFileCountPrio);
    // Multiple Queues have been created
    assertTrue(sawQueues);
    // Start Compactors
    getCluster().getConfig().getClusterServerConfiguration().addCompactorResourceGroup(QUEUE1, 1);
    getCluster().getClusterControl().start(ServerType.COMPACTOR);
    boolean emptyQueue = false;
    // Make sure that metrics added to the queue are recent
    UtilWaitThread.sleep(TestStatsDRegistryFactory.pollingFrequency.toMillis());
    while (!emptyQueue) {
        while (!queueMetrics.isEmpty()) {
            var metric = queueMetrics.take();
            if (metric.getName().contains(COMPACTOR_JOB_PRIORITY_QUEUE_JOBS_QUEUED.getName()) && metric.getTags().containsValue(QUEUE1_METRIC_LABEL)) {
                if (Integer.parseInt(metric.getValue()) == 0) {
                    emptyQueue = true;
                }
            }
            // Check if the total number of queues is zero, if so then will not see metrics for the
            // above queue.
            if (metric.getName().equals(COMPACTOR_JOB_PRIORITY_QUEUES.getName())) {
                if (Integer.parseInt(metric.getValue()) == 0) {
                    emptyQueue = true;
                }
            }
        }
        UtilWaitThread.sleep(TestStatsDRegistryFactory.pollingFrequency.toMillis());
    }
}

/**
 * Test that the compaction queue is cleared when compactions no longer need to happen.
 */
@Test
public void testCompactionQueueClearedWhenNotNeeded() throws Exception {
    ServerContext context = getCluster().getServerContext();
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        String dir = getDir("/testBulkFile-");
        FileSystem fs = getCluster().getFileSystem();
        fs.mkdirs(new Path(dir));
        // Create splits so there are two groupings of tablets with similar file counts.
        String splitString = "500 1000 1500 2000 3750 5500 7250 9000";
        addSplits(c, tableName, splitString);
        for (int i = 0; i < 100; i++) {
            writeData(dir + "/f" + i + ".", aconf, i * 100, (i + 1) * 100 - 1);
        }
        c.tableOperations().importDirectory(dir).to(tableName).load();
        verifyData(c, tableName, 0, 100 * 100 - 1, false);
    }
    final long sleepMillis = TestStatsDRegistryFactory.pollingFrequency.toMillis();
    // wait for compaction jobs to be queued
    Wait.waitFor(() -> getJobsQueued() > 0, 60_000, sleepMillis, "Expected to see compaction jobs queued");
    // change compactor settings so that compactions no longer need to run
    context.tableOperations().setProperty(tableName, Property.TABLE_MAJC_RATIO.getKey(), "2000");
    context.tableOperations().setProperty(tableName, Property.TABLE_FILE_MAX.getKey(), "2000");
    // wait for queue to clear
    Wait.waitFor(() -> getJobsQueued() == 0, 60_000, sleepMillis, "Expected job queue to be cleared once compactions no longer need to happen");
}

@Test
public void testSplitCancelsExternalCompaction() throws Exception {
    String table1 = this.getUniqueNames(1)[0];
    try (AccumuloClient client = Accumulo.newClient().from(getCluster().getClientProperties()).build()) {
        createTable(client, table1, "cs1");
        TableId tid = getCluster().getServerContext().getTableId(table1);
        writeData(client, table1);
        compact(client, table1, 2, GROUP1, false);
        // Wait for the compaction to start by waiting for 1 external compaction column
        Set<ExternalCompactionId> ecids = ExternalCompactionTestUtils.waitForCompactionStartAndReturnEcids(getCluster().getServerContext(), tid);
        // Confirm that this ECID shows up in RUNNING set
        int matches = ExternalCompactionTestUtils.confirmCompactionRunning(getCluster().getServerContext(), ecids);
        assertTrue(matches > 0);
        // Verify that a tmp file is created
        Wait.waitFor(() -> FindCompactionTmpFiles.findTempFiles(getCluster().getServerContext(), tid.canonical()).size() == 1);
        // ExternalDoNothingCompactor will not compact, it will wait, split the table.
        SortedSet<Text> splits = new TreeSet<>();
        int jump = MAX_DATA / 5;
        for (int r = jump; r < MAX_DATA; r += jump) {
            splits.add(new Text(row(r)));
        }
        client.tableOperations().addSplits(table1, splits);
        confirmCompactionCompleted(getCluster().getServerContext(), ecids, TCompactionState.CANCELLED);
        // ensure compaction ids were deleted by split operation from metadata table
        try (TabletsMetadata tm = getCluster().getServerContext().getAmple().readTablets().forTable(tid).fetch(ColumnType.ECOMP).build()) {
            Set<ExternalCompactionId> ecids2 = tm.stream().flatMap(t -> t.getExternalCompactions().keySet().stream()).collect(Collectors.toSet());
            assertTrue(Collections.disjoint(ecids, ecids2));
        }
        // We need to cancel the compaction or delete the table here because we initiate a user
        // compaction above in the test. Even though the external compaction was cancelled
        // because we split the table, FaTE will continue to queue up a compaction
        client.tableOperations().cancelCompaction(table1);
        // Verify that the tmp file are cleaned up
        Wait.waitFor(() -> FindCompactionTmpFiles.findTempFiles(getCluster().getServerContext(), tid.canonical()).size() == 0, 60_000);
    }
}

@Test
public void testUserCompactionCancellation() throws Exception {
    String table1 = this.getUniqueNames(1)[0];
    try (AccumuloClient client = Accumulo.newClient().from(getCluster().getClientProperties()).build()) {
        createTable(client, table1, "cs3");
        TableId tid = getCluster().getServerContext().getTableId(table1);
        writeData(client, table1);
        AtomicReference<Throwable> error = new AtomicReference<>();
        Thread t = new Thread(() -> {
            try {
                compact(client, table1, 2, GROUP3, true);
            } catch (AccumuloSecurityException | TableNotFoundException | AccumuloException e) {
                error.set(e);
            }
        });
        t.start();
        // Wait for the compaction to start by waiting for 1 external compaction column
        Set<ExternalCompactionId> ecids = ExternalCompactionTestUtils.waitForCompactionStartAndReturnEcids(getCluster().getServerContext(), tid);
        // Confirm that this ECID shows up in RUNNING set
        int matches = ExternalCompactionTestUtils.confirmCompactionRunning(getCluster().getServerContext(), ecids);
        assertTrue(matches > 0);
        // Verify that a tmp file is created
        Wait.waitFor(() -> FindCompactionTmpFiles.findTempFiles(getCluster().getServerContext(), tid.canonical()).size() == 1);
        // when the compaction starts it will create a selected files column in the tablet, wait for
        // that to happen
        while (countTablets(getCluster().getServerContext(), table1, tm -> tm.getSelectedFiles() != null) == 0) {
            Thread.sleep(1000);
        }
        client.tableOperations().cancelCompaction(table1);
        t.join();
        Throwable e = error.get();
        assertNotNull(e);
        assertEquals(TableOperationsImpl.COMPACTION_CANCELED_MSG, e.getMessage());
        confirmCompactionCompleted(getCluster().getServerContext(), ecids, TCompactionState.CANCELLED);
        // ensure the canceled compaction deletes any tablet metadata related to the compaction
        while (countTablets(getCluster().getServerContext(), table1, tm -> tm.getSelectedFiles() != null || !tm.getCompacted().isEmpty()) > 0) {
            Thread.sleep(1000);
        }
        // Verify that the tmp file are cleaned up
        Wait.waitFor(() -> FindCompactionTmpFiles.findTempFiles(getCluster().getServerContext(), tid.canonical()).size() == 0);
    }
}

