@Test
public void testPartialCompaction() throws Exception {
    String tableName = getUniqueNames(1)[0];
    try (final AccumuloClient client = Accumulo.newClient().from(getCluster().getClientProperties()).build()) {
        createTable(client, tableName, "cs8");
        writeData(client, tableName);
        // This should create an A file
        compact(client, tableName, 17, GROUP8, true);
        verify(client, tableName, 17);
        try (BatchWriter bw = client.createBatchWriter(tableName)) {
            for (int i = MAX_DATA; i < MAX_DATA * 2; i++) {
                Mutation m = new Mutation(row(i));
                m.put("", "", "" + i);
                bw.addMutation(m);
            }
        }
        // this should create an F file
        client.tableOperations().flush(tableName);
        // run a compaction that only compacts F files
        IteratorSetting iterSetting = new IteratorSetting(100, TestFilter.class);
        // make sure iterator options make it to compactor process
        iterSetting.addOption("expectedQ", GROUP8);
        // compact F file w/ different modulus and user pmodulus option for partial compaction
        iterSetting.addOption("pmodulus", 19 + "");
        CompactionConfig config = new CompactionConfig().setIterators(List.of(iterSetting)).setWait(true).setSelector(new PluginConfig(FSelector.class.getName()));
        client.tableOperations().compact(tableName, config);
        assertNoCompactionMetadata(getCluster().getServerContext(), tableName);
        try (Scanner scanner = client.createScanner(tableName)) {
            int count = 0;
            for (Entry<Key, Value> entry : scanner) {
                int v = Integer.parseInt(entry.getValue().toString());
                int modulus = v < MAX_DATA ? 17 : 19;
                assertEquals(0, Integer.parseInt(entry.getValue().toString()) % modulus, String.format("%s %s %d != 0", entry.getValue(), "%", modulus));
                count++;
            }
            int expectedCount = 0;
            for (int i = 0; i < MAX_DATA * 2; i++) {
                int modulus = i < MAX_DATA ? 17 : 19;
                if (i % modulus == 0) {
                    expectedCount++;
                }
            }
            assertEquals(expectedCount, count);
        }
        // We need to cancel the compaction or delete the table here because we initiate a user
        // compaction above in the test. Even though the external compaction was cancelled
        // because we split the table, FaTE will continue to queue up a compaction
        client.tableOperations().cancelCompaction(tableName);
    }
}

@Test
public void testMergeCancelsExternalCompaction() throws Exception {
    String table1 = this.getUniqueNames(1)[0];
    try (AccumuloClient client = Accumulo.newClient().from(getCluster().getClientProperties()).build()) {
        getCluster().getClusterControl().stop(ServerType.COMPACTOR);
        getCluster().getClusterControl().start(ServerType.COMPACTOR, null, 1, ExternalDoNothingCompactor.class);
        createTable(client, table1, "cs1", 2);
        // set compaction ratio to 1 so that majc occurs naturally, not user compaction
        // user compaction blocks merge
        client.tableOperations().setProperty(table1, Property.TABLE_MAJC_RATIO.toString(), "1.0");
        // cause multiple rfiles to be created
        writeData(client, table1);
        writeData(client, table1);
        writeData(client, table1);
        writeData(client, table1);
        TableId tid = getCluster().getServerContext().getTableId(table1);
        // Wait for the compaction to start by waiting for 1 external compaction column
        Set<ExternalCompactionId> ecids = waitForCompactionStartAndReturnEcids(getCluster().getServerContext(), tid);
        var md = new ArrayList<TabletMetadata>();
        try (TabletsMetadata tm = getCluster().getServerContext().getAmple().readTablets().forTable(tid).fetch(ColumnType.PREV_ROW).build()) {
            tm.forEach(t -> md.add(t));
            assertEquals(2, md.size());
        }
        // Verify that a tmp file is created
        Wait.waitFor(() -> FindCompactionTmpFiles.findTempFiles(getCluster().getServerContext(), tid.canonical()).size() == 1);
        // Merge - blocking operation
        Text start = md.get(0).getPrevEndRow();
        Text end = md.get(1).getEndRow();
        client.tableOperations().merge(table1, start, end);
        confirmCompactionCompleted(getCluster().getServerContext(), ecids, TCompactionState.CANCELLED);
        // ensure compaction ids were deleted by merge operation from metadata table
        try (TabletsMetadata tm = getCluster().getServerContext().getAmple().readTablets().forTable(tid).fetch(ColumnType.ECOMP).build()) {
            Set<ExternalCompactionId> ecids2 = tm.stream().flatMap(t -> t.getExternalCompactions().keySet().stream()).collect(Collectors.toSet());
            // keep checking until test times out
            while (!Collections.disjoint(ecids, ecids2)) {
                UtilWaitThread.sleep(25);
                ecids2 = tm.stream().flatMap(t -> t.getExternalCompactions().keySet().stream()).collect(Collectors.toSet());
            }
        }
        // We need to cancel the compaction or delete the table here because we initiate a user
        // compaction above in the test. Even though the external compaction was cancelled
        // because we split the table, FaTE will continue to queue up a compaction
        client.tableOperations().delete(table1);
        // Verify that the tmp file are cleaned up
        Wait.waitFor(() -> FindCompactionTmpFiles.findTempFiles(getCluster().getServerContext(), tid.canonical()).size() == 0);
    } finally {
        getCluster().getClusterControl().stop(ServerType.COMPACTOR);
        getCluster().getClusterControl().start(ServerType.COMPACTOR);
    }
}

@Test
public void testCoordinatorRestartsDuringCompaction() throws Exception {
    String table1 = this.getUniqueNames(1)[0];
    try (AccumuloClient client = Accumulo.newClient().from(getCluster().getClientProperties()).build()) {
        createTable(client, table1, "cs2", 2);
        writeData(client, table1);
        IteratorSetting setting = new IteratorSetting(50, "slow", SlowIterator.class);
        SlowIterator.setSeekSleepTime(setting, 5000);
        SlowIterator.setSleepTime(setting, 5000);
        client.tableOperations().attachIterator(table1, setting, EnumSet.of(IteratorScope.majc));
        compact(client, table1, 2, GROUP2, false);
        TableId tid = getCluster().getServerContext().getTableId(table1);
        // Wait for the compaction to start by waiting for 1 external compaction column
        Set<ExternalCompactionId> ecids = waitForCompactionStartAndReturnEcids(getCluster().getServerContext(), tid);
        ServerContext ctx = getCluster().getServerContext();
        // Wait for all compactions to start
        Map<ExternalCompactionId, RunningCompactionInfo> originalRunningInfo = null;
        do {
            originalRunningInfo = getRunningCompactionInformation(ctx, ecids);
        } while (originalRunningInfo == null || originalRunningInfo.values().stream().allMatch(rci -> rci.duration == 0));
        Map<String, TExternalCompactionList> longestRunning = getLongRunningCompactions(ctx);
        assertTrue(longestRunning.containsKey(GROUP2));
        assertEquals(originalRunningInfo.size(), longestRunning.get(GROUP2).getCompactions().size());
        // Stop the Manager (Coordinator)
        getCluster().getClusterControl().stop(ServerType.MANAGER);
        // Restart the Manager while the compaction is running
        getCluster().getClusterControl().start(ServerType.MANAGER);
        Map<ExternalCompactionId, RunningCompactionInfo> postRestartRunningInfo = getRunningCompactionInformation(ctx, ecids);
        for (Entry<ExternalCompactionId, RunningCompactionInfo> post : postRestartRunningInfo.entrySet()) {
            if (originalRunningInfo.containsKey(post.getKey())) {
                assertTrue((post.getValue().duration - originalRunningInfo.get(post.getKey()).duration) > 0);
            }
            final String lastState = post.getValue().status;
            assertTrue(lastState.equals(TCompactionState.IN_PROGRESS.name()));
        }
        longestRunning = getLongRunningCompactions(ctx);
        assertTrue(longestRunning.containsKey(GROUP2));
        assertEquals(postRestartRunningInfo.size(), longestRunning.get(GROUP2).getCompactions().size());
        // We need to cancel the compaction or delete the table here because we initiate a user
        // compaction above in the test. Even though the external compaction was cancelled
        // because we split the table, FaTE will continue to queue up a compaction
        client.tableOperations().cancelCompaction(table1);
    }
}

@Test
public void test() throws Exception {
    final String tableName = getUniqueNames(1)[0];
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        c.tableOperations().create(tableName);
        TableId tid = TableId.of(c.tableOperations().tableIdMap().get(tableName));
        // majc should take 100 * .5 secs
        IteratorSetting it = new IteratorSetting(100, SlowIterator.class);
        SlowIterator.setSleepTime(it, 500);
        c.tableOperations().attachIterator(tableName, it, EnumSet.of(IteratorScope.majc));
        try (BatchWriter bw = c.createBatchWriter(tableName)) {
            for (int i = 0; i < 100; i++) {
                Mutation m = new Mutation("" + i);
                m.put("", "", new Value());
                bw.addMutation(m);
            }
            bw.flush();
        }
        // start majc
        final AtomicReference<Exception> ex = new AtomicReference<>();
        Thread thread = new Thread(() -> {
            try {
                c.tableOperations().compact(tableName, null, null, true, true);
            } catch (Exception e) {
                ex.set(e);
            }
        });
        thread.start();
        Set<ExternalCompactionId> compactionIds = ExternalCompactionTestUtils.waitForCompactionStartAndReturnEcids(getCluster().getServerContext(), tid);
        assertNotNull(compactionIds);
        assertEquals(1, compactionIds.size());
        long now = System.currentTimeMillis();
        Thread.sleep(SECONDS.toMillis(10));
        // split the table, interrupts the compaction
        SortedSet<Text> partitionKeys = new TreeSet<>();
        partitionKeys.add(new Text("10"));
        c.tableOperations().addSplits(tableName, partitionKeys);
        ExternalCompactionTestUtils.confirmCompactionCompleted(getCluster().getServerContext(), compactionIds, TCompactionState.CANCELLED);
        thread.join();
        // wait for the restarted compaction
        assertTrue(System.currentTimeMillis() - now > 59_000);
        if (ex.get() != null) {
            throw ex.get();
        }
    }
}

