        Wait.waitFor(() -> client.namespaceOperations().getNamespaceProperties(namespace).containsKey("table.custom.p1"));
        assertEquals(Map.of("table.custom.p1", "v1"), client.namespaceOperations().getNamespaceProperties(namespace));
        assertEquals(Map.of("table.custom.p2", "v2"), client.tableOperations().getTableProperties(table));
        assertTrue(client.tableOperations().getConfiguration(table).keySet().containsAll(Set.of("table.custom.p1", "table.custom.p2")));
        client.namespaceOperations().removeProperty(namespace, "table.custom.p1");
        // should not impact table prop
        client.namespaceOperations().removeProperty(namespace, "table.custom.p2");
        Wait.waitFor(() -> !client.namespaceOperations().getNamespaceProperties(namespace).containsKey("table.custom.p1"));
        assertEquals(Map.of(), client.namespaceOperations().getNamespaceProperties(namespace));
        assertEquals(Map.of("table.custom.p2", "v2"), client.tableOperations().getTableProperties(table));
        assertTrue(client.tableOperations().getConfiguration(table).containsKey("table.custom.p2"));
        client.namespaceOperations().rename(namespace, namespace + "2");
        assertFalse(client.namespaceOperations().exists(namespace));
        assertTrue(client.namespaceOperations().exists(namespace + "2"));
        assertFalse(client.tableOperations().exists(table));
        assertTrue(client.tableOperations().exists(table2));
        assertThrows(NamespaceNotEmptyException.class, () -> client.namespaceOperations().delete(namespace + "2"));
        client.tableOperations().delete(table2);
        client.namespaceOperations().delete(namespace + "2");
        assertFalse(client.namespaceOperations().exists(namespace + "2"));
    }
}

@Test
public void testCompaction() throws Exception {
    String table = getUniqueNames(1)[0];
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        var splits = new TreeSet<>(List.of(new Text(row(100)), new Text(row(200)), new Text(row(300))));
        client.tableOperations().create(table, new NewTableConfiguration().withSplits(splits));
        write(client, table, generateMutations(0, 100, tr -> true));
        // write no data to the tablet (100,200]
        write(client, table, generateMutations(201, 400, tr -> true));
        CompactionConfig compactionConfig = new CompactionConfig();
        compactionConfig.setSelector(new PluginConfig(NotThreeHundredSelector.class.getName()));
        var iterSetting = new IteratorSetting(200, "fam3", FamFilter.class);
        iterSetting.addOption("family", "3");
        compactionConfig.setIterators(List.of(iterSetting));
        compactionConfig.setWait(true);
        compactionConfig.setFlush(true);
        // This compaction will have one empty tablet and one tablet that is skipped by the selector.
        // There is special code for handling tablets with no files and marking them as compacted in
        // the fate operation which is why this case is tested. There is also special code in the fate
        // operation for handling tablets were the CompactionSelector plugin selects no files, so
        // testing that also.
        client.tableOperations().compact(table, compactionConfig);
        verifyData(client, table, AUTHORIZATIONS, generateKeys(0, 400, tr -> {
            if (tr.row < 100) {
                return tr.fam != 3;
            } else if (tr.row <= 200) {
                // this is the empty tablet
                return false;
            } else if (tr.row <= 300) {
                // this tablet was skipped by the selector, so the compaction should not have filtered any
                // of its data
                return true;
            } else {
                return tr.fam != 3;
            }
        }));
        // Test compaction over row range, should not filter anything outside of range.
        compactionConfig = new CompactionConfig();
        iterSetting = new IteratorSetting(200, "fam5", FamFilter.class);
        iterSetting.addOption("family", "5");
        compactionConfig.setIterators(List.of(iterSetting));
        compactionConfig.setStartRow(new Text(row(201))).setEndRow(new Text(row(300)));
        compactionConfig.setWait(true);
        client.tableOperations().compact(table, compactionConfig);
        verifyData(client, table, AUTHORIZATIONS, generateKeys(0, 400, tr -> {
            if (tr.row < 100) {
                return tr.fam != 3;
            } else if (tr.row <= 200) {
                return false;
            } else if (tr.row <= 300) {
                // the most recent compaction filtered out family 5 in only this tablet
                return tr.fam != 5;
            } else {
                return tr.fam != 3;
            }
        }));
    }
}

@Test
public void testBasic() throws Exception {
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        client.tableOperations().create(tableName);
        try (ConditionalWriter cw = client.createConditionalWriter(tableName);
            Scanner scanner = client.createScanner(tableName, Authorizations.EMPTY)) {
            // mutation conditional on column tx:seq not existing
            ConditionalMutation cm0 = new ConditionalMutation("99006", new Condition("tx", "seq"));
            cm0.put("name", "last", "doe");
            cm0.put("name", "first", "john");
            cm0.put("tx", "seq", "1");
            assertEquals(Status.ACCEPTED, cw.write(cm0).getStatus());
            assertEquals(Status.REJECTED, cw.write(cm0).getStatus());
            // mutation conditional on column tx:seq being 1
            ConditionalMutation cm1 = new ConditionalMutation("99006", new Condition("tx", "seq").setValue("1"));
            cm1.put("name", "last", "Doe");
            cm1.put("tx", "seq", "2");
            assertEquals(Status.ACCEPTED, cw.write(cm1).getStatus());
            // test condition where value differs
            ConditionalMutation cm2 = new ConditionalMutation("99006", new Condition("tx", "seq").setValue("1"));
            cm2.put("name", "last", "DOE");
            cm2.put("tx", "seq", "2");
            assertEquals(Status.REJECTED, cw.write(cm2).getStatus());
            // test condition where column does not exists
            ConditionalMutation cm3 = new ConditionalMutation("99006", new Condition("txtypo", "seq").setValue("1"));
            cm3.put("name", "last", "deo");
            cm3.put("tx", "seq", "2");
            assertEquals(Status.REJECTED, cw.write(cm3).getStatus());
            // test two conditions, where one should fail
            ConditionalMutation cm4 = new ConditionalMutation("99006", new Condition("tx", "seq").setValue("2"), new Condition("name", "last").setValue("doe"));
            cm4.put("name", "last", "deo");
            cm4.put("tx", "seq", "3");
            assertEquals(Status.REJECTED, cw.write(cm4).getStatus());
            // test two conditions, where one should fail
            ConditionalMutation cm5 = new ConditionalMutation("99006", new Condition("tx", "seq").setValue("1"), new Condition("name", "last").setValue("Doe"));
            cm5.put("name", "last", "deo");
            cm5.put("tx", "seq", "3");
            assertEquals(Status.REJECTED, cw.write(cm5).getStatus());
            // ensure rejected mutations did not write
            scanner.fetchColumn("name", "last");
            scanner.setRange(new Range("99006"));
            Entry<Key, Value> entry = getOnlyElement(scanner);
            assertEquals("Doe", entry.getValue().toString());
            // test w/ two conditions that are met
            ConditionalMutation cm6 = new ConditionalMutation("99006", new Condition("tx", "seq").setValue("2"), new Condition("name", "last").setValue("Doe"));
            cm6.put("name", "last", "DOE");
            cm6.put("tx", "seq", "3");
            assertEquals(Status.ACCEPTED, cw.write(cm6).getStatus());
            entry = getOnlyElement(scanner);
            assertEquals("DOE", entry.getValue().toString());
            // test a conditional mutation that deletes
            ConditionalMutation cm7 = new ConditionalMutation("99006", new Condition("tx", "seq").setValue("3"));
            cm7.putDelete("name", "last");
            cm7.putDelete("name", "first");
            cm7.putDelete("tx", "seq");
            assertEquals(Status.ACCEPTED, cw.write(cm7).getStatus());
            assertFalse(scanner.iterator().hasNext(), "Did not expect to find any results");
            // add the row back
            assertEquals(Status.ACCEPTED, cw.write(cm0).getStatus());
            assertEquals(Status.REJECTED, cw.write(cm0).getStatus());
            entry = getOnlyElement(scanner);
            assertEquals("doe", entry.getValue().toString());
        }
    }
}

@Test
public void testFields() throws Exception {
    try (AccumuloClient client1 = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        ClusterUser user1 = getUser(0);
        String user = user1.getPrincipal();
        if (saslEnabled()) {
            // The token is pointless for kerberos
            client1.securityOperations().createLocalUser(user, null);
        } else {
            client1.securityOperations().createLocalUser(user, new PasswordToken(user1.getPassword()));
        }
        Authorizations auths = new Authorizations("A", "B");
        client1.securityOperations().changeUserAuthorizations(user, auths);
        client1.securityOperations().grantSystemPermission(user, SystemPermission.CREATE_TABLE);
        try (AccumuloClient client2 = Accumulo.newClient().from(client1.properties()).as(user, user1.getToken()).build()) {
            client2.tableOperations().create(tableName);
            try (ConditionalWriter cw = client2.createConditionalWriter(tableName, new ConditionalWriterConfig().setAuthorizations(auths));
                Scanner scanner = client2.createScanner(tableName, auths)) {
                ColumnVisibility cva = new ColumnVisibility("A");
                ColumnVisibility cvb = new ColumnVisibility("B");
                ConditionalMutation cm0 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cva));
                cm0.put("name", "last", cva, "doe");
                cm0.put("name", "first", cva, "john");
                cm0.put("tx", "seq", cva, "1");
                assertEquals(Status.ACCEPTED, cw.write(cm0).getStatus());
                scanner.setRange(new Range("99006"));
                // verify we get the expected values that were written above
                Function<Scanner, Entry<Key, Value>> verifyValues = givenScanner -> {
                    Entry<Key, Value> result;
                    givenScanner.fetchColumn("name", "last");
                    result = getOnlyElement(givenScanner);
                    assertEquals("doe", result.getValue().toString());
                    givenScanner.clearColumns();
                    givenScanner.fetchColumn("name", "first");
                    result = getOnlyElement(givenScanner);
                    assertEquals("john", result.getValue().toString());
                    givenScanner.clearColumns();
                    givenScanner.fetchColumn("tx", "seq");
                    result = getOnlyElement(givenScanner);
                    assertEquals("1", result.getValue().toString());
                    givenScanner.clearColumns();
                    return result;
                };
                Entry<Key, Value> entry = verifyValues.apply(scanner);
                long ts = entry.getKey().getTimestamp();
                // test wrong colf
                ConditionalMutation cm1 = new ConditionalMutation("99006", new Condition("txA", "seq").setVisibility(cva).setValue("1"));
                cm1.put("name", "last", cva, "Doe");
                cm1.put("name", "first", cva, "John");
                cm1.put("tx", "seq", cva, "2");
                assertEquals(Status.REJECTED, cw.write(cm1).getStatus());
                // test wrong colq
                ConditionalMutation cm2 = new ConditionalMutation("99006", new Condition("tx", "seqA").setVisibility(cva).setValue("1"));
                cm2.put("name", "last", cva, "Doe");
                cm2.put("name", "first", cva, "John");
                cm2.put("tx", "seq", cva, "2");
                assertEquals(Status.REJECTED, cw.write(cm2).getStatus());
                // test wrong colv
                ConditionalMutation cm3 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cvb).setValue("1"));
                cm3.put("name", "last", cva, "Doe");
                cm3.put("name", "first", cva, "John");
                cm3.put("tx", "seq", cva, "2");
                assertEquals(Status.REJECTED, cw.write(cm3).getStatus());
                // test wrong timestamp
                ConditionalMutation cm4 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cva).setTimestamp(ts + 1).setValue("1"));
                cm4.put("name", "last", cva, "Doe");
                cm4.put("name", "first", cva, "John");
                cm4.put("tx", "seq", cva, "2");
                assertEquals(Status.REJECTED, cw.write(cm4).getStatus());
                // test wrong timestamp
                ConditionalMutation cm5 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cva).setTimestamp(ts - 1).setValue("1"));
                cm5.put("name", "last", cva, "Doe");
                cm5.put("name", "first", cva, "John");
                cm5.put("tx", "seq", cva, "2");
                assertEquals(Status.REJECTED, cw.write(cm5).getStatus());
                // ensure no updates were made
                var after = verifyValues.apply(scanner);
                assertEquals(ts, after.getKey().getTimestamp());
                // set all columns correctly
                ConditionalMutation cm6 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cva).setTimestamp(ts).setValue("1"));
                cm6.put("name", "last", cva, "Doe");
                cm6.put("name", "first", cva, "John");
                cm6.put("tx", "seq", cva, "2");
                assertEquals(Status.ACCEPTED, cw.write(cm6).getStatus());
                scanner.fetchColumn("tx", "seq");
                entry = getOnlyElement(scanner);
                assertEquals("2", entry.getValue().toString());
            }
        }
    }
}

@Test
public void testBadColVis() throws Exception {
    // test when a user sets a col vis in a condition that can never be seen
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        client.tableOperations().create(tableName);
        Authorizations auths = new Authorizations("A", "B");
        client.securityOperations().changeUserAuthorizations(getAdminPrincipal(), auths);
        Authorizations filteredAuths = new Authorizations("A");
        ColumnVisibility cva = new ColumnVisibility("A");
        ColumnVisibility cvb = new ColumnVisibility("B");
        ColumnVisibility cvc = new ColumnVisibility("C");
        try (ConditionalWriter cw = client.createConditionalWriter(tableName, new ConditionalWriterConfig().setAuthorizations(filteredAuths))) {
            // User has authorization, but didn't include it in the writer
            ConditionalMutation cm0 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cvb));
            cm0.put("name", "last", cva, "doe");
            cm0.put("name", "first", cva, "john");
            cm0.put("tx", "seq", cva, "1");
            assertEquals(Status.INVISIBLE_VISIBILITY, cw.write(cm0).getStatus());
            ConditionalMutation cm1 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cvb).setValue("1"));
            cm1.put("name", "last", cva, "doe");
            cm1.put("name", "first", cva, "john");
            cm1.put("tx", "seq", cva, "1");
            assertEquals(Status.INVISIBLE_VISIBILITY, cw.write(cm1).getStatus());
            // User does not have the authorization
            ConditionalMutation cm2 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cvc));
            cm2.put("name", "last", cva, "doe");
            cm2.put("name", "first", cva, "john");
            cm2.put("tx", "seq", cva, "1");
            assertEquals(Status.INVISIBLE_VISIBILITY, cw.write(cm2).getStatus());
            ConditionalMutation cm3 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cvc).setValue("1"));
            cm3.put("name", "last", cva, "doe");
            cm3.put("name", "first", cva, "john");
            cm3.put("tx", "seq", cva, "1");
            assertEquals(Status.INVISIBLE_VISIBILITY, cw.write(cm3).getStatus());
            // if any visibility is bad, good visibilities don't override
            ConditionalMutation cm4 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cvb), new Condition("tx", "seq").setVisibility(cva));
            cm4.put("name", "last", cva, "doe");
            cm4.put("name", "first", cva, "john");
            cm4.put("tx", "seq", cva, "1");
            assertEquals(Status.INVISIBLE_VISIBILITY, cw.write(cm4).getStatus());
            ConditionalMutation cm5 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cvb).setValue("1"), new Condition("tx", "seq").setVisibility(cva).setValue("1"));
            cm5.put("name", "last", cva, "doe");
            cm5.put("name", "first", cva, "john");
            cm5.put("tx", "seq", cva, "1");
            assertEquals(Status.INVISIBLE_VISIBILITY, cw.write(cm5).getStatus());
            ConditionalMutation cm6 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cvb).setValue("1"), new Condition("tx", "seq").setVisibility(cva));
            cm6.put("name", "last", cva, "doe");
            cm6.put("name", "first", cva, "john");
            cm6.put("tx", "seq", cva, "1");
            assertEquals(Status.INVISIBLE_VISIBILITY, cw.write(cm6).getStatus());
            ConditionalMutation cm7 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cvb), new Condition("tx", "seq").setVisibility(cva).setValue("1"));
            cm7.put("name", "last", cva, "doe");
            cm7.put("name", "first", cva, "john");
            cm7.put("tx", "seq", cva, "1");
            assertEquals(Status.INVISIBLE_VISIBILITY, cw.write(cm7).getStatus());
        }
        // test passing auths that exceed users configured auths
        Authorizations exceedingAuths = new Authorizations("A", "B", "D");
        try (ConditionalWriter cw2 = client.createConditionalWriter(tableName, new ConditionalWriterConfig().setAuthorizations(exceedingAuths))) {
            ConditionalMutation cm8 = new ConditionalMutation("99006", new Condition("tx", "seq").setVisibility(cvb), new Condition("tx", "seq").setVisibility(cva).setValue("1"));
            cm8.put("name", "last", cva, "doe");
            cm8.put("name", "first", cva, "john");
            cm8.put("tx", "seq", cva, "1");
            assertThrows(AccumuloSecurityException.class, () -> {
                Status status = cw2.write(cm8).getStatus();
                log.error("Writing mutation with Authorizations the user doesn't have should fail. Got " + "status: {}", status);
            });
        }
    }
}

@Test
public void testConstraints() throws Exception {
    // ensure constraint violations are properly reported
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        client.tableOperations().create(tableName);
        client.tableOperations().addConstraint(tableName, AlphaNumKeyConstraint.class.getName());
        client.tableOperations().clone(tableName, tableName + "_clone", true, new HashMap<>(), new HashSet<>());
        try (ConditionalWriter cw = client.createConditionalWriter(tableName + "_clone");
            Scanner scanner = client.createScanner(tableName + "_clone", new Authorizations())) {
            ConditionalMutation cm0 = new ConditionalMutation("99006+", new Condition("tx", "seq"));
            cm0.put("tx", "seq", "1");
            assertEquals(Status.VIOLATED, cw.write(cm0).getStatus());
            assertFalse(scanner.iterator().hasNext(), "Should find no results in the table is mutation result was violated");
            ConditionalMutation cm1 = new ConditionalMutation("99006", new Condition("tx", "seq"));
            cm1.put("tx", "seq", "1");
            assertEquals(Status.ACCEPTED, cw.write(cm1).getStatus());
            assertTrue(scanner.iterator().hasNext(), "Accepted result should be returned when reading table");
        }
    }
}

@Test
public void testIterators() throws Exception {
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        client.tableOperations().create(tableName, new NewTableConfiguration().withoutDefaultIterators());
        try (BatchWriter bw = client.createBatchWriter(tableName)) {
            Mutation m = new Mutation("ACCUMULO-1000");
            m.put("count", "comments", "1");
            bw.addMutation(m);
            bw.addMutation(m);
            bw.addMutation(m);
            m = new Mutation("ACCUMULO-1001");
            m.put("count2", "comments", "1");
            bw.addMutation(m);
            bw.addMutation(m);
            m = new Mutation("ACCUMULO-1002");
            m.put("count2", "comments", "1");
            bw.addMutation(m);
            bw.addMutation(m);
        }
        IteratorSetting iterConfig = new IteratorSetting(10, SummingCombiner.class);
        SummingCombiner.setEncodingType(iterConfig, Type.STRING);
        SummingCombiner.setColumns(iterConfig, Collections.singletonList(new IteratorSetting.Column("count")));
        IteratorSetting iterConfig2 = new IteratorSetting(10, SummingCombiner.class);
        SummingCombiner.setEncodingType(iterConfig2, Type.STRING);
        SummingCombiner.setColumns(iterConfig2, Collections.singletonList(new IteratorSetting.Column("count2", "comments")));
        IteratorSetting iterConfig3 = new IteratorSetting(5, VersioningIterator.class);
        VersioningIterator.setMaxVersions(iterConfig3, 1);
        try (Scanner scanner = client.createScanner(tableName, new Authorizations())) {
            scanner.addScanIterator(iterConfig);
            scanner.setRange(new Range("ACCUMULO-1000"));
            scanner.fetchColumn("count", "comments");
            Entry<Key, Value> entry = getOnlyElement(scanner);
            assertEquals("3", entry.getValue().toString());
            try (ConditionalWriter cw = client.createConditionalWriter(tableName)) {
                ConditionalMutation cm0 = new ConditionalMutation("ACCUMULO-1000", new Condition("count", "comments").setValue("3"));
                cm0.put("count", "comments", "1");
                assertEquals(Status.REJECTED, cw.write(cm0).getStatus());
                entry = getOnlyElement(scanner);
                assertEquals("3", entry.getValue().toString());
                ConditionalMutation cm1 = new ConditionalMutation("ACCUMULO-1000", new Condition("count", "comments").setIterators(iterConfig).setValue("3"));
                cm1.put("count", "comments", "1");
                assertEquals(Status.ACCEPTED, cw.write(cm1).getStatus());
                entry = getOnlyElement(scanner);
                assertEquals("4", entry.getValue().toString());
                ConditionalMutation cm2 = new ConditionalMutation("ACCUMULO-1000", new Condition("count", "comments").setValue("4"));
                cm2.put("count", "comments", "1");
                assertEquals(Status.REJECTED, cw.write(cm1).getStatus());
                entry = getOnlyElement(scanner);
                assertEquals("4", entry.getValue().toString());
                // run test with multiple iterators passed in same batch and condition with two iterators
                ConditionalMutation cm3 = new ConditionalMutation("ACCUMULO-1000", new Condition("count", "comments").setIterators(iterConfig).setValue("4"));
                cm3.put("count", "comments", "1");
                ConditionalMutation cm4 = new ConditionalMutation("ACCUMULO-1001", new Condition("count2", "comments").setIterators(iterConfig2).setValue("2"));
                cm4.put("count2", "comments", "1");
                ConditionalMutation cm5 = new ConditionalMutation("ACCUMULO-1002", new Condition("count2", "comments").setIterators(iterConfig2, iterConfig3).setValue("2"));
                cm5.put("count2", "comments", "1");
                Iterator<Result> results = cw.write(Arrays.asList(cm3, cm4, cm5).iterator());
                Map<String, Status> actual = new HashMap<>();
                while (results.hasNext()) {
                    Result result = results.next();
                    String k = new String(result.getMutation().getRow(), UTF_8);
                    assertFalse(actual.containsKey(k), "Did not expect to see multiple results for the row: " + k);
                    actual.put(k, result.getStatus());
                }
                Map<String, Status> expected = new HashMap<>();
                expected.put("ACCUMULO-1000", Status.ACCEPTED);
                expected.put("ACCUMULO-1001", Status.ACCEPTED);
                expected.put("ACCUMULO-1002", Status.REJECTED);
                assertEquals(expected, actual);
            }
        }
    }
}

@Test
public void testTableAndConditionIterators() throws Exception {
    // test w/ table that has iterators configured
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        IteratorSetting aiConfig1 = new IteratorSetting(30, "AI1", AddingIterator.class);
        aiConfig1.addOption("amount", "2");
        IteratorSetting aiConfig2 = new IteratorSetting(35, "MI1", MultiplyingIterator.class);
        aiConfig2.addOption("amount", "3");
        IteratorSetting aiConfig3 = new IteratorSetting(40, "AI2", AddingIterator.class);
        aiConfig3.addOption("amount", "5");
        client.tableOperations().create(tableName);
