            count = 0;
            results = cw.write(cml2.iterator());
            while (results.hasNext()) {
                Result result = results.next();
                assertEquals(Status.ACCEPTED, result.getStatus());
                count++;
            }
            assertEquals(num, count, "Did not receive the expected number of results");
        }
    }
}

