@Test
public void expireTest() throws Exception {
    // expect(parent.getUpdateCount()).andReturn(123L).anyTimes();
    replay(context);
    propStore.create(SystemPropKey.of(), Map.of(Property.TABLE_BLOOM_ENABLED.getKey(), "true"));
    var sysPropKey = SystemPropKey.of();
    TestListener testListener = new TestListener();
    propStore.registerAsListener(sysPropKey, testListener);
    ZooBasedConfiguration zbc = new SystemConfiguration(context, sysPropKey, parent);
    assertNotNull(zbc.getSnapshot());
    assertEquals("true", zbc.get(Property.TABLE_BLOOM_ENABLED));
    long updateCount = zbc.getUpdateCount();
    // advance well past unload period.
    ticker.advance(2, TimeUnit.HOURS);
    var tableBPropKey = TablePropKey.of(tidB);
    propStore.create(tableBPropKey, Map.of());
    Thread.sleep(150);
    int changeCount = testListener.getZkChangeCount();
    // force an "external update" directly in ZK - emulates a change external to the prop store.
    // just echoing the same data - but it will update the ZooKeeper node data version.
    Stat stat = new Stat();
    byte[] bytes = zrw.getData(sysPropKey.getPath(), stat);
    zrw.overwritePersistentData(sysPropKey.getPath(), bytes, stat.getVersion());
    // allow ZooKeeper notification time to propagate
    int retries = 5;
    do {
        Thread.sleep(25);
    } while (changeCount >= testListener.getZkChangeCount() && --retries > 0);
    assertTrue(changeCount < testListener.getZkChangeCount());
    // prop changed - but will not be loaded in cache.
    long updateCount2 = zbc.getUpdateCount();
    assertNotEquals(updateCount, updateCount2);
    // read will repopulate the cache.
    assertNotNull(zbc.getSnapshot());
    assertEquals("true", zbc.get(Property.TABLE_BLOOM_ENABLED));
    assertNotEquals(updateCount, zbc.getUpdateCount());
    assertEquals(updateCount2, zbc.getUpdateCount());
}

@Test
public void modifyPropTest() throws Exception {
    String[] names = getUniqueNames(2);
    String namespace = names[0];
    String table = namespace + "." + names[1];
    try (var client = Accumulo.newClient().from(getClientProps()).build()) {
        client.namespaceOperations().create(namespace);
        client.tableOperations().create(table);
        LOG.debug("Tables: {}", client.tableOperations().list());
        // override default in sys, and then over-ride that for table prop
        client.instanceOperations().setProperty(Property.TABLE_BLOOM_ENABLED.getKey(), "true");
        client.namespaceOperations().setProperty(namespace, Property.TABLE_BLOOM_ENABLED.getKey(), "true");
        client.tableOperations().setProperty(table, Property.TABLE_BLOOM_ENABLED.getKey(), "false");
        Wait.waitFor(() -> client.instanceOperations().getSystemConfiguration().get(Property.TABLE_BLOOM_ENABLED.getKey()).equals("true"), 5000, 500);
        ZooPropEditor tool = new ZooPropEditor();
        // before - check setup correct
        Wait.waitFor(() -> client.tableOperations().getTableProperties(table).get(Property.TABLE_BLOOM_ENABLED.getKey()).equals("false"), 5000, 500);
        // set table property (table.bloom.enabled=true)
        String[] setTablePropArgs = { "-p", getCluster().getAccumuloPropertiesPath(), "-t", table, "-s", Property.TABLE_BLOOM_ENABLED.getKey() + "=true" };
        tool.execute(setTablePropArgs);
        // after set - check prop changed in ZooKeeper
        Wait.waitFor(() -> client.tableOperations().getTableProperties(table).get(Property.TABLE_BLOOM_ENABLED.getKey()).equals("true"), 5000, 500);
        String[] deleteTablePropArgs = { "-p", getCluster().getAccumuloPropertiesPath(), "-t", table, "-d", Property.TABLE_BLOOM_ENABLED.getKey() };
        tool.execute(deleteTablePropArgs);
        // after delete - check map entry is null (removed from ZooKeeper)
        Wait.waitFor(() -> client.tableOperations().getTableProperties(table).get(Property.TABLE_BLOOM_ENABLED.getKey()) == null, 5000, 500);
        // set system property (changed from setup)
        Wait.waitFor(() -> client.instanceOperations().getSystemConfiguration().get(Property.TABLE_BLOOM_ENABLED.getKey()).equals("true"), 5000, 500);
        String[] setSystemPropArgs = { "-p", getCluster().getAccumuloPropertiesPath(), "-s", Property.TABLE_BLOOM_ENABLED.getKey() + "=false" };
        tool.execute(setSystemPropArgs);
        // after set - check map entry is false
        Wait.waitFor(() -> client.instanceOperations().getSystemConfiguration().get(Property.TABLE_BLOOM_ENABLED.getKey()).equals("false"), 5000, 500);
        // set namespace property (changed from setup)
        Wait.waitFor(() -> client.namespaceOperations().getNamespaceProperties(namespace).get(Property.TABLE_BLOOM_ENABLED.getKey()).equals("true"), 5000, 500);
        String[] setNamespacePropArgs = { "-p", getCluster().getAccumuloPropertiesPath(), "-ns", namespace, "-s", Property.TABLE_BLOOM_ENABLED.getKey() + "=false" };
        tool.execute(setNamespacePropArgs);
        // after set - check map entry is false
        Wait.waitFor(() -> client.namespaceOperations().getNamespaceProperties(namespace).get(Property.TABLE_BLOOM_ENABLED.getKey()).equals("false"), 5000, 500);
        String[] deleteNamespacePropArgs = { "-p", getCluster().getAccumuloPropertiesPath(), "-ns", namespace, "-d", Property.TABLE_BLOOM_ENABLED.getKey() };
        tool.execute(deleteNamespacePropArgs);
        // after set - check map entry is false
        Wait.waitFor(() -> client.namespaceOperations().getNamespaceProperties(namespace).get(Property.TABLE_BLOOM_ENABLED.getKey()) == null, 5000, 500);
    }
}

@Test
public void testCorruptMutation() throws Exception {
    String table = getUniqueNames(1)[0];
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        c.tableOperations().create(table);
        try (BatchWriter writer = c.createBatchWriter(table)) {
            Mutation m = new Mutation("1");
            m.put("f1", "q1", new Value("v1"));
            writer.addMutation(m);
        }
        var ctx = (ClientContext) c;
        var tableId = ctx.getTableId(table);
        var extent = new KeyExtent(tableId, null, null);
        var tabletMetadata = ctx.getAmple().readTablet(extent, TabletMetadata.ColumnType.LOCATION);
        var location = tabletMetadata.getLocation();
        assertNotNull(location);
        assertEquals(TabletMetadata.LocationType.CURRENT, location.getType());
        TabletIngestClientService.Iface client = ThriftUtil.getClient(ThriftClientTypes.TABLET_INGEST, location.getHostAndPort(), ctx);
        // Make the same RPC calls made by the BatchWriter, but pass a corrupt serialized mutation in
        // this try block.
        try {
            TInfo tinfo = TraceUtil.traceInfo();
            long sessionId = client.startUpdate(tinfo, ctx.rpcCreds(), TDurability.DEFAULT);
            // Write two valid mutations to the session. The tserver buffers data it receives via
            // applyUpdates and may not write them until closeUpdate RPC is called. Because
            // TSERV_TOTAL_MUTATION_QUEUE_MAX was set so small, these values should be written.
            client.applyUpdates(tinfo, sessionId, extent.toThrift(), List.of(createTMutation("abc", "z1"), createTMutation("def", "z2")));
            // Simulate data corruption in the serialized mutation
            TMutation badMutation = createTMutation("ghi", "z3");
            badMutation.entries = -42;
            // Write some good and bad mutations to the session. The server side will see an error here,
            // however since this is a thrift oneway method no exception is expected here. This should
            // leave the session in a broken state where it no longer accepts any new data.
            client.applyUpdates(tinfo, sessionId, extent.toThrift(), List.of(createTMutation("jkl", "z4"), badMutation, createTMutation("mno", "z5")));
            // Write two more valid mutations to the session, these should be dropped on the server side
            // because of the previous error. So should never see these updates.
            client.applyUpdates(tinfo, sessionId, extent.toThrift(), List.of(createTMutation("pqr", "z6"), createTMutation("stu", "z7")));
            // Since client.applyUpdates experienced an error, should see an error when closing the
            // session.
            assertThrows(TApplicationException.class, () -> client.closeUpdate(tinfo, sessionId));
        } finally {
            ThriftUtil.returnClient((TServiceClient) client, ctx);
        }
        // The values that a scan must see
        Set<String> expectedValues = Set.of("v1", "v2", "z1", "z2");
        // The failed mutation should not have left the tablet in a bad state. Do some follow-on
        // actions to ensure the tablet is still functional.
        try (BatchWriter writer = c.createBatchWriter(table)) {
            Mutation m = new Mutation("2");
            m.put("f1", "q1", new Value("v2"));
            writer.addMutation(m);
        }
        try (Scanner scanner = c.createScanner(table)) {
            var valuesSeen = scanner.stream().map(e -> e.getValue().toString()).collect(Collectors.toSet());
            assertEquals(expectedValues, valuesSeen);
        }
        c.tableOperations().flush(table, null, null, true);
        try (Scanner scanner = c.createScanner(table)) {
            var valuesSeen = scanner.stream().map(e -> e.getValue().toString()).collect(Collectors.toSet());
            assertEquals(expectedValues, valuesSeen);
        }
    }
}

@Test
public void compareOldNewBulkImportTest() throws Exception {
    try (AccumuloClient c = Accumulo.newClient().from(getClientProperties()).build()) {
        getCluster().getClusterControl().kill(ServerType.GARBAGE_COLLECTOR, "localhost");
        final String tableName = getUniqueNames(1)[0];
        // disable compactions
        Map<String, String> props = new HashMap<>();
        props.put(Property.TABLE_MAJC_RATIO.getKey(), "2000");
        props.put(Property.TABLE_FILE_MAX.getKey(), "2000");
        props.put(Property.TABLE_FILE_PAUSE.getKey(), "2000");
        // splits to slow down bulk import
        SortedSet<Text> splits = new TreeSet<>();
        for (int i = 1; i < 0xf; i++) {
            splits.add(new Text(Integer.toHexString(i)));
        }
        var ntc = new NewTableConfiguration().setProperties(props).withSplits(splits);
        c.tableOperations().create(tableName, ntc);
        ManagerMonitorInfo stats = getCluster().getManagerMonitorInfo();
        assertEquals(1, stats.tServerInfo.size());
        log.info("Creating lots of bulk import files");
        final FileSystem fs = getCluster().getFileSystem();
        final Path basePath = getCluster().getTemporaryPath();
        final Path base = new Path(basePath, "testBulkLoad" + tableName);
        fs.delete(base, true);
        fs.mkdirs(base);
        ExecutorService es = Executors.newFixedThreadPool(5);
        List<Future<String>> futures = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            final int which = i;
            futures.add(es.submit(() -> {
                Path files = new Path(base, "files" + which);
                fs.mkdirs(files);
                for (int i1 = 0; i1 < 100; i1++) {
                    FileSKVWriter writer = FileOperations.getInstance().newWriterBuilder().forFile(UnreferencedTabletFile.of(fs, new Path(files + "/bulk_" + i1 + "." + RFile.EXTENSION)), fs, fs.getConf(), NoCryptoServiceFactory.NONE).withTableConfiguration(DefaultConfiguration.getInstance()).build();
                    writer.startDefaultLocalityGroup();
                    for (int j = 0x100; j < 0xfff; j += 3) {
                        writer.append(new Key(Integer.toHexString(j)), new Value());
                    }
                    writer.close();
                }
                return files.toString();
            }));
        }
        List<String> dirs = new ArrayList<>();
        for (Future<String> f : futures) {
            dirs.add(f.get());
        }
        log.info("Importing");
        long startOps = getStat(getStats(), "FileInfoOps");
        long now = System.currentTimeMillis();
        List<Future<Object>> errs = new ArrayList<>();
        for (String dir : dirs) {
            errs.add(es.submit(() -> {
                c.tableOperations().importDirectory(dir).to(tableName).load();
                return null;
            }));
        }
        for (Future<Object> err : errs) {
            err.get();
        }
        es.shutdown();
        es.awaitTermination(2, MINUTES);
        log.info(String.format("Completed in %.2f seconds", (System.currentTimeMillis() - now) / 1000.));
        Thread.sleep(SECONDS.toMillis(30));
        Map<?, ?> map = getStats();
        map.forEach((k, v) -> {
            try {
                if (v != null && Double.parseDouble(v.toString()) > 0.0) {
                    log.debug("{}:{}", k, v);
                }
            } catch (NumberFormatException e) {
                // only looking for numbers
            }
        });
        long getFileInfoOpts = getStat(map, "FileInfoOps") - startOps;
        log.info("New bulk import used {} opts, vs old using 2060", getFileInfoOpts);
        // counts for old bulk import:
        // Expected number of FileInfoOps was between 1000 and 2100
        // new bulk import is way better :)
        assertEquals(20, getFileInfoOpts, "unexpected number of FileInfoOps");
    }
}

