@ParameterizedTest
@EnumSource(value = MergeInfo.Operation.class, names = { "MERGE", "DELETE" })
public void testNoWalsMergeRepos(MergeInfo.Operation operation) throws Exception {
    String[] tableNames = getUniqueNames(2);
    String metadataTable = tableNames[0] + operation;
    String userTable = tableNames[1] + operation;
    try (ClientContext client = (ClientContext) Accumulo.newClient().from(getClientProps()).build()) {
        client.tableOperations().create(userTable);
        TableId tableId = TableId.of(client.tableOperations().tableIdMap().get(userTable));
        // Set up Test ample and manager
        TestAmple.createMetadataTable(client, metadataTable);
        TestServerAmpleImpl testAmple = (TestServerAmpleImpl) TestAmple.create(getCluster().getServerContext(), Map.of(DataLevel.USER, metadataTable));
        testAmple.createMetadataFromExisting(client, tableId);
        Manager manager = mockWithAmple(getCluster().getServerContext(), testAmple);
        // Create a test operation and fate id for testing merge and delete rows
        // and add operation to test metadata for the tablet
        var fateId = FateId.from(FateInstanceType.USER, UUID.randomUUID());
        var opid = TabletOperationId.from(TabletOperationType.MERGING, fateId);
        var extent = new KeyExtent(tableId, null, null);
        try (TabletsMutator tm = testAmple.mutateTablets()) {
            tm.mutateTablet(extent).putOperation(opid).mutate();
        }
        // Build either MergeTablets or DeleteRows repo for testing no WALs, both should check this
        // condition
        final MergeInfo mergeInfo = new MergeInfo(tableId, manager.getContext().getNamespaceId(tableId), null, null, operation);
        final ManagerRepo repo = operation == Operation.MERGE ? new MergeTablets(mergeInfo) : new DeleteRows(mergeInfo);
        // Also test ReserveTablets isReady()
        final ManagerRepo reserve = new ReserveTablets(mergeInfo);
        // First, check no errors with the default case
        assertEquals(0, reserve.isReady(fateId, manager));
        assertNotNull(repo.call(fateId, manager));
        // Write a WAL to the test metadata and then re-run the repo to check for an error
        try (TabletsMutator tm = testAmple.mutateTablets()) {
            var walFilePath = Path.of("tserver+8080", UUID.randomUUID().toString()).toString();
            tm.mutateTablet(extent).putWal(LogEntry.fromPath(walFilePath)).mutate();
        }
        // Should not be ready due to the presence of a WAL
        assertTrue(reserve.isReady(fateId, manager) > 0);
        // Repo should throw an exception due to the WAL existence
        var thrown = assertThrows(IllegalStateException.class, () -> repo.call(fateId, manager));
        assertTrue(thrown.getMessage().contains("has unexpected walogs"));
    }
}

@Test
public void testVerifyMergeability() throws Exception {
    String[] tableNames = getUniqueNames(2);
    String metadataTable = tableNames[0];
    String userTable = tableNames[1];
    try (ClientContext client = (ClientContext) Accumulo.newClient().from(getClientProps()).build()) {
        SortedMap<Text, TabletMergeability> splits = new TreeMap<>();
        splits.put(new Text("a"), TabletMergeability.always());
        splits.put(new Text("b"), TabletMergeability.always());
        splits.put(new Text("c"), TabletMergeability.never());
        splits.put(new Text("d"), TabletMergeability.after(Duration.ofDays(2)));
        splits.put(new Text("e"), TabletMergeability.always());
        client.tableOperations().create(userTable, new NewTableConfiguration().setProperties(Map.of(Property.TABLE_SPLIT_THRESHOLD.getKey(), "10K", Property.TABLE_MAJC_RATIO.getKey(), "9999", Property.TABLE_MERGE_FILE_MAX.getKey(), "10")).withSplits(splits));
        TableId tableId = TableId.of(client.tableOperations().tableIdMap().get(userTable));
        // Set up Test ample and manager
        TestAmple.createMetadataTable(client, metadataTable);
        TestServerAmpleImpl testAmple = (TestServerAmpleImpl) TestAmple.create(getCluster().getServerContext(), Map.of(DataLevel.USER, metadataTable));
        testAmple.createMetadataFromExisting(client, tableId);
        Manager manager = mockWithAmple(getCluster().getServerContext(), testAmple, Duration.ofDays(1));
        // Create a test fate id
        var fateId = FateId.from(FateInstanceType.USER, UUID.randomUUID());
        // Tablet c is set to never merge
        MergeInfo mergeInfo = new MergeInfo(tableId, manager.getContext().getNamespaceId(tableId), null, new Text("c").getBytes(), Operation.SYSTEM_MERGE);
        var repo = new VerifyMergeability(mergeInfo).call(fateId, manager);
        assertInstanceOf(UnreserveSystemMerge.class, repo);
        assertEquals(UnmergeableReason.TABLET_MERGEABILITY, ((UnreserveSystemMerge) repo).getReason());
        // Tablets a and b are always merge
        mergeInfo = new MergeInfo(tableId, manager.getContext().getNamespaceId(tableId), null, new Text("b").getBytes(), Operation.SYSTEM_MERGE);
        assertInstanceOf(MergeTablets.class, new VerifyMergeability(mergeInfo).call(fateId, manager));
        var context = manager.getContext();
        // split threshold is 10k so default max merge size is 2500 bytes.
        // this adds 6 files of 450 each which puts the tablets over teh 2500 threshold
        addFileMetadata(context, tableId, null, new Text("c"), 3, 450);
        // Data written to the first two tablets totals 2700 bytes and is too large
        repo = new VerifyMergeability(mergeInfo).call(fateId, manager);
        assertInstanceOf(UnreserveSystemMerge.class, repo);
        assertEquals(UnmergeableReason.MAX_TOTAL_SIZE, ((UnreserveSystemMerge) repo).getReason());
        // Not enough time has passed for Tablet, should be able to merge d and e
        mergeInfo = new MergeInfo(tableId, manager.getContext().getNamespaceId(tableId), new Text("c").getBytes(), new Text("e").getBytes(), Operation.SYSTEM_MERGE);
        repo = new VerifyMergeability(mergeInfo).call(fateId, manager);
        assertInstanceOf(UnreserveSystemMerge.class, repo);
        assertEquals(UnmergeableReason.TABLET_MERGEABILITY, ((UnreserveSystemMerge) repo).getReason());
        // update time to 3 days so enough time has passed
        manager = mockWithAmple(getCluster().getServerContext(), testAmple, Duration.ofDays(3));
        assertInstanceOf(MergeTablets.class, new VerifyMergeability(mergeInfo).call(fateId, manager));
        // last 3 tablets should total 9 files which is < max of 10
        mergeInfo = new MergeInfo(tableId, manager.getContext().getNamespaceId(tableId), new Text("c").getBytes(), null, Operation.SYSTEM_MERGE);
        addFileMetadata(context, tableId, new Text("c"), null, 3, 10);
        assertInstanceOf(MergeTablets.class, new VerifyMergeability(mergeInfo).call(fateId, manager));
        // last 3 tablets should total 12 files which is > max of 10
        addFileMetadata(context, tableId, new Text("c"), null, 4, 10);
        repo = new VerifyMergeability(mergeInfo).call(fateId, manager);
        assertInstanceOf(UnreserveSystemMerge.class, repo);
        assertEquals(UnmergeableReason.MAX_FILE_COUNT, ((UnreserveSystemMerge) repo).getReason());
    }
}

@Test
public void testSplitOffline() throws Exception {
    String[] tableNames = getUniqueNames(2);
    String metadataTable = tableNames[0];
    String userTable = tableNames[1];
    // This test ensures a repo involved in splitting a tablet handles an offline table correctly
    try (ClientContext client = (ClientContext) Accumulo.newClient().from(getClientProps()).build()) {
        TestAmple.createMetadataTable(client, metadataTable);
        // create a new table that is initially offline
        client.tableOperations().create(userTable, new NewTableConfiguration().createOffline());
        TableId tableId = TableId.of(client.tableOperations().tableIdMap().get(userTable));
        TestServerAmpleImpl testAmple = (TestServerAmpleImpl) TestAmple.create(getCluster().getServerContext(), Map.of(DataLevel.USER, metadataTable));
        testAmple.createMetadataFromExisting(client, tableId, not(SplitColumnFamily.UNSPLITTABLE_COLUMN));
        var fateId = FateId.from(FateInstanceType.USER, UUID.randomUUID());
        KeyExtent extent = new KeyExtent(tableId, null, null);
        // manually set an operation id on the tablet
        var opid = TabletOperationId.from(TabletOperationType.SPLITTING, fateId);
        testAmple.mutateTablet(extent).putOperation(TabletOperationId.from(TabletOperationType.SPLITTING, fateId)).mutate();
        Manager manager = mockWithAmple(getCluster().getServerContext(), testAmple);
        assertEquals(opid, testAmple.readTablet(extent).getOperationId());
        var eoRepo = new AllocateDirsAndEnsureOnline(new SplitInfo(extent, TabletMergeabilityUtil.systemDefaultSplits(new TreeSet<>(List.of(new Text("sp1"))))));
        // The repo should delete the opid and throw an exception
        assertThrows(ThriftTableOperationException.class, () -> eoRepo.call(fateId, manager));
        // the operation id should have been cleaned up before the exception was thrown
        assertNull(testAmple.readTablet(extent).getOperationId());
    }
}

@Test
public void testFindSplitsUnsplittable() throws Exception {
    String[] tableNames = getUniqueNames(2);
    String metadataTable = tableNames[0];
    String userTable = tableNames[1];
    try (ClientContext client = (ClientContext) Accumulo.newClient().from(getClientProps()).build()) {
        TestAmple.createMetadataTable(client, metadataTable);
        // Create table with a smaller max end row size
        createUnsplittableTable(client, userTable);
        populateUnsplittableTable(client, userTable);
        TableId tableId = TableId.of(client.tableOperations().tableIdMap().get(userTable));
        TestServerAmpleImpl testAmple = (TestServerAmpleImpl) TestAmple.create(getCluster().getServerContext(), Map.of(DataLevel.USER, metadataTable), () -> withStatus(ACCEPTED, UNKNOWN, 1));
        // Prevent UNSPLITTABLE_COLUMN just in case a system split tried to run on the table
        // before we copied it and inserted the column
        testAmple.createMetadataFromExisting(client, tableId, not(SplitColumnFamily.UNSPLITTABLE_COLUMN));
        KeyExtent extent = new KeyExtent(tableId, null, null);
        Manager manager = mockWithAmple(getCluster().getServerContext(), testAmple);
        FindSplits findSplits = new FindSplits(extent);
        PreSplit preSplit = (PreSplit) findSplits.call(FateId.from(FateInstanceType.USER, UUID.randomUUID()), manager);
        // The table should not need splitting
        assertNull(preSplit);
        // Verify metadata has unsplittable column
        var metadata = testAmple.readTablet(new KeyExtent(tableId, null, null)).getUnSplittable();
        assertNotNull(metadata);
        // Bump max end row size and verify split occurs and unsplittable column is cleaned up
        client.tableOperations().setProperty(userTable, Property.TABLE_MAX_END_ROW_SIZE.getKey(), "500");
        findSplits = new FindSplits(extent);
        preSplit = (PreSplit) findSplits.call(FateId.from(FateInstanceType.USER, UUID.randomUUID()), manager);
        // The table SHOULD now need splitting
        assertNotNull(preSplit);
        // Verify unsplittable metadata is still the same and exists
        // This will not be cleared until the UpdateTablets repo runs
        // so if the test is updated to test UpdateTablets this can be checked
        assertEquals(metadata, testAmple.readTablet(new KeyExtent(tableId, null, null)).getUnSplittable());
    }
}

