@ParameterizedTest
@MethodSource("compactionDriverRanges")
public void testCompactionDriverCleanup(Pair<Text, Text> rangeText) throws Exception {
    // Create a range for the test and generate table names
    String[] tableNames = getUniqueNames(2);
    var range = new Range(rangeText.getFirst(), true, rangeText.getSecond(), false);
    var tableSuffix = (range.isInfiniteStartKey() ? "" : rangeText.getFirst().toString()) + (range.isInfiniteStopKey() ? "" : rangeText.getSecond().toString());
    String metadataTable = tableNames[0] + tableSuffix;
    String userTable = tableNames[1] + tableSuffix;
    try (ClientContext client = (ClientContext) Accumulo.newClient().from(getClientProps()).build()) {
        // Create a table with 4 splits
        var splits = Sets.newTreeSet(Arrays.asList(new Text("d"), new Text("m"), new Text("s")));
        client.tableOperations().create(userTable, new NewTableConfiguration().withSplits(splits));
        TableId tableId = TableId.of(client.tableOperations().tableIdMap().get(userTable));
        // Set up Test ample and manager
        TestAmple.createMetadataTable(client, metadataTable);
        TestServerAmpleImpl testAmple = (TestServerAmpleImpl) TestAmple.create(getCluster().getServerContext(), Map.of(DataLevel.USER, metadataTable));
        testAmple.createMetadataFromExisting(client, tableId);
        Manager manager = mockWithAmple(getCluster().getServerContext(), testAmple);
        var ctx = manager.getContext();
        // Create the CompactionDriver to test with the given range passed into the method
        final ManagerRepo repo = new CompactionDriver(ctx.getNamespaceId(tableId), tableId, !range.isInfiniteStartKey() ? range.getStartKey().getRow().getBytes() : null, !range.isInfiniteStopKey() ? range.getEndKey().getRow().getBytes() : null);
        // Create a couple random fateIds and generate compaction metadata for
        // the first fateId for all 4 tablets in the table
        var fateId1 = FateId.from(FateInstanceType.USER, UUID.randomUUID());
        var fateId2 = FateId.from(FateInstanceType.USER, UUID.randomUUID());
        createCompactionMetadata(testAmple, tableId, fateId1);
        // Verify there are 4 tablets and each tablet has compaction metadata generated
        // for the first fateId and store all the extents in a set
        Set<KeyExtent> extents = new HashSet<>();
        try (TabletsMetadata tabletsMetadata = testAmple.readTablets().forTable(tableId).build()) {
            assertEquals(4, tabletsMetadata.stream().count());
            tabletsMetadata.forEach(tm -> {
                extents.add(tm.getExtent());
                assertHasCompactionMetadata(fateId1, tm);
            });
        }
        assertEquals(4, extents.size());
        // First call undo using the second fateId and verify there's still metadata for the first one
        repo.undo(fateId2, manager);
        try (TabletsMetadata tabletsMetadata = testAmple.readTablets().forTable(tableId).build()) {
            tabletsMetadata.forEach(tm -> {
                assertHasCompactionMetadata(fateId1, tm);
            });
        }
        // Now call undo on the first fateId which would clean up all the metadata for all the
        // tablets that overlap with the given range that was provided to the CompactionDriver
        // during the creation of the repo
        repo.undo(fateId1, manager);
        // First, iterate over only the overlapping tablets and verify that those tablets
        // were cleaned up and remove any visited tablets from the extents set
        try (var tabletsMetadata = testAmple.readTablets().forTable(tableId).overlapping(rangeText.getFirst(), rangeText.getSecond()).build()) {
            tabletsMetadata.forEach(tm -> {
                extents.remove(tm.getExtent());
                assertNoCompactionMetadata(tm);
            });
        }
        // Second, for any remaining tablets that did not overlap the range provided,
        // verify that metadata still exists as the CompactionDriver should not have cleaned
        // up tablets that did not overlap the given range
        try (var tabletsMetadata = testAmple.readTablets().forTablets(extents, Optional.empty()).build()) {
            tabletsMetadata.forEach(tm -> {
                extents.remove(tm.getExtent());
                assertHasCompactionMetadata(fateId1, tm);
            });
        }
        // Verify all the tablets in the table were checked for correct metadata after undo
        assertTrue(extents.isEmpty());
    }
}

/**
 * This test uses multiple threads to update the data in a single zookeeper node using
 * {@link ZooReaderWriter#mutateOrCreate(String, byte[], ZooReaderWriter.Mutator)} and tries to
 * detect errors and race conditions in that code. Each thread uses {@link #nextValue(String)} to
 * compute a new value for the ZK node based on the current value, producing a new unique value.
 * Its expected that multiple threads calling {@link #nextValue(String)} as previously described
 * should yield the same final value as a single thread repeatedly calling
 * {@link #nextValue(String)} the same number of times. There are many things that can go wrong in
 * the multithreaded case. This test tries to ensure the following are true for the multithreaded
 * case.
 *
 * <ul>
 * <li>All expected updates are made, none were skipped.
 * <li>No updates are made twice. For example if two threads wrote the exact same value to the
 * node this should be detected by the test. Would expect each update to be unique.
 * <li>The updates are made in the same order as a single thread repeatedly calling
 * {@link #nextValue(String)}.
 * </ul>
 *
 * <p>
 * If any of the expectations above are not met it should cause the hash, count, and/or count
 * tracking done in the test to not match the what is computed by the single threaded code at the
 * end of the test.
 *
 * <p>
 * A hash and a counter are stored in ZK. The hashes form a chain of hashes as each new value is
 * written because its a hash of the previous value. The chain of hashes is useful for detecting
 * missing and out of order updates, but not duplicates. The counter and associated map that
 * tracks which counts were seen is useful for detecting missing and duplicate updates. The
 * counter is also used to weakly check for out of order updates, but the chain of hashes provides
 * a much strong check for this.
 */
@Test
public void concurrentMutatorTest() throws Exception {
    File newFolder = new File(tempDir, testName() + "/");
    assertTrue(newFolder.isDirectory() || newFolder.mkdir(), "failed to create dir: " + newFolder);
    try (var testZk = new ZooKeeperTestingServer(newFolder);
        var zk = testZk.newClient()) {
        var zrw = zk.asReaderWriter();
        var executor = Executors.newFixedThreadPool(16);
        String initialData = hash("Accumulo Zookeeper Mutator test data") + " 0";
        List<Future<?>> futures = new ArrayList<>();
        // This map is used to ensure multiple threads do not successfully write the same value and no
        // values are skipped. The hash in the value also verifies similar things in a different way.
        ConcurrentHashMap<Integer, Integer> countCounts = new ConcurrentHashMap<>();
        for (int i = 0; i < 16; i++) {
            futures.add(executor.submit(() -> {
                try {
                    int count = -1;
                    while (count < 200) {
                        byte[] val = zrw.mutateOrCreate("/test-zm", initialData.getBytes(UTF_8), this::nextValue);
                        int nextCount = getCount(val);
                        assertTrue(nextCount > count, "nextCount <= count " + nextCount + " " + count);
                        count = nextCount;
                        countCounts.merge(count, 1, Integer::sum);
                    }
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }));
        }
        // wait and check for errors in background threads
        for (Future<?> future : futures) {
            future.get();
        }
        executor.shutdown();
        byte[] actual = zrw.getData("/test-zm");
        int settledCount = getCount(actual);
        assertTrue(settledCount >= 200);
        String expected = initialData;
        assertEquals(1, (int) countCounts.get(0));
        for (int i = 1; i <= settledCount; i++) {
            assertEquals(1, (int) countCounts.get(i));
            expected = nextValue(expected);
        }
        assertEquals(settledCount + 1, countCounts.size());
        assertEquals(expected, new String(actual, UTF_8));
    }
