@Test
public void requireStatus() throws Exception {
    final String table = getUniqueNames(1)[0];
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        client.tableOperations().create(table, ntc);
        ClientContext context = (ClientContext) client;
        FateId fateId = FateId.from(FateInstanceType.fromNamespaceOrTableName(table), UUID.randomUUID());
        // use require status passing all statuses. without the status column present this should fail
        assertThrows(IllegalStateException.class, () -> new FateMutatorImpl<>(context, table, fateId).requireStatus(ReadOnlyFateStore.TStatus.values()).putStatus(ReadOnlyFateStore.TStatus.NEW).mutate());
        assertEquals(0, client.createScanner(table).stream().count());
        var status = new FateMutatorImpl<>(context, table, fateId).requireStatus(ReadOnlyFateStore.TStatus.values()).putStatus(ReadOnlyFateStore.TStatus.NEW).tryMutate();
        assertEquals(REJECTED, status);
        assertEquals(0, client.createScanner(table).stream().count());
        // use require status without passing any statuses to require that the status column is absent
        status = new FateMutatorImpl<>(context, table, fateId).requireStatus().putStatus(ReadOnlyFateStore.TStatus.NEW).tryMutate();
        assertEquals(ACCEPTED, status);
        // try again with requiring an absent status column. this time it should fail because we just
        // put status NEW
        assertThrows(IllegalStateException.class, () -> new FateMutatorImpl<>(context, table, fateId).requireStatus().putStatus(ReadOnlyFateStore.TStatus.NEW).mutate(), "Expected to not be able to use requireStatus() without passing any statuses");
        status = new FateMutatorImpl<>(context, table, fateId).requireStatus().putStatus(ReadOnlyFateStore.TStatus.NEW).tryMutate();
        assertEquals(REJECTED, status, "Expected to not be able to use requireStatus() without passing any statuses");
        // now use require same with the current status, NEW passed in
        status = new FateMutatorImpl<>(context, table, fateId).requireStatus(ReadOnlyFateStore.TStatus.NEW).putStatus(ReadOnlyFateStore.TStatus.SUBMITTED).tryMutate();
        assertEquals(ACCEPTED, status);
        // use require same with an array of statuses, none of which are the current status
        // (SUBMITTED)
        assertThrows(IllegalStateException.class, () -> new FateMutatorImpl<>(context, table, fateId).requireStatus(ReadOnlyFateStore.TStatus.NEW, ReadOnlyFateStore.TStatus.UNKNOWN).putStatus(ReadOnlyFateStore.TStatus.SUBMITTED).mutate(), "Expected to not be able to use requireStatus() with statuses that do not match the current status");
        status = new FateMutatorImpl<>(context, table, fateId).requireStatus(ReadOnlyFateStore.TStatus.NEW, ReadOnlyFateStore.TStatus.UNKNOWN).putStatus(ReadOnlyFateStore.TStatus.SUBMITTED).tryMutate();
        assertEquals(REJECTED, status, "Expected to not be able to use requireStatus() with statuses that do not match the current status");
        // use require same with an array of statuses, one of which is the current status (SUBMITTED)
        status = new FateMutatorImpl<>(context, table, fateId).requireStatus(ReadOnlyFateStore.TStatus.UNKNOWN, ReadOnlyFateStore.TStatus.SUBMITTED).putStatus(ReadOnlyFateStore.TStatus.IN_PROGRESS).tryMutate();
        assertEquals(ACCEPTED, status);
        // one more time check that we can use require same with the current status (IN_PROGRESS)
        status = new FateMutatorImpl<>(context, table, fateId).requireStatus(ReadOnlyFateStore.TStatus.IN_PROGRESS).putStatus(ReadOnlyFateStore.TStatus.FAILED_IN_PROGRESS).tryMutate();
        assertEquals(ACCEPTED, status);
    }
}

@Test
public void testReservations() throws Exception {
    final String table = getUniqueNames(1)[0];
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        client.tableOperations().create(table, ntc);
        ClientContext context = (ClientContext) client;
        FateId fateId = FateId.from(FateInstanceType.USER, UUID.randomUUID());
        ZooUtil.LockID lockID = new ZooUtil.LockID("/locks", "L1", 50);
        FateStore.FateReservation reservation = FateStore.FateReservation.from(lockID, UUID.randomUUID());
        FateStore.FateReservation wrongReservation = FateStore.FateReservation.from(lockID, UUID.randomUUID());
        // Ensure that reserving is the only thing we can do
        FateMutator.Status status = new FateMutatorImpl<>(context, table, fateId).putUnreserveTx(reservation).tryMutate();
        assertEquals(REJECTED, status);
        status = new FateMutatorImpl<>(context, table, fateId).putReservedTx(reservation).tryMutate();
        assertEquals(ACCEPTED, status);
        // Should not be able to reserve when it is already reserved
        status = new FateMutatorImpl<>(context, table, fateId).putReservedTx(wrongReservation).tryMutate();
        assertEquals(REJECTED, status);
        status = new FateMutatorImpl<>(context, table, fateId).putReservedTx(reservation).tryMutate();
        assertEquals(REJECTED, status);
        // Should be able to unreserve
        status = new FateMutatorImpl<>(context, table, fateId).putUnreserveTx(wrongReservation).tryMutate();
        assertEquals(REJECTED, status);
        status = new FateMutatorImpl<>(context, table, fateId).putUnreserveTx(reservation).tryMutate();
        assertEquals(ACCEPTED, status);
        status = new FateMutatorImpl<>(context, table, fateId).putUnreserveTx(reservation).tryMutate();
        assertEquals(REJECTED, status);
    }
}

