@Test
public void updateSplitWithMergeabilityTest() throws Exception {
    String tableName = getUniqueNames(1)[0];
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        c.tableOperations().create(tableName);
        NavigableMap<Text, TabletMergeability> splits = new TreeMap<>();
        splits.put(new Text(String.format("%09d", 111)), TabletMergeability.always());
        splits.put(new Text(String.format("%09d", 333)), TabletMergeability.never());
        splits.put(new Text(String.format("%09d", 666)), TabletMergeability.never());
        splits.put(new Text(String.format("%09d", 999)), TabletMergeability.after(Duration.ofDays(10)));
        c.tableOperations().putSplits(tableName, splits);
        Thread.sleep(100);
        assertEquals(splits.keySet(), new TreeSet<>(c.tableOperations().listSplits(tableName)));
        TableId id = TableId.of(c.tableOperations().tableIdMap().get(tableName));
        verifySplits(id, splits);
        // Set all splits to system default (always) and update
        var splitUpdates = TabletMergeabilityUtil.systemDefaultSplits(splits.navigableKeySet());
        c.tableOperations().putSplits(tableName, splitUpdates);
        verifySplits(id, splitUpdates);
        verifySplitsWithApi(c, tableName, splitUpdates);
        // Update existing and add two new splits
        // remove split 111 from map so we don't update it
        splits.remove(new Text(String.format("%09d", 111)));
        splits.put(new Text(String.format("%09d", 333)), TabletMergeability.after(Duration.ofHours(11)));
        splits.put(new Text(String.format("%09d", 666)), TabletMergeability.after(Duration.ofHours(10)));
        splits.put(new Text(String.format("%09d", 444)), TabletMergeability.always());
        splits.put(new Text(String.format("%09d", 777)), TabletMergeability.after(Duration.ofMinutes(5)));
        c.tableOperations().putSplits(tableName, splits);
        // re-add split 111 and verify it has not changed
        splits.put(new Text(String.format("%09d", 111)), TabletMergeability.always());
        verifySplits(id, splits);
        verifySplitsWithApi(c, tableName, splits);
        // Update with same and make sure insertion time updated
        splits.clear();
        var split = new Text(String.format("%09d", 777));
        splits.put(split, TabletMergeability.after(Duration.ofMinutes(5)));
        var originalTmi = c.tableOperations().getTabletInformation(tableName, new Range(split)).findFirst().orElseThrow().getTabletMergeabilityInfo();
        assertTrue(originalTmi.getElapsed().orElseThrow().toNanos() > 0);
        // Update existing with same delay of 5 minutes
        c.tableOperations().putSplits(tableName, splits);
        var updatedTmi = c.tableOperations().getTabletInformation(tableName, new Range(split)).findFirst().orElseThrow().getTabletMergeabilityInfo();
        // TabletMergeability setting should be the same but the new elapsed time should
        // be different (less time has passed as it was updated with a new insertion time)
        assertEquals(originalTmi.getTabletMergeability(), updatedTmi.getTabletMergeability());
        assertTrue(originalTmi.getElapsed().orElseThrow().compareTo(updatedTmi.getElapsed().orElseThrow()) > 0);
    }
}

@Test
public void addSplitIsMergeableTest() throws Exception {
    String tableName = getUniqueNames(1)[0];
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        c.tableOperations().create(tableName);
        var split1 = new Text(String.format("%09d", 333));
        var split2 = new Text(String.format("%09d", 666));
        var split3 = new Text(String.format("%09d", 888));
        var split4 = new Text(String.format("%09d", 999));
        SortedMap<Text, TabletMergeability> splits = new TreeMap<>();
        splits.put(split1, TabletMergeability.always());
        splits.put(split2, TabletMergeability.never());
        splits.put(split3, TabletMergeability.after(Duration.ofMillis(1)));
        splits.put(split4, TabletMergeability.after(Duration.ofDays(1)));
        c.tableOperations().putSplits(tableName, splits);
        Thread.sleep(100);
        assertEquals(splits.keySet(), new TreeSet<>(c.tableOperations().listSplits(tableName)));
        var tableInfo = c.tableOperations().getTabletInformation(tableName, new Range()).collect(Collectors.toMap(ti -> ti.getTabletId().getEndRow(), Function.identity()));
        // Set to always
        var split1Tmi = tableInfo.get(split1).getTabletMergeabilityInfo();
        assertTrue(split1Tmi.isMergeable());
        assertTrue(split1Tmi.getTabletMergeability().isAlways());
        assertTrue(split1Tmi.getElapsed().orElseThrow().toNanos() > 0);
        assertEquals(Duration.ZERO, split1Tmi.getRemaining().orElseThrow());
        assertEquals(computeRemaining(split1Tmi), split1Tmi.getRemaining());
        // Set to never
        var split2Tmi = tableInfo.get(split2).getTabletMergeabilityInfo();
        assertFalse(split2Tmi.isMergeable());
        assertTrue(split2Tmi.getTabletMergeability().isNever());
        assertTrue(split2Tmi.getElapsed().isEmpty());
        assertTrue(split2Tmi.getDelay().isEmpty());
        assertTrue(split2Tmi.getRemaining().isEmpty());
        // Set to a delay of 1 ms and current time should have elapsed long enough
        var split3Tmi = tableInfo.get(split3).getTabletMergeabilityInfo();
        assertTrue(split3Tmi.isMergeable());
        assertEquals(Duration.ofMillis(1), split3Tmi.getDelay().orElseThrow());
        assertTrue(split3Tmi.getElapsed().orElseThrow().toNanos() > 0);
        assertEquals(computeRemaining(split3Tmi), split3Tmi.getRemaining());
        // Set to a delay of 1 day and current time has NOT elapsed long enough
        var split4Tmi = tableInfo.get(split4).getTabletMergeabilityInfo();
        assertFalse(split4Tmi.isMergeable());
        assertEquals(Duration.ofDays(1), split4Tmi.getDelay().orElseThrow());
        assertTrue(split4Tmi.getElapsed().orElseThrow().toNanos() > 0);
        assertEquals(computeRemaining(split4Tmi), split4Tmi.getRemaining());
    }
}

@Test
public void concurrentAddSplitTest() throws Exception {
    var threads = 10;
    var service = Executors.newFixedThreadPool(threads);
    var latch = new CountDownLatch(threads);
    String tableName = getUniqueNames(1)[0];
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        c.tableOperations().create(tableName);
        // Create a map to hold all splits to verify later
        SortedMap<Text, TabletMergeability> allSplits = Collections.synchronizedNavigableMap(new TreeMap<>());
        var commonBuilder = ImmutableMap.<Text, TabletMergeability>builder();
        for (int i = 0; i < 50; i++) {
            commonBuilder.put(new Text(String.format("%09d", i)), TabletMergeability.after(Duration.ofHours(1 + i)));
        }
        // create 50 splits that will be added to all threads
        var commonSplits = commonBuilder.build();
        allSplits.putAll(commonSplits);
        // Spin up 10 threads and concurrently submit all 50 existing splits
        // as well as 50 unique splits, this should create a collision with fate
        // and cause retries
        for (int i = 1; i <= threads; i++) {
            var start = i * 100;
            service.execute(() -> {
                // add the 50 common splits
                SortedMap<Text, TabletMergeability> splits = new TreeMap<>(commonSplits);
                // create 50 unique splits
                for (int j = start; j < start + 50; j++) {
                    splits.put(new Text(String.format("%09d", j)), TabletMergeability.after(Duration.ofHours(1 + j)));
                }
                // make sure all splits are captured
                allSplits.putAll(splits);
                // Wait for all 10 threads to be ready before calling putSplits()
                // to increase the chance of collisions
                latch.countDown();
                try {
                    latch.await();
                    c.tableOperations().putSplits(tableName, splits);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            });
        }
        // Wait for all 10 threads to finish
        service.shutdown();
        assertTrue(service.awaitTermination(2, TimeUnit.MINUTES));
        // Verify we have 550 splits and then all splits are correctly set
        assertEquals(50 + (threads * 50), allSplits.size());
        TableId id = TableId.of(c.tableOperations().tableIdMap().get(tableName));
        verifySplits(id, allSplits);
        verifySplitsWithApi(c, tableName, allSplits);
    }
}

@Test
public void testLocations() {
    var ts1 = new TServerInstance("localhost:9997", 5000L);
    var ts2 = new TServerInstance("localhost:9997", 6000L);
    var context = getCluster().getServerContext();
    assertNull(context.getAmple().readTablet(e1).getLocation());
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireAbsentLocation().putLocation(Location.future(ts1)).submit(tm -> false);
        assertEquals(Status.ACCEPTED, ctmi.process().get(e1).getStatus());
    }
    assertEquals(Location.future(ts1), context.getAmple().readTablet(e1).getLocation());
    // test require absent with a future location set
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireAbsentLocation().putLocation(Location.future(ts2)).submit(tm -> false, () -> "Testing that requireAbsentLocation() fails when a future location is set");
        assertEquals(Status.REJECTED, ctmi.process().get(e1).getStatus());
    }
    assertEquals(Location.future(ts1), context.getAmple().readTablet(e1).getLocation());
    try (TabletsMetadata tablets = context.getAmple().readTablets().forTable(tid).filter(new HasCurrentFilter()).build()) {
        List<KeyExtent> actual = tablets.stream().map(TabletMetadata::getExtent).collect(Collectors.toList());
        assertEquals(List.of(), actual);
    }
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireLocation(Location.future(ts1)).putLocation(Location.current(ts1)).deleteLocation(Location.future(ts1)).submit(tm -> false);
        assertEquals(Status.ACCEPTED, ctmi.process().get(e1).getStatus());
    }
    assertEquals(Location.current(ts1), context.getAmple().readTablet(e1).getLocation());
    // test require absent with a current location set
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireAbsentLocation().putLocation(Location.future(ts2)).submit(tm -> false);
        assertEquals(Status.REJECTED, ctmi.process().get(e1).getStatus(), () -> "Testing that requireAbsentLocation() fails when a current location is set");
    }
    assertEquals(Location.current(ts1), context.getAmple().readTablet(e1).getLocation());
    try (TabletsMetadata tablets = context.getAmple().readTablets().forTable(tid).filter(new HasCurrentFilter()).build()) {
        List<KeyExtent> actual = tablets.stream().map(TabletMetadata::getExtent).collect(Collectors.toList());
        assertEquals(List.of(e1), actual);
    }
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireLocation(Location.future(ts1)).putLocation(Location.current(ts1)).deleteLocation(Location.future(ts1)).submit(tm -> false);
        assertEquals(Status.REJECTED, ctmi.process().get(e1).getStatus());
    }
    assertEquals(Location.current(ts1), context.getAmple().readTablet(e1).getLocation());
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireLocation(Location.future(ts2)).putLocation(Location.current(ts2)).deleteLocation(Location.future(ts2)).submit(tm -> false);
        assertEquals(Status.REJECTED, ctmi.process().get(e1).getStatus());
    }
    assertEquals(Location.current(ts1), context.getAmple().readTablet(e1).getLocation());
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireLocation(Location.current(ts1)).deleteLocation(Location.current(ts1)).submit(tm -> false);
        assertEquals(Status.ACCEPTED, ctmi.process().get(e1).getStatus());
    }
    assertNull(context.getAmple().readTablet(e1).getLocation());
    // Set two current locations, this puts the tablet in a bad state as its only expected that
    // single location should be set
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().putLocation(Location.current(ts1)).putLocation(Location.current(ts2)).submit(tm -> false);
        assertEquals(Status.ACCEPTED, ctmi.process().get(e1).getStatus());
    }
    // When a tablet has two locations reading it should throw an exception
    assertThrows(IllegalStateException.class, () -> context.getAmple().readTablet(e1));
    // Try to update the tablet requiring one of the locations that is set on the tablet. Even
    // though the required location exists, the presence of the other location in the tablet
    // metadata should cause the update to fail.
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireLocation(Location.current(ts1)).deleteLocation(Location.current(ts1)).deleteLocation(Location.current(ts2)).submit(tm -> false);
        // The update should be rejected because of the two locations. When a conditional mutation
        // is rejected an attempt is made to read the tablet metadata and examine. This read of the
        // tablet metadata will fail because the tablet has two locations.
        assertThrows(IllegalStateException.class, ctmi.process().get(e1)::getStatus);
    }
    // tablet should still have two location set, so reading it should fail
    assertThrows(IllegalStateException.class, () -> context.getAmple().readTablet(e1));
    // Requiring an absent location should fail when two locations are set
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireAbsentLocation().deleteLocation(Location.current(ts1)).deleteLocation(Location.current(ts2)).submit(tm -> false);
        assertThrows(IllegalStateException.class, ctmi.process().get(e1)::getStatus);
    }
    // tablet should still have two location set, so reading it should fail
    assertThrows(IllegalStateException.class, () -> context.getAmple().readTablet(e1));
    // Change the tablet to have a future and current location set.
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().deleteLocation(Location.current(ts1)).putLocation(Location.future(ts1)).submit(tm -> false);
        assertEquals(Status.ACCEPTED, ctmi.process().get(e1).getStatus());
    }
    // tablet should still have two location set, so reading it should fail
    assertThrows(IllegalStateException.class, () -> context.getAmple().readTablet(e1));
    // Test requiring different locations. Some of the required locations are actually set and
    // some are not. All should fail because the tablet has multiple locations set and/or the
    // required location does not exist.
    for (var loc : List.of(Location.current(ts1), Location.current(ts2), Location.future(ts1), Location.future(ts2))) {
        try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
            ctmi.mutateTablet(e1).requireAbsentOperation().requireLocation(loc).deleteLocation(Location.future(ts1)).deleteLocation(Location.current(ts2)).submit(tm -> false);
            // tablet should still have two location set, so reading it should fail
            assertThrows(IllegalStateException.class, ctmi.process().get(e1)::getStatus);
        }
    }
    // Requiring an absent location should fail when a future and current location are set
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireAbsentLocation().deleteLocation(Location.current(ts1)).deleteLocation(Location.current(ts2)).submit(tm -> false);
        assertThrows(IllegalStateException.class, ctmi.process().get(e1)::getStatus);
    }
    // tablet should still have two location set, so reading it should fail
    assertThrows(IllegalStateException.class, () -> context.getAmple().readTablet(e1));
    // Delete one of the locations w/o any location requirements, this should succeed.
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().deleteLocation(Location.future(ts1)).submit(tm -> false);
        assertEquals(Status.ACCEPTED, ctmi.process().get(e1).getStatus());
    }
    // This check validates the expected state of the tablet as some of the previous test were
    // catching an exception and making assumption about the state of the tablet metadata based on
    // the fact that an exception was thrown.
    assertEquals(Location.current(ts2), context.getAmple().readTablet(e1).getLocation());
}

