    assertEquals(Set.of(stf1, stf2, stf3), context.getAmple().readTablet(e1).getFiles());
    // simulate a compaction and test a subset and superset of files
    for (var tabletMeta : List.of(TabletMetadata.builder(e1).putFile(stf1, dfv).putFile(stf2, dfv).build(), TabletMetadata.builder(e1).putFile(stf1, dfv).putFile(stf2, dfv).putFile(stf3, dfv).putFile(stf4, dfv).build())) {
