    assertEquals(Set.of(stf4), context.getAmple().readTablet(e1).getFiles());
    // simulate a bulk import
    var stf5 = StoredTabletFile.of(new Path("hdfs://localhost:8020/accumulo/tables/2a/b-0000009/I0000074.rf"));
