        assertEquals(Status.ACCEPTED, ctmi.process().get(e1).getStatus());
    }
    assertEquals(Set.of(stf4, stf5), context.getAmple().readTablet(e1).getFiles());
    // simulate a compaction
    var stf6 = StoredTabletFile.of(new Path("hdfs://localhost:8020/accumulo/tables/2a/default_tablet/A0000075.rf"));
    var tm7 = TabletMetadata.builder(e1).putFile(stf4, compactedDv).putFile(stf5, compactedDv).build();
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireSame(tm7, FILES).putFile(stf6, new DataFileValue(0, 0)).deleteFile(stf4).deleteFile(stf5).submit(tm -> false);
        assertEquals(Status.ACCEPTED, ctmi.process().get(e1).getStatus());
    }
    assertEquals(Set.of(stf6), context.getAmple().readTablet(e1).getFiles());
