    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireAbsentLocation().putLocation(Location.future(ts2)).submit(tm -> false);
        ctmi.mutateTablet(e2).requireAbsentTablet().putLocation(Location.future(ts1)).submit(tm -> false);
