@Test
public void testCompaction() {
    var context = getCluster().getServerContext();
    ExternalCompactionId ecid1 = ExternalCompactionId.generate(UUID.randomUUID());
    ExternalCompactionId ecid2 = ExternalCompactionId.generate(UUID.randomUUID());
    FateInstanceType type = FateInstanceType.fromTableId(tid);
    FateId fateId = FateId.from(type, UUID.randomUUID());
    ReferencedTabletFile tmpFile = ReferencedTabletFile.of(new Path("file:///accumulo/tables/t-0/b-0/c1.rf"));
    CompactorGroupId ceid = CompactorGroupId.of("G1");
    Set<StoredTabletFile> jobFiles = Set.of(StoredTabletFile.of(new Path("file:///accumulo/tables/t-0/b-0/b2.rf")));
    CompactionMetadata ecMeta = new CompactionMetadata(jobFiles, tmpFile, "localhost:4444", CompactionKind.SYSTEM, (short) 2, ceid, false, fateId);
    // create a tablet metadata w/ en empty set of compactions
    var tabletMetaNoCompactions = TabletMetadata.builder(e1).build(ECOMP);
    var tabletMetaCompactions = TabletMetadata.builder(e1).putExternalCompaction(ecid1, ecMeta).build();
    // Test different compaction requirement scenarios for tablets w/o any compactions in the
    // metadata table
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireSame(tabletMetaNoCompactions, ECOMP).putExternalCompaction(ecid1, ecMeta).submit(tm -> false);
        ctmi.mutateTablet(e2).requireAbsentOperation().requireCompaction(ecid2).putExternalCompaction(ecid1, ecMeta).submit(tm -> false);
        ctmi.mutateTablet(e3).requireAbsentOperation().requireSame(tabletMetaNoCompactions, ECOMP).putExternalCompaction(ecid1, ecMeta).putExternalCompaction(ecid2, ecMeta).submit(tm -> false);
        ctmi.mutateTablet(e4).requireAbsentOperation().requireSame(tabletMetaCompactions, ECOMP).putExternalCompaction(ecid1, ecMeta).submit(tm -> false);
        var results = ctmi.process();
        assertEquals(Status.ACCEPTED, results.get(e1).getStatus());
        assertEquals(Status.REJECTED, results.get(e2).getStatus());
        assertEquals(Status.ACCEPTED, results.get(e3).getStatus());
        assertEquals(Status.REJECTED, results.get(e4).getStatus());
    }
    assertEquals(Set.of(ecid1), context.getAmple().readTablet(e1).getExternalCompactions().keySet());
    assertEquals(Set.of(), context.getAmple().readTablet(e2).getExternalCompactions().keySet());
    assertEquals(Set.of(ecid1, ecid2), context.getAmple().readTablet(e3).getExternalCompactions().keySet());
    assertEquals(Set.of(), context.getAmple().readTablet(e4).getExternalCompactions().keySet());
    // Test compaction requirements that do not match the compaction ids that exists in the
    // metadata table.
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireCompaction(ecid2).deleteExternalCompaction(ecid1).submit(tm -> false);
        ctmi.mutateTablet(e3).requireAbsentOperation().requireSame(tabletMetaCompactions, ECOMP).deleteExternalCompaction(ecid1).submit(tm -> false);
        var results = ctmi.process();
        assertEquals(Status.REJECTED, results.get(e1).getStatus());
        assertEquals(Status.REJECTED, results.get(e3).getStatus());
    }
    assertEquals(Set.of(ecid1), context.getAmple().readTablet(e1).getExternalCompactions().keySet());
    assertEquals(Set.of(ecid1, ecid2), context.getAmple().readTablet(e3).getExternalCompactions().keySet());
    // Test compaction requirements that match the compaction ids that exists in the metadata
    // table.
    try (var ctmi = new ConditionalTabletsMutatorImpl(context)) {
        ctmi.mutateTablet(e1).requireAbsentOperation().requireSame(tabletMetaCompactions, ECOMP).deleteExternalCompaction(ecid1).submit(tm -> false);
        ctmi.mutateTablet(e3).requireAbsentOperation().requireCompaction(ecid2).deleteExternalCompaction(ecid1).submit(tm -> false);
        var results = ctmi.process();
        assertEquals(Status.ACCEPTED, results.get(e1).getStatus());
        assertEquals(Status.ACCEPTED, results.get(e3).getStatus());
    }
    assertEquals(Set.of(), context.getAmple().readTablet(e1).getExternalCompactions().keySet());
    assertEquals(Set.of(ecid2), context.getAmple().readTablet(e3).getExternalCompactions().keySet());
}

