@Test
public void test() throws Exception {
    // wait for manager
    Thread.sleep(1000);
    // create a backup
    Process backup = exec(Manager.class);
    try (AccumuloClient client = Accumulo.newClient().from(getClientProperties()).build()) {
        ZooReaderWriter writer = getServerContext().getZooSession().asReaderWriter();
        // wait for 2 lock entries
        var path = getServerContext().getServerPaths().createManagerPath();
        Wait.waitFor(() -> ServiceLock.validateAndSort(path, writer.getChildren(path.toString())).size() == 2);
        // wait for the backup manager to learn to be the backup
        Thread.sleep(1000);
        // generate a false zookeeper event
        List<String> children = ServiceLock.validateAndSort(path, writer.getChildren(path.toString()));
        String lockPath = path + "/" + children.get(0);
        byte[] data = writer.getData(lockPath);
        getServerContext().getZooSession().setData(lockPath, data, -1);
        // let it propagate
        Thread.sleep(500);
        // kill the manager by removing its lock
        writer.recursiveDelete(lockPath, NodeMissingPolicy.FAIL);
        // ensure the backup becomes the manager
        client.tableOperations().create(getUniqueNames(1)[0]);
    } finally {
        backup.destroy();
    }
}

@Test
public void test() throws Exception {
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        c.tableOperations().create(tableName);
        IteratorSetting is = new IteratorSetting(30, BadIterator.class);
        c.tableOperations().attachIterator(tableName, is, EnumSet.of(IteratorScope.minc));
        try (BatchWriter bw = c.createBatchWriter(tableName)) {
            Mutation m = new Mutation(new Text("r1"));
            m.put("acf", tableName, "1");
            bw.addMutation(m);
        }
        c.tableOperations().flush(tableName, null, null, false);
        Thread.sleep(SECONDS.toMillis(1));
        // minc should fail, so there should be no files
        FunctionalTestUtils.checkRFiles(c, tableName, 1, 1, 0, 0);
        // try to scan table
        try (Scanner scanner = c.createScanner(tableName, Authorizations.EMPTY)) {
            int count = Iterators.size(scanner.iterator());
            assertEquals(1, count, "Did not see expected # entries " + count);
            // remove the bad iterator
            c.tableOperations().removeIterator(tableName, BadIterator.class.getSimpleName(), EnumSet.of(IteratorScope.minc));
            Thread.sleep(SECONDS.toMillis(5));
            // minc should complete
            FunctionalTestUtils.checkRFiles(c, tableName, 1, 1, 1, 1);
            count = Iterators.size(scanner.iterator());
            if (count != 1) {
                throw new Exception("Did not see expected # entries " + count);
            }
            // now try putting bad iterator back and deleting the table
            c.tableOperations().attachIterator(tableName, is, EnumSet.of(IteratorScope.minc));
            try (BatchWriter bw = c.createBatchWriter(tableName)) {
                Mutation m = new Mutation(new Text("r2"));
                m.put("acf", tableName, "1");
                bw.addMutation(m);
            }
            // make sure property is given time to propagate
            Thread.sleep(500);
            c.tableOperations().flush(tableName, null, null, false);
            // make sure the flush has time to start
            Thread.sleep(SECONDS.toMillis(1));
            // this should not hang
            c.tableOperations().delete(tableName);
        }
    }
}

