@Test
public void test() throws Exception {
    log.info("Test that balancing is not stopped by an offline table with outstanding migrations.");
    log.debug("starting test ingestion");
    VerifyParams params = new VerifyParams(getClientProps(), TEST_TABLE, 200_000);
    TestIngest.ingest(accumuloClient, params);
    accumuloClient.tableOperations().flush(TEST_TABLE, null, null, true);
    VerifyIngest.verifyIngest(accumuloClient, params);
    log.debug("waiting for balancing, up to ~5 minutes to allow for migration cleanup.");
    final long startTime = System.currentTimeMillis();
    long currentWait = 1_000;
    boolean balancingWorked = false;
    Credentials creds = new Credentials(getAdminPrincipal(), getAdminToken());
    while (!balancingWorked && (System.currentTimeMillis() - startTime) < ((5 * 60 + 15) * 1000)) {
        Thread.sleep(currentWait);
        currentWait = Math.min(currentWait * 2, 30_000);
        log.debug("fetch the list of tablets assigned to each tserver.");
        ManagerMonitorInfo stats = ThriftClientTypes.MANAGER.execute((ClientContext) accumuloClient, client -> client.getManagerStats(TraceUtil.traceInfo(), creds.toThrift(accumuloClient.instanceOperations().getInstanceId())));
        if (stats.getTServerInfoSize() < 2) {
            log.debug("we need >= 2 servers. sleeping for {}ms", currentWait);
            continue;
        }
        if (stats.getUnassignedTablets() != 0) {
            log.debug("We shouldn't have unassigned tablets. sleeping for {}ms", currentWait);
            continue;
        }
        var numSplits = accumuloClient.tableOperations().listSplits(TEST_TABLE).size();
        if (numSplits < 20) {
            log.debug("Waiting for 20 splits, saw {} split. sleeping for {}ms", numSplits, currentWait);
            continue;
        }
        long[] tabletsPerServer = new long[stats.getTServerInfoSize()];
        Arrays.fill(tabletsPerServer, 0L);
        for (int i = 0; i < stats.getTServerInfoSize(); i++) {
            for (Map.Entry<String, TableInfo> entry : stats.getTServerInfo().get(i).getTableMap().entrySet()) {
                tabletsPerServer[i] += entry.getValue().getTablets();
                log.debug("Tablets per server {} {} {} {}", stats.getTServerInfo().get(i).getName(), i, entry.getKey(), entry.getValue().getTablets());
            }
        }
        if (tabletsPerServer[0] <= 10) {
            log.debug("We should have > 10 tablets. sleeping for {}ms tabletsPerServer:{}", currentWait, List.of(tabletsPerServer));
            continue;
        }
        long min = NumberUtils.min(tabletsPerServer), max = NumberUtils.max(tabletsPerServer);
        log.debug("Min={}, Max={}", min, max);
        if ((min / ((double) max)) < 0.5) {
            log.debug("ratio of min to max tablets per server should be roughly even. sleeping for {}ms", currentWait);
            continue;
        }
        balancingWorked = true;
    }
    assertTrue(balancingWorked, "did not properly balance");
}

@Test
public void test() throws Exception {
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        c.tableOperations().create(tableName);
        int numRows = 1 << 18;
        try (BatchWriter bw = c.createBatchWriter(tableName)) {
            for (int i = 0; i < numRows; i++) {
                Mutation m = new Mutation(new Text(String.format("%09x", i)));
                m.put("cf1", "cq1", String.format("%016x", numRows - i));
                bw.addMutation(m);
            }
        }
        c.tableOperations().flush(tableName, null, null, true);
        c.tableOperations().setProperty(tableName, Property.TABLE_SPLIT_THRESHOLD.getKey(), "4K");
        Collection<Text> splits = c.tableOperations().listSplits(tableName);
        while (splits.size() < 2) {
            Thread.sleep(1);
            splits = c.tableOperations().listSplits(tableName);
        }
        System.out.println("splits : " + splits);
        HashMap<Text, Value> expected = new HashMap<>();
        ArrayList<Range> ranges = new ArrayList<>();
        for (int i = 0; i < 100; i++) {
            int r = RANDOM.get().nextInt(numRows);
            Text row = new Text(String.format("%09x", r));
            expected.put(row, new Value(String.format("%016x", numRows - r)));
            ranges.add(new Range(row));
        }
        // logger.setLevel(Level.TRACE);
        HashMap<Text, Value> found = new HashMap<>();
        for (int i = 0; i < 20; i++) {
            try (BatchScanner bs = c.createBatchScanner(tableName)) {
                found.clear();
                long t1 = System.currentTimeMillis();
                bs.setRanges(ranges);
                for (Entry<Key, Value> entry : bs) {
                    found.put(entry.getKey().getRow(), entry.getValue());
                }
                long t2 = System.currentTimeMillis();
                log.info(String.format("rate : %06.2f%n", ranges.size() / ((t2 - t1) / 1000.0)));
                if (!found.equals(expected)) {
                    throw new Exception("Found and expected differ " + found + " " + expected);
                }
            }
        }
        splits = c.tableOperations().listSplits(tableName);
        log.info("splits : {}", splits);
    }
}

