/**
 * Validate that {@code TableOperations} online operation does not block when table is already
 * online and fate transaction lock is held by other operations. The test creates, populates a
 * table and then runs a compaction with a slow iterator so that operation takes long enough to
 * simulate the condition. After the online operation while compaction is running completes, the
 * test is complete and the compaction is canceled so that other tests can run.
 *
 * @throws Exception any exception is a test failure.
 */
@Test
public void changeTableStateTest() throws Exception {
    String tableName = getUniqueNames(1)[0];
    slowOps = new SlowOps(client, tableName, maxWaitMillis);
    assertEquals(TableState.ONLINE, getTableState(tableName), "verify table online after created");
    OnLineCallable onlineOp = new OnLineCallable(tableName);
    Future<OnlineOpTiming> task = pool.submit(onlineOp);
    OnlineOpTiming timing1 = task.get();
    log.trace("Online 1 in {} ms", NANOSECONDS.toMillis(timing1.runningTime()));
    assertEquals(TableState.ONLINE, getTableState(tableName), "verify table is still online");
    // verify that offline then online functions as expected.
    client.tableOperations().offline(tableName, true);
    assertEquals(TableState.OFFLINE, getTableState(tableName), "verify table is offline");
    onlineOp = new OnLineCallable(tableName);
    task = pool.submit(onlineOp);
    OnlineOpTiming timing2 = task.get();
    log.trace("Online 2 in {} ms", NANOSECONDS.toMillis(timing2.runningTime()));
    assertEquals(TableState.ONLINE, getTableState(tableName), "verify table is back online");
    // launch a full table compaction with the slow iterator to ensure table lock is acquired and
    // held by the compaction
    slowOps.startCompactTask();
    // try to set online while fate transaction is in progress - before ACCUMULO-4574 this would
    // block
    onlineOp = new OnLineCallable(tableName);
    task = pool.submit(onlineOp);
    OnlineOpTiming timing3 = task.get();
    assertTrue(timing3.runningTime() < MILLISECONDS.toNanos(NUM_ROWS * SLOW_SCAN_SLEEP_MS), "online should take less time than expected compaction time");
    assertEquals(TableState.ONLINE, getTableState(tableName), "verify table is still online");
    assertTrue(findFate(tableName), "Find FATE operation for table");
    // test complete, cancel compaction and move on.
    client.tableOperations().cancelCompaction(tableName);
    log.debug("Success: Timing results for online commands.");
    log.debug("Time for unblocked online {} ms", NANOSECONDS.toMillis(timing1.runningTime()));
    log.debug("Time for online when offline {} ms", NANOSECONDS.toMillis(timing2.runningTime()));
    log.debug("Time for blocked online {} ms", NANOSECONDS.toMillis(timing3.runningTime()));
    // block if compaction still running
    slowOps.blockWhileCompactionRunning();
}

/**
 * Validate the AdminUtil.getStatus works correctly after refactor and validate that
 * getTransactionStatus can be called without lock map(s). The test starts a long running fate
 * transaction (slow compaction) and the calls AdminUtil functions to get the FATE.
 */
@Test
public void getFateStatus() {
    String tableName = getUniqueNames(1)[0];
    slowOps = new SlowOps(client, tableName, maxWaitMillis);
    TableId tableId;
    try {
        assertEquals(TableState.ONLINE, getTableState(tableName), "verify table online after created");
        tableId = context.getTableId(tableName);
        log.trace("tid: {}", tableId);
    } catch (TableNotFoundException ex) {
        throw new IllegalStateException(String.format("Table %s does not exist, failing test", tableName));
    }
    slowOps.startCompactTask();
    AdminUtil.FateStatus withLocks = null;
    List<AdminUtil.TransactionStatus> noLocks = null;
    int maxRetries = 3;
    AdminUtil<String> admin = new AdminUtil<>();
    while (maxRetries > 0) {
        try {
            var zk = context.getZooSession();
            MetaFateStore<String> readOnlyMFS = new MetaFateStore<>(zk, null, null);
            UserFateStore<String> readOnlyUFS = new UserFateStore<>(context, AccumuloTable.FATE.tableName(), null, null);
            var lockPath = context.getServerPaths().createTableLocksPath(tableId);
            Map<FateInstanceType, ReadOnlyFateStore<String>> readOnlyFateStores = Map.of(FateInstanceType.META, readOnlyMFS, FateInstanceType.USER, readOnlyUFS);
            withLocks = admin.getStatus(readOnlyFateStores, zk, lockPath, null, null, null);
            // call method that does not use locks.
            noLocks = admin.getTransactionStatus(readOnlyFateStores, null, null, null);
            // no zk exception, no need to retry
            break;
        } catch (InterruptedException ex) {
            Thread.currentThread().interrupt();
            fail("Interrupt received - test failed");
            return;
        } catch (KeeperException ex) {
            maxRetries--;
            try {
                Thread.sleep(1000);
            } catch (InterruptedException intr_ex) {
                Thread.currentThread().interrupt();
                return;
            }
        }
    }
    assertNotNull(withLocks);
    assertNotNull(noLocks);
    // fast check - count number of transactions
    assertEquals(withLocks.getTransactions().size(), noLocks.size());
    int matchCount = 0;
    for (AdminUtil.TransactionStatus tx : withLocks.getTransactions()) {
        if (isCompaction(tx)) {
            log.trace("Fate id: {}, status: {}", tx.getFateId(), tx.getStatus());
            for (AdminUtil.TransactionStatus tx2 : noLocks) {
                if (tx2.getFateId().equals(tx.getFateId())) {
                    matchCount++;
                }
            }
        }
    }
    assertTrue(matchCount > 0, "Number of fates matches should be > 0");
    try {
        // test complete, cancel compaction and move on.
        client.tableOperations().cancelCompaction(tableName);
        // block if compaction still running
        boolean cancelled = slowOps.blockWhileCompactionRunning();
        log.debug("Cancel completed successfully: {}", cancelled);
    } catch (TableNotFoundException | AccumuloSecurityException | AccumuloException ex) {
        log.debug("Could not cancel compaction due to exception", ex);
    }
}

/**
 * Concurrency testing - ensure that tests are valid if multiple compactions are running. for
 * development testing - force transient condition that was failing this test so that we know if
 * multiple compactions are running, they are properly handled by the test code and the tests are
 * valid.
 */
@Test
public void multipleCompactions() throws InterruptedException, IOException {
    int tableCount = 4;
    // Start 4 Compactors for the default group
    MiniAccumuloClusterImpl mini = (MiniAccumuloClusterImpl) getCluster();
    mini.getConfig().getClusterServerConfiguration().addCompactorResourceGroup(Constants.DEFAULT_RESOURCE_GROUP_NAME, 4);
    mini.start();
    List<SlowOps> tables = Arrays.stream(getUniqueNames(tableCount)).map(tableName -> new SlowOps(client, tableName, maxWaitMillis)).collect(Collectors.toList());
    tables.forEach(SlowOps::startCompactTask);
    assertEquals(tableCount, tables.stream().map(SlowOps::getTableName).filter(this::findFate).count());
    Wait.waitFor(() -> tableCount == ExternalCompactionUtil.getCompactionsRunningOnCompactors((ClientContext) client).size());
    tables.forEach(t -> {
        try {
            client.tableOperations().cancelCompaction(t.getTableName());
        } catch (AccumuloSecurityException | TableNotFoundException | AccumuloException ex) {
            log.debug("Exception throw during multiple table test clean-up", ex);
        }
        // block if compaction still running
        boolean cancelled = t.blockWhileCompactionRunning();
        if (!cancelled) {
            log.info("Failed to cancel compaction during multiple compaction test clean-up for {}", t.getTableName());
        }
    });
}

@Test
public void run() throws Exception {
    String tableName = getUniqueNames(1)[0];
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        var ntc = new NewTableConfiguration().withSplits(TestIngest.getSplitPoints(0, 100000, 50));
        c.tableOperations().create(tableName, ntc);
        IngestParams params = new IngestParams(getClientProps(), tableName, 100_000);
        params.random = 89;
        params.timestamp = 7;
        params.dataSize = 50;
        params.cols = 1;
        TestIngest.ingest(c, params);
        log.debug("Ingest complete");
        c.tableOperations().flush(tableName, null, null, true);
        log.debug("Flush complete");
        List<Text> splits = new ArrayList<>(TestIngest.getSplitPoints(0, 100000, 67));
        List<Future<?>> futures = new ArrayList<>();
        var executor = Executors.newCachedThreadPool();
        for (int i = 0; i < 100; i++) {
            int idx1 = RANDOM.get().nextInt(splits.size() - 1);
            int idx2 = RANDOM.get().nextInt(splits.size() - (idx1 + 1)) + idx1 + 1;
            var future = executor.submit(() -> {
                c.tableOperations().compact(tableName, splits.get(idx1), splits.get(idx2), false, true);
                return null;
            });
            futures.add(future);
        }
        log.debug("Started compactions");
        // wait for all compactions to complete
        for (var future : futures) {
            future.get();
        }
        FunctionalTestUtils.assertNoDanglingFateLocks(getCluster());
    }
}

@Test
public void contiguousRangeTest() throws Exception {
    ServerContext ctx = getCluster().getServerContext();
    try (AccumuloClient accumuloClient = Accumulo.newClient().from(getClientProps()).build()) {
        // Need permission to write to metadata
        accumuloClient.securityOperations().grantTablePermission(accumuloClient.whoami(), AccumuloTable.METADATA.tableName(), TablePermission.WRITE);
        final int rows = 10000;
        final String tableName = getUniqueNames(1)[0];
        createTableAndDisableCompactions(accumuloClient, tableName);
        final TableId tableId = TableId.of(accumuloClient.tableOperations().tableIdMap().get(tableName));
        // Ingest 10000 rows start with row 1 and flush and verify data
        ingest(accumuloClient, rows, COLS, 10, 1, tableName);
        accumuloClient.tableOperations().flush(tableName, null, null, true);
        verify(accumuloClient, rows, COLS, 10, 1, tableName);
        // Bring tablet offline so we can modify file metadata
        accumuloClient.tableOperations().offline(tableName, true);
        try (TabletsMetadata tabletsMetadata = ctx.getAmple().readTablets().forTable(tableId).fetch(ColumnType.FILES, ColumnType.PREV_ROW).build()) {
            // Read each file (should only be 1), and split into 4 ranges
            for (TabletMetadata tabletMetadata : tabletsMetadata) {
                final KeyExtent ke = tabletMetadata.getExtent();
                // Create a mutation to delete the existing file metadata entry with infinite range
                TabletMutator mutator = ctx.getAmple().mutateTablet(ke);
                // Read each of the 10 files referenced by the table, should be 1 per tablet
                for (Entry<StoredTabletFile, DataFileValue> fileEntry : tabletMetadata.getFilesMap().entrySet()) {
                    StoredTabletFile file = fileEntry.getKey();
                    DataFileValue value = fileEntry.getValue();
                    // Create a mutation to delete the existing file metadata entry with infinite range
                    mutator.deleteFile(file);
                    // Add 4 contiguous ranges
                    final int ranges = 4;
                    for (int i = 1; i <= ranges; i++) {
                        int rowsPerRange = rows / ranges;
                        int endRow = i * rowsPerRange;
                        mutator.putFile(StoredTabletFile.of(file.getPath(), new Range(new Text("row_" + String.format("%010d", endRow - rowsPerRange)), false, new Text("row_" + String.format("%010d", endRow)), true)), new DataFileValue(value.getSize() / ranges, value.getNumEntries() / ranges));
                    }
                    mutator.mutate();
                }
            }
        }
        accumuloClient.tableOperations().online(tableName, true);
        verify(accumuloClient, rows, COLS, 10, 1, tableName);
        // Should have 4 files
        printAndVerifyFileMetadata(getServerContext(), tableId, 4);
        // Compact and verify the correct rows are still valid
        accumuloClient.tableOperations().compact(tableName, new CompactionConfig().setWait(true));
        verify(accumuloClient, rows, COLS, 10, 1, tableName);
        printAndVerifyFileMetadata(getServerContext(), tableId, 1);
    }
}

@Test
public void fencedRangeTest() throws Exception {
    ServerContext ctx = getCluster().getServerContext();
    try (AccumuloClient accumuloClient = Accumulo.newClient().from(getClientProps()).build()) {
        // Need permission to write to metadata
        accumuloClient.securityOperations().grantTablePermission(accumuloClient.whoami(), AccumuloTable.METADATA.tableName(), TablePermission.WRITE);
        final int rows = 10000;
        final int ranges = 4;
        int rowsPerRange = rows / ranges;
        final String tableName = getUniqueNames(1)[0];
        createTableAndDisableCompactions(accumuloClient, tableName);
        final TableId tableId = TableId.of(accumuloClient.tableOperations().tableIdMap().get(tableName));
        // Ingest 10000 rows start with row 1 and flush and verify data
        ingest(accumuloClient, rows, COLS, 10, 1, tableName);
        accumuloClient.tableOperations().flush(tableName, null, null, true);
        verify(accumuloClient, rows, COLS, 10, 1, tableName);
        // Bring tablet offline so we can modify file metadata
        accumuloClient.tableOperations().offline(tableName, true);
        try (TabletsMetadata tabletsMetadata = ctx.getAmple().readTablets().forTable(tableId).fetch(ColumnType.FILES, ColumnType.PREV_ROW).build()) {
            // Read each file, should just be 1.
            // Split into 4 ranges and skip the second so only 3/4 of the file should be readable
            for (TabletMetadata tabletMetadata : tabletsMetadata) {
                var fileEntry = tabletMetadata.getFilesMap().entrySet().stream().collect(MoreCollectors.onlyElement());
                StoredTabletFile file = fileEntry.getKey();
                DataFileValue value = fileEntry.getValue();
                final KeyExtent ke = tabletMetadata.getExtent();
                // Create a mutation to delete the existing file metadata entry with infinite range
                TabletMutator mutator = ctx.getAmple().mutateTablet(ke);
                mutator.deleteFile(file);
                // Add 3 ranges
                for (int i = 1; i <= ranges; i++) {
                    // Skip second range
                    if (i == 2) {
                        continue;
                    }
                    int endRow = i * rowsPerRange;
                    mutator.putFile(StoredTabletFile.of(file.getPath(), new Range(new Text("row_" + String.format("%010d", endRow - rowsPerRange)), false, new Text("row_" + String.format("%010d", endRow)), true)), new DataFileValue(value.getSize() / ranges, value.getNumEntries() / ranges));
                }
                mutator.mutate();
            }
        }
        // Write mutations to metadata and then bring the table back online
        accumuloClient.tableOperations().online(tableName, true);
        // Verify rows 1 - 2500 are readable
        verify(accumuloClient, rowsPerRange, COLS, 10, 1, tableName);
        // Rows 2501 - 5000 should not be fenced and not visible
        // Try and read 2500 rows and verify none are visible, should throw an exception with 0 rows
        // read
        verifyNoRows(accumuloClient, rowsPerRange, COLS, 10, rowsPerRange + 1, tableName);
        // Verify rows 5001 - 10000 are readable
        verify(accumuloClient, rowsPerRange * 2, COLS, 10, (rowsPerRange * 2) + 1, tableName);
        // Should have 3 rfiles in metadata
        printAndVerifyFileMetadata(getServerContext(), tableId, 3);
        // Compact and verify the correct rows are still valid
        accumuloClient.tableOperations().compact(tableName, new CompactionConfig().setWait(true));
        // Verify rows 1 - 2500 are readable
        verify(accumuloClient, rowsPerRange, COLS, 10, 1, tableName);
        // Rows 2501 - 5000 should not be fenced and not visible
        // Try and read 2500 rows and verify none are visible, should throw an exception with 0
        // rows read
        verifyNoRows(accumuloClient, rowsPerRange, COLS, 10, rowsPerRange + 1, tableName);
        // Verify rows 5001 - 10000 are readable
        verify(accumuloClient, rowsPerRange * 2, COLS, 10, (rowsPerRange * 2) + 1, tableName);
        // Should just have 1 file after compaction
        printAndVerifyFileMetadata(getServerContext(), tableId, 1);
    }
}

