@Test
public void test() throws Exception {
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        NewTableConfiguration ntc = new NewTableConfiguration();
        IteratorSetting iteratorSetting = new IteratorSetting(20, NullIterator.class);
        ntc.attachIterator(iteratorSetting, EnumSet.of(IteratorUtil.IteratorScope.minc));
        ntc.withSplits(new TreeSet<>(Set.of(new Text("a"), new Text("s"))));
        c.tableOperations().create(tableName, ntc);
        TableId tableId = TableId.of(c.tableOperations().tableIdMap().get(tableName));
        try (BatchWriter bw = c.createBatchWriter(tableName)) {
            Mutation m = new Mutation(new Text("r1"));
            m.put("acf", tableName, "1");
            bw.addMutation(m);
        }
        FunctionalTestUtils.checkRFiles(c, tableName, 3, 3, 0, 0);
        c.tableOperations().flush(tableName, null, null, true);
        FunctionalTestUtils.checkRFiles(c, tableName, 3, 3, 0, 0);
        Map<KeyExtent, OptionalLong> flushIds = FunctionalTestUtils.getFlushIds((ClientContext) c, tableId);
        assertEquals(3, flushIds.size());
        // There are three tablets in this table, but the batchWriter above only wrote to
        // one of the tablets. The table is using the default tablet availability (ONDEMAND),
        // so only one of the tablets was hosted and flushed. The other two tablets won't
        // have a flushId.
        KeyExtent extentWithData = new KeyExtent(tableId, new Text("s"), new Text("a"));
        flushIds.forEach((k, v) -> {
            if (k.equals(extentWithData)) {
                assertEquals(1, v.getAsLong());
            } else {
                assertTrue(v.isEmpty());
            }
        });
        try (BatchWriter bw = c.createBatchWriter(tableName)) {
            Mutation m = new Mutation(new Text("r2"));
            m.put("acf", tableName, "1");
            bw.addMutation(m);
        }
        c.tableOperations().flush(tableName, null, null, true);
        FunctionalTestUtils.checkRFiles(c, tableName, 3, 3, 0, 0);
        flushIds = FunctionalTestUtils.getFlushIds((ClientContext) c, tableId);
        assertEquals(3, flushIds.size());
        flushIds.forEach((k, v) -> {
            if (k.equals(extentWithData)) {
                assertEquals(2, v.getAsLong());
            } else {
                assertTrue(v.isEmpty());
            }
        });
        // Host all tablets
        c.tableOperations().setTabletAvailability(tableName, new Range(), TabletAvailability.HOSTED);
        // Wait for all tablets to be hosted
        Wait.waitFor(() -> ManagerAssignmentIT.countTabletsWithLocation(c, tableId) == 3);
        // Flush and validate that all flushIds are the same
        c.tableOperations().flush(tableName, null, null, true);
        FunctionalTestUtils.checkRFiles(c, tableName, 3, 3, 0, 0);
        flushIds = FunctionalTestUtils.getFlushIds((ClientContext) c, tableId);
        assertEquals(3, flushIds.size());
        flushIds.forEach((k, v) -> {
            assertEquals(3, v.getAsLong());
        });
        try (Scanner scanner = c.createScanner(tableName)) {
            assertEquals(0, Iterables.size(scanner), "Expected 0 Entries in table");
        }
    }
}

@Test
public void gcTest() throws Exception {
    killMacGc();
    final String table = "test_ingest";
    try (AccumuloClient c = Accumulo.newClient().from(getClientProperties()).build()) {
        c.tableOperations().create(table);
        c.tableOperations().setProperty(table, Property.TABLE_SPLIT_THRESHOLD.getKey(), "5K");
        VerifyParams params = new VerifyParams(getClientProperties(), table, 10_000);
        params.cols = 1;
        log.info("Ingesting files to {}", table);
        TestIngest.ingest(c, cluster.getFileSystem(), params);
        log.info("Compacting the table {}", table);
        c.tableOperations().compact(table, null, null, true, true);
        // the following path expects mini to be configured with a single volume
        final String pathString = cluster.getSiteConfiguration().get(Property.INSTANCE_VOLUMES) + "/" + Constants.TABLE_DIR + "/1/*/*.rf";
        log.info("Counting files in path: {}", pathString);
        int before = countFiles(pathString);
        log.info("Counted {} files in path: {}", before, pathString);
        while (true) {
            Thread.sleep(SECONDS.toMillis(1));
            int more = countFiles(pathString);
            if (more <= before) {
                break;
            }
            before = more;
        }
        // restart GC
        log.info("Restarting GC...");
        getCluster().start();
        Thread.sleep(SECONDS.toMillis(15));
        log.info("Again Counting files in path: {}", pathString);
        int after = countFiles(pathString);
        log.info("Counted {} files in path: {}", after, pathString);
        VerifyIngest.verifyIngest(c, params);
        assertTrue(after < before, "After count " + after + " was not less than " + before);
    }
}

