@Test
public void testBatchScanPauses() throws Exception {
    String table = getUniqueNames(1)[0];
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        TableOperations to = client.tableOperations();
        to.create(table);
