        try (BatchScanner dataConsumingScanner = client.createBatchScanner(table);
            Scanner memoryConsumingScanner = client.createScanner(table)) {
            dataConsumingScanner.addScanIterator(new IteratorSetting(11, SlowIterator.class, Map.of("sleepTime", "500")));
            dataConsumingScanner.setRanges(Collections.singletonList(new Range()));
            Iterator<Entry<Key, Value>> iter = dataConsumingScanner.iterator();
            AtomicInteger fetched = new AtomicInteger(0);
            Thread t = new Thread(() -> {
                int i = 0;
                while (iter.hasNext()) {
                    iter.next();
                    fetched.set(++i);
                }
            });
            memoryConsumingScanner.addScanIterator(new IteratorSetting(11, MemoryConsumingIterator.class, Map.of()));
            memoryConsumingScanner.setBatchSize(1);
            memoryConsumingScanner.setReadaheadThreshold(Long.MAX_VALUE);
            t.start();
            // Wait until the dataConsumingScanner has started fetching data
            int currentCount = fetched.get();
            while (currentCount == 0) {
                Thread.sleep(500);
                currentCount = fetched.get();
            }
            // This should block until the LowMemoryDetector runs and notices that the
            // VM is low on memory.
            Iterator<Entry<Key, Value>> consumingIter = memoryConsumingScanner.iterator();
            assertTrue(consumingIter.hasNext());
            // Confirm that some data was fetched by the dataConsumingScanner
            currentCount = fetched.get();
            assertTrue(currentCount > 0 && currentCount < 100);
            // Grab the current paused count, wait two seconds and then confirm that
            // the number of rows fetched by the memoryConsumingScanner has not increased
            // and that the scan delay counter has increased.
            double returned = SCAN_RETURNED_EARLY.doubleValue();
            double paused = SCAN_START_DELAYED.doubleValue();
            Thread.sleep(1500);
            assertEquals(currentCount, fetched.get());
            assertTrue(SCAN_START_DELAYED.doubleValue() >= paused);
            assertTrue(SCAN_RETURNED_EARLY.doubleValue() >= returned);
            waitFor(() -> LOW_MEM_DETECTED.get() == 1);
            // Perform the check again
            paused = SCAN_START_DELAYED.doubleValue();
            returned = SCAN_RETURNED_EARLY.doubleValue();
            Thread.sleep(1500);
            assertEquals(currentCount, fetched.get());
            assertTrue(SCAN_START_DELAYED.doubleValue() >= paused);
            assertTrue(SCAN_RETURNED_EARLY.doubleValue() >= returned);
            // check across multiple low memory checks and metric updates that low memory detected
            // remains set
            int checkCount = 0;
            while (checkCount++ < 5) {
                Thread.sleep(5_000);
                LOG.debug("Check low memory still set. Low Memory Flag: {}, Check count: {}", LOW_MEM_DETECTED.get(), checkCount);
                assertEquals(1, LOW_MEM_DETECTED.get());
            }
            // Free the memory which will allow the pausing scanner to continue
            freeServerMemory(client);
            t.join();
            assertEquals(30, fetched.get());
            // allow metric collection to cycle.
            waitFor(() -> LOW_MEM_DETECTED.get() == 0);
        } finally {
            to.delete(table);
        }
    }
}

@Test
public void tooManyFilesMergeTest() throws Exception {
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        c.tableOperations().create(tableName, new NewTableConfiguration().setProperties(Map.of(Property.TABLE_MAJC_RATIO.getKey(), "20000", Property.TABLE_MERGE_FILE_MAX.getKey(), "12345")));
        c.tableOperations().addSplits(tableName, IntStream.range(1, 10001).mapToObj(i -> String.format("%06d", i)).map(Text::new).collect(Collectors.toCollection(TreeSet::new)));
        c.tableOperations().addSplits(tableName, IntStream.range(10001, 20001).mapToObj(i -> String.format("%06d", i)).map(Text::new).collect(Collectors.toCollection(TreeSet::new)));
        // add two bogus files to each tablet, creating 40K file entries
        c.tableOperations().offline(tableName, true);
        try (var tablets = getCluster().getServerContext().getAmple().readTablets().forTable(getCluster().getServerContext().getTableId(tableName)).build();
            var mutator = getCluster().getServerContext().getAmple().mutateTablets()) {
            int fc = 0;
            for (var tabletMeta : tablets) {
                StoredTabletFile f1 = StoredTabletFile.of(new Path("file:///accumulo/tables/1/" + tabletMeta.getDirName() + "/F" + fc++ + ".rf"));
                StoredTabletFile f2 = StoredTabletFile.of(new Path("file:///accumulo/tables/1/" + tabletMeta.getDirName() + "/F" + fc++ + ".rf"));
                DataFileValue dfv1 = new DataFileValue(4200, 42);
                DataFileValue dfv2 = new DataFileValue(4200, 42);
                mutator.mutateTablet(tabletMeta.getExtent()).putFile(f1, dfv1).putFile(f2, dfv2).mutate();
            }
        }
        c.tableOperations().online(tableName, true);
        // should fail to merge because there are too many files in the merge range
        var exception = assertThrows(AccumuloException.class, () -> c.tableOperations().merge(tableName, null, null));
        // message should contain the observed number of files
        assertTrue(exception.getMessage().contains("40002"));
        // message should contain the max files limit it saw
        assertTrue(exception.getMessage().contains("12345"));
        assertEquals(20000, c.tableOperations().listSplits(tableName).size());
        // attempt to merge smaller ranges with less files, should work.. want to make sure the
        // aborted merge did not leave the table in a bad state
        Text prev = null;
        for (int i = 1000; i <= 20000; i += 1000) {
            Text end = new Text(String.format("%06d", i));
            c.tableOperations().merge(tableName, prev, end);
            prev = end;
        }
        assertEquals(20, c.tableOperations().listSplits(tableName).size());
        try (var tablets = getCluster().getServerContext().getAmple().readTablets().forTable(getCluster().getServerContext().getTableId(tableName)).build()) {
            assertEquals(40002, tablets.stream().mapToInt(tabletMetadata -> tabletMetadata.getFiles().size()).sum());
        }
    }
}

