// Test that merge handles metadata from compactions
@Test
public void testCompactionMetadata() throws Exception {
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        c.tableOperations().create(tableName);
        var split = new Text("m");
        c.tableOperations().addSplits(tableName, new TreeSet<>(List.of(split)));
        TableId tableId = getCluster().getServerContext().getTableId(tableName);
        // add metadata from compactions to tablets prior to merge
        try (var tabletsMutator = getCluster().getServerContext().getAmple().mutateTablets()) {
            for (var extent : List.of(new KeyExtent(tableId, split, null), new KeyExtent(tableId, null, split))) {
                var tablet = tabletsMutator.mutateTablet(extent);
                ExternalCompactionId ecid = ExternalCompactionId.generate(UUID.randomUUID());
                FateInstanceType type = FateInstanceType.fromTableId(tableId);
                FateId fateId = FateId.from(type, UUID.randomUUID());
                ReferencedTabletFile tmpFile = ReferencedTabletFile.of(new Path("file:///accumulo/tables/t-0/b-0/c1.rf"));
                CompactorGroupId ceid = CompactorGroupId.of("G1");
                Set<StoredTabletFile> jobFiles = Set.of(StoredTabletFile.of(new Path("file:///accumulo/tables/t-0/b-0/b2.rf")));
                CompactionMetadata ecMeta = new CompactionMetadata(jobFiles, tmpFile, "localhost:4444", CompactionKind.SYSTEM, (short) 2, ceid, false, fateId);
                tablet.putExternalCompaction(ecid, ecMeta);
                tablet.mutate();
            }
        }
        // ensure data is in metadata table as expected
        try (var tablets = getCluster().getServerContext().getAmple().readTablets().forTable(tableId).build()) {
            for (var tablet : tablets) {
                assertFalse(tablet.getExternalCompactions().isEmpty());
            }
        }
        c.tableOperations().merge(tableName, null, null);
        // ensure merge operation remove compaction entries
        try (var tablets = getCluster().getServerContext().getAmple().readTablets().forTable(tableId).build()) {
            for (var tablet : tablets) {
                assertTrue(tablet.getExternalCompactions().isEmpty());
            }
        }
    }
}

@Test
public void testFlushAndCompact() throws Exception {
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        String[] tableNames = getUniqueNames(2);
        // create a table to write some data to metadata table
        c.tableOperations().create(tableNames[0]);
        try (Scanner rootScanner = c.createScanner(AccumuloTable.ROOT.tableName(), Authorizations.EMPTY)) {
            rootScanner.setRange(TabletsSection.getRange());
            rootScanner.fetchColumnFamily(DataFileColumnFamily.NAME);
            Set<String> files1 = new HashSet<>();
            for (Entry<Key, Value> entry : rootScanner) {
                files1.add(entry.getKey().getColumnQualifier().toString());
            }
            c.tableOperations().create(tableNames[1]);
            c.tableOperations().flush(AccumuloTable.METADATA.tableName(), null, null, true);
            Set<String> files2 = new HashSet<>();
            for (Entry<Key, Value> entry : rootScanner) {
                files2.add(entry.getKey().getColumnQualifier().toString());
            }
            // flush of metadata table should change file set in root table
            assertTrue(!files2.isEmpty());
            assertNotEquals(files1, files2);
            c.tableOperations().compact(AccumuloTable.METADATA.tableName(), null, null, false, true);
            Set<String> files3 = new HashSet<>();
            for (Entry<Key, Value> entry : rootScanner) {
                files3.add(entry.getKey().getColumnQualifier().toString());
            }
            // compaction of metadata table should change file set in root table
            assertNotEquals(files2, files3);
        }
    }
}

