public void test() throws Exception {
    try (AccumuloClient c = Accumulo.newClient().from(getClientProperties()).build()) {
        SortedSet<Text> splits = new TreeSet<>();
        for (int i = 0; i < 1000; i++) {
            splits.add(new Text(String.format("%03d", i)));
        }
        c.tableOperations().setProperty(AccumuloTable.METADATA.tableName(), Property.TABLE_SPLIT_THRESHOLD.getKey(), "10000");
        // propagation time
        Thread.sleep(SECONDS.toMillis(5));
        for (int i = 0; i < 2; i++) {
            String tableName = "table" + i;
            log.info("Creating {} with splits", tableName);
            NewTableConfiguration ntc = new NewTableConfiguration().withSplits(splits).withInitialTabletAvailability(TabletAvailability.HOSTED);
            c.tableOperations().create(tableName, ntc);
            log.info("flushing");
            c.tableOperations().flush(AccumuloTable.METADATA.tableName(), null, null, true);
            c.tableOperations().flush(AccumuloTable.ROOT.tableName(), null, null, true);
        }
        while (true) {
            ClientContext context = (ClientContext) c;
            ManagerMonitorInfo stats = ThriftClientTypes.MANAGER.execute(context, client -> client.getManagerStats(TraceUtil.traceInfo(), context.rpcCreds()));
            int tablets = 0;
            for (TabletServerStatus tserver : stats.tServerInfo) {
                for (Entry<String, TableInfo> entry : tserver.tableMap.entrySet()) {
                    if (entry.getKey().startsWith("!") || entry.getKey().startsWith("+")) {
                        continue;
                    }
                    tablets += entry.getValue().onlineTablets;
                }
            }
            log.info("Online tablets " + tablets);
            if (tablets == 2002) {
                break;
            }
            Thread.sleep(SECONDS.toMillis(1));
        }
    }
}

