@Test
public void bulkImportThatCantSplitHangsCompaction() throws Exception {
    /*
     * There was a bug where a bulk import into a tablet with the following conditions would cause
     * compactions to hang.
     *
     * 1. Tablet where the files sizes indicates its needs to split
     *
     * 2. Row with many columns in the tablet that is unsplittable
     *
     * This happened because the bulk import plus an attempted split would leave the tablet in a bad
     * internal state for compactions.
     */
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        SortedSet<Text> initialSplits = new TreeSet<>(List.of(new Text("r1")));
        c.tableOperations().create(tableName, new NewTableConfiguration().setProperties(singletonMap(Property.TABLE_SPLIT_THRESHOLD.getKey(), "10K")).withSplits(initialSplits));
        var random = RANDOM.get();
        byte[] val = new byte[100];
        String dir = getDir();
        String file = dir + "/f1.rf";
        // create a file with a single row and lots of columns. The files size will exceed the split
        // threshold configured above.
        try (RFileWriter writer = RFile.newWriter().to(file).withFileSystem(getFileSystem()).build()) {
            writer.startDefaultLocalityGroup();
            for (int i = 0; i < 1000; i++) {
                random.nextBytes(val);
                writer.append(new Key("r1", "f1", String.format("%09d", i)), new Value(Base64.getEncoder().encodeToString(val)));
            }
        }
        // import the file
        c.tableOperations().importDirectory(dir).to(tableName).load();
        // wait for the tablet to be marked unsplittable
        var ctx = getServerContext();
        Wait.waitFor(() -> {
            var tableId = ctx.getTableId(tableName);
            try (var tabletsMeta = ctx.getAmple().readTablets().forTable(tableId).build()) {
                return tabletsMeta.stream().filter(tabletMetadata -> tabletMetadata.getUnSplittable() != null).count() == 1;
            }
        });
        // tablet should not be able to split
        var splits = c.tableOperations().listSplits(tableName).stream().map(Text::toString).collect(Collectors.toSet());
        assertEquals(Set.of("r1"), splits);
        Thread.sleep(1000);
        c.tableOperations().compact(tableName, new CompactionConfig().setWait(true));
        // should have over 100K of data in the values
        assertTrue(c.createScanner(tableName).stream().mapToLong(entry -> entry.getValue().getSize()).sum() > 100_000);
        // should have 1000 entries
        assertEquals(1000, c.createScanner(tableName).stream().count());
    }
}

/**
 * Test attempting to split a tablet that has an unexpected column
 */
@Test
public void testUnexpectedColumn() throws Exception {
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        String tableName = getUniqueNames(1)[0];
        c.tableOperations().create(tableName);
        var ctx = getServerContext();
        var tableId = ctx.getTableId(tableName);
        var extent = new KeyExtent(tableId, null, null);
        // This column is not expected to be present
        var tabletMutator = ctx.getAmple().mutateTablet(extent);
        tabletMutator.setMerged();
        tabletMutator.mutate();
        var tabletMetadata = ctx.getAmple().readTablets().forTable(tableId).saveKeyValues().build().stream().collect(MoreCollectors.onlyElement());
        assertEquals(extent, tabletMetadata.getExtent());
        // remove the srv:lock column for tests as this will change
        // because we are changing the metadata from the IT.
        var original = tabletMetadata.getKeyValues().stream().collect(Collectors.toMap(Entry::getKey, Entry::getValue, (a1, b1) -> b1, TreeMap::new));
        assertTrue(original.keySet().removeIf(LOCK_COLUMN::hasColumns));
        // Split operation should fail because of the unexpected column.
        var splits = new TreeSet<>(List.of(new Text("m")));
        assertThrows(AccumuloException.class, () -> c.tableOperations().addSplits(tableName, splits));
        assertEquals(Set.of(), Set.copyOf(c.tableOperations().listSplits(tableName)));
        // The tablet should be left in a bad state, so simulate a manual cleanup
        var tabletMetadata2 = ctx.getAmple().readTablets().forTable(tableId).saveKeyValues().build().stream().collect(MoreCollectors.onlyElement());
        assertEquals(extent, tabletMetadata.getExtent());
        // tablet should have an operation id set, but nothing else changed
        var kvCopy = tabletMetadata2.getKeyValues().stream().collect(Collectors.toMap(Entry::getKey, Entry::getValue, (a, b) -> b, TreeMap::new));
        assertTrue(kvCopy.keySet().removeIf(LOCK_COLUMN::hasColumns));
        assertTrue(kvCopy.keySet().removeIf(OPID_COLUMN::hasColumns));
        assertEquals(original, kvCopy);
        // remove the offending columns
        tabletMutator = ctx.getAmple().mutateTablet(extent);
        tabletMutator.deleteMerged();
        tabletMutator.deleteOperation();
        tabletMutator.mutate();
        // after cleaning up the tablet metadata, should be able to split
        c.tableOperations().addSplits(tableName, splits);
        assertEquals(Set.of(new Text("m")), Set.copyOf(c.tableOperations().listSplits(tableName)));
    }
}

@SuppressFBWarnings(value = { "PREDICTABLE_RANDOM", "DMI_RANDOM_USED_ONLY_ONCE" }, justification = "predictable random is ok for testing")
@Test
public void testOneMillionTablets() throws Exception {
    try (AccumuloClient c = Accumulo.newClient().from(getClientProperties()).build()) {
        String tableName = getUniqueNames(1)[0];
        c.tableOperations().create(tableName);
        // pre split the metadata table
        var tableId = getServerContext().getTableId(tableName);
        SortedSet<Text> metaSplits = new TreeSet<>();
        for (int i = 1; i < 10; i++) {
            String metaSplit = String.format("%s;%010d", tableId, 100_000_000 / 10 * i);
            metaSplits.add(new Text(metaSplit));
        }
        c.tableOperations().addSplits(AccumuloTable.METADATA.tableName(), metaSplits);
        SortedSet<Text> splits = new TreeSet<>();
        for (int i = 100; i < 100_000_000; i += 100) {
            String split = String.format("%010d", i);
            splits.add(new Text(split));
            if (splits.size() >= 10000) {
                addSplits(c, tableName, splits, log);
            }
        }
        if (!splits.isEmpty()) {
            addSplits(c, tableName, splits, log);
        }
        var rows = IntStream.concat(new Random().ints(98, 0, 100_000_000).flatMap(i -> IntStream.of(i, i + 1)), IntStream.of(0, 1, 99_999_998, 99_999_999)).toArray();
        long t1 = System.currentTimeMillis();
        try (var scanner = c.createBatchScanner(tableName)) {
            var ranges = Arrays.stream(rows).mapToObj(rowInt -> String.format("%010d", rowInt)).map(Range::new).collect(Collectors.toList());
            scanner.setRanges(ranges);
            assertEquals(0, scanner.stream().count());
        }
        long t2 = System.currentTimeMillis();
        log.info("Time to scan {} rows {}ms", rows.length, (t2 - t1));
        t1 = System.currentTimeMillis();
        try (var writer = c.createBatchWriter(tableName)) {
            for (var rowInt : rows) {
                var row = String.format("%010d", rowInt);
                Mutation m = new Mutation(row);
                m.put("c", "x", "200");
                m.put("c", "y", "900");
                m.put("c", "z", "300");
                writer.addMutation(m);
            }
        }
        t2 = System.currentTimeMillis();
        log.info("Time to write {} rows {}ms", rows.length, (t2 - t1));
        // read and write to a few of the 1 million tablets. The following should touch the first,
        // last, and a few middle tablets.
        for (var rowInt : rows) {
            var row = String.format("%010d", rowInt);
            long t3 = System.currentTimeMillis();
            verifyRow(c, tableName, row, Map.of("x", "200", "y", "900", "z", "300"));
            long t4 = System.currentTimeMillis();
            log.info("Row: {}  scan: {}ms", row, t4 - t3);
        }
        long count;
        t1 = System.currentTimeMillis();
        try (var tabletInformation = c.tableOperations().getTabletInformation(tableName, new Range())) {
            count = tabletInformation.count();
        }
        t2 = System.currentTimeMillis();
        assertEquals(1_000_000, count);
        log.info("Time to scan all tablets information : {}ms", t2 - t1);
        t1 = System.currentTimeMillis();
        var iterSetting = new IteratorSetting(100, XFilter.class);
        c.tableOperations().compact(tableName, new CompactionConfig().setIterators(List.of(iterSetting)).setWait(true).setFlush(true));
        t2 = System.currentTimeMillis();
        log.info("Time to compact all tablets : {}ms", t2 - t1);
        var expected = Map.of("y", "900", "z", "300");
        vefifyData(rows, c, tableName, expected, ConsistencyLevel.IMMEDIATE);
        // We are done with tableName, except for deleting it later. Modify the tablets
        // availability to UNHOSTED so that when the clone operation happens below none
        // of the tablets for the clone table will be hosted. The subsequent merge operation
        // is a metadata-only operation unless the tablet is hosted. If the tablet is hosted
        // then the tablet has to be closed making the merge operation take longer.
        c.tableOperations().setTabletAvailability(tableName, new Range(), TabletAvailability.UNHOSTED);
        // clone the table to test cloning with lots of tablets and also to give merge its own table
        // to work on
        var cloneName = tableName + "_clone";
        t1 = System.currentTimeMillis();
        c.tableOperations().clone(tableName, cloneName, CloneConfiguration.builder().build());
        t2 = System.currentTimeMillis();
        log.info("Time to clone table : {}ms", t2 - t1);
        vefifyData(rows, c, cloneName, expected, ConsistencyLevel.EVENTUAL);
        TableId tid = TableId.of(c.tableOperations().tableIdMap().get(cloneName));
        assertEquals(0, ManagerAssignmentIT.countTabletsWithLocation(c, tid));
        // merge the clone, so that delete table can run later on tablet with lots and lots of tablets
        t1 = System.currentTimeMillis();
        c.tableOperations().merge(cloneName, null, null);
        t2 = System.currentTimeMillis();
        log.info("Time to merge all tablets : {}ms", t2 - t1);
        vefifyData(rows, c, cloneName, expected, ConsistencyLevel.EVENTUAL);
        t1 = System.currentTimeMillis();
        c.tableOperations().delete(tableName);
        t2 = System.currentTimeMillis();
        log.info("Time to delete original table : {}ms", t2 - t1);
        t1 = System.currentTimeMillis();
        c.tableOperations().delete(cloneName);
        t2 = System.currentTimeMillis();
        log.info("Time to delete clone table : {}ms", t2 - t1);
    }
}

