@Test
public void testManyFiles() throws Exception {
    final String table = getUniqueNames(1)[0];
    try (AccumuloClient c = Accumulo.newClient().from(getClientProps()).build()) {
        int q = 0;
        SortedSet<Text> partitionKeys = new TreeSet<>();
        for (int split = 100_000; split < 1_000_000; split += 100_000) {
            partitionKeys.add(new Text(String.format("%06d", split)));
        }
        NewTableConfiguration ntc = new NewTableConfiguration().enableSummarization(SummarizerConfiguration.builder(FamilySummarizer.class).build()).withSplits(partitionKeys);
        c.tableOperations().create(table, ntc);
        Map<String, Long> famCounts = new HashMap<>();
        for (int t = 0; t < 20; t++) {
            // this loop should cause a varying number of files and compactions
            try (BatchWriter bw = c.createBatchWriter(table)) {
                for (int i = 0; i < 10000; i++) {
                    String row = String.format("%06d", RANDOM.get().nextInt(1_000_000));
                    String fam = String.format("%03d", RANDOM.get().nextInt(100));
                    String qual = String.format("%06d", q++);
                    write(bw, row, fam, qual, "val");
                    famCounts.merge(fam, 1L, Long::sum);
                }
            }
            List<Summary> summaries = c.tableOperations().summaries(table).flush(true).retrieve();
            assertEquals(1, summaries.size());
            CounterSummary cs = new CounterSummary(summaries.get(0));
            assertEquals(famCounts, cs.getCounters());
            FileStatistics fileStats = summaries.get(0).getFileStatistics();
            assertEquals(0, fileStats.getInaccurate());
            assertTrue(fileStats.getTotal() >= 10, "Saw " + fileStats.getTotal() + " files expected >=10");
        }
    }
}

@Test
public void testSuspendMarker() throws Exception {
    try (AccumuloClient c = Accumulo.newClient().from(getClientProperties()).build()) {
        MiniAccumuloClusterControl clusterControl = getCluster().getClusterControl();
        List<Process> processes = clusterControl.getTabletServers(SUSPEND_RG);
        assertNotNull(processes);
        assertEquals(1, processes.size());
        String tableName = getUniqueNames(1)[0];
        NewTableConfiguration ntc = new NewTableConfiguration();
        ntc.withInitialTabletAvailability(TabletAvailability.HOSTED);
        ntc.setProperties(Map.of(Property.TABLE_SUSPEND_DURATION.getKey(), "30s", TableLoadBalancer.TABLE_ASSIGNMENT_GROUP_PROPERTY, SUSPEND_RG));
        c.tableOperations().create(tableName, ntc);
        c.instanceOperations().waitForBalance();
        TableId suspendTableTid = TableId.of(c.tableOperations().tableIdMap().get(tableName));
        TabletMetadata originalTM;
        try (TabletsMetadata tms = TabletsMetadata.builder(c).forTable(suspendTableTid).build()) {
            originalTM = tms.stream().collect(onlyElement());
            assertNull(originalTM.getSuspend());
        }
        clusterControl.stopTabletServerGroup(SUSPEND_RG);
        Wait.waitFor(() -> suspendColumnExists(c, suspendTableTid), 60_000);
        try (var tabletsMutator = getCluster().getServerContext().getAmple().conditionallyMutateTablets()) {
            tabletsMutator.mutateTablet(originalTM.getExtent()).requireAbsentOperation().requireSame(originalTM, SUSPEND).putTabletAvailability(TabletAvailability.ONDEMAND).submit(tabletMetadata -> false);
            // This should fail because the original tablet metadata does not have a suspend column
            // and the current tablet metadata does.
            assertEquals(REJECTED, tabletsMutator.process().get(originalTM.getExtent()).getStatus());
        }
        // test require same when the tablet metadata passed in has a suspend column set
        var suspendedTM = getCluster().getServerContext().getAmple().readTablet(originalTM.getExtent());
        assertNotNull(suspendedTM.getSuspend());
        try (var tabletsMutator = getCluster().getServerContext().getAmple().conditionallyMutateTablets()) {
            tabletsMutator.mutateTablet(originalTM.getExtent()).requireAbsentOperation().requireSame(suspendedTM, SUSPEND).putFlushNonce(6789).submit(tabletMetadata -> false);
            // This should succeed because the tablet metadata does have a suspend column and the
            // current tablet metadata does.
            assertEquals(ACCEPTED, tabletsMutator.process().get(originalTM.getExtent()).getStatus());
        }
        clusterControl.start(ServerType.TABLET_SERVER);
        Wait.waitFor(() -> !suspendColumnExists(c, suspendTableTid), 60_000);
        try (var tabletsMutator = getCluster().getServerContext().getAmple().conditionallyMutateTablets()) {
            tabletsMutator.mutateTablet(originalTM.getExtent()).requireAbsentOperation().requireSame(originalTM, SUSPEND).putTabletAvailability(TabletAvailability.ONDEMAND).submit(tabletMetadata -> false);
            // This should succeed because the original tablet metadata does not have a suspend column
            // and the current tablet metadata does not also because the tablet server for the SUSPEND
            // resource group was restarted.
            assertEquals(ACCEPTED, tabletsMutator.process().get(originalTM.getExtent()).getStatus());
        }
    }
}

