@Test
public void test() throws Exception {
    MiniAccumuloClusterImpl mac = getCluster();
    MiniAccumuloClusterControl control = mac.getClusterControl();
    control.stop(GARBAGE_COLLECTOR);
    ServerContext context = getServerContext();
    try (AccumuloClient c = Accumulo.newClient().from(getClientProperties()).build()) {
        String tableName = getUniqueNames(1)[0];
        c.tableOperations().create(tableName);
        writeSomeData(c, tableName, 1, 1);
        // wal markers are added lazily
        Map<String, WalState> wals = getWALsAndAssertCount(context, 2);
        assertEquals(2, countInUse(wals.values()), "all WALs should be in use");
        // roll log, get a new next
        writeSomeData(c, tableName, 1001, 50);
        Map<String, WalState> walsAfterRoll = getWALsAndAssertCount(context, 3);
        assertTrue(walsAfterRoll.keySet().containsAll(wals.keySet()), "new WALs should be a superset of the old WALs");
        assertEquals(3, countInUse(walsAfterRoll.values()), "all WALs should be in use");
        // flush the tables
        for (String table : new String[] { tableName, AccumuloTable.METADATA.tableName(), AccumuloTable.ROOT.tableName(), AccumuloTable.FATE.tableName() }) {
            c.tableOperations().flush(table, null, null, true);
        }
        Thread.sleep(SECONDS.toMillis(1));
        // rolled WAL is no longer in use, but needs to be GC'd
        Map<String, WalState> walsAfterflush = getWALsAndAssertCount(context, 3);
        assertEquals(2, countInUse(walsAfterflush.values()), "inUse should be 2");
        // let the GC run for a little bit
        control.start(GARBAGE_COLLECTOR);
        Thread.sleep(SECONDS.toMillis(5));
        // make sure the unused WAL goes away
        getWALsAndAssertCount(context, 2);
        control.stop(GARBAGE_COLLECTOR);
        // restart the tserver, but don't run recovery on all tablets
        control.stop(TABLET_SERVER);
        // this delays recovery on the normal tables
        assertEquals(0, cluster.exec(SetGoalState.class, "SAFE_MODE").getProcess().waitFor());
        control.start(TABLET_SERVER);
        // wait for the metadata table to go back online
        getRecoveryMarkers(c);
        // allow a little time for the manager to notice ASSIGNED_TO_DEAD_SERVER tablets
        Thread.sleep(SECONDS.toMillis(5));
        Map<KeyExtent, List<String>> markers = getRecoveryMarkers(c);
        // log.debug("markers " + markers);
        // There should be markers for the created table and also the Fate and ScanRef tables
        assertEquals(3, markers.size(), "three tablets should have markers");
        assertTrue(markers.keySet().stream().anyMatch(extent -> extent.tableId().canonical().equals("1")), "tableId of the keyExtent should be 1");
        assertTrue(markers.keySet().stream().anyMatch(extent -> extent.tableId().equals(AccumuloTable.FATE.tableId())), "tableId of the Fate table can't be found");
        assertTrue(markers.keySet().stream().anyMatch(extent -> extent.tableId().equals(AccumuloTable.SCAN_REF.tableId())), "tableId of the ScanRef table can't be found");
        // put some data in the WAL
        assertEquals(0, cluster.exec(SetGoalState.class, "NORMAL").getProcess().waitFor());
        verifySomeData(c, tableName, 1001 * 50 + 1);
        writeSomeData(c, tableName, 100, 100);
        Map<String, WalState> walsAfterRestart = getWALsAndAssertCount(context, 4);
        // log.debug("wals after " + walsAfterRestart);
        assertEquals(4, countInUse(walsAfterRestart.values()), "used WALs after restart should be 4");
        control.start(GARBAGE_COLLECTOR);
        Thread.sleep(SECONDS.toMillis(5));
        Map<String, WalState> walsAfterRestartAndGC = getWALsAndAssertCount(context, 2);
        assertEquals(2, countInUse(walsAfterRestartAndGC.values()), "logs in use should be 2");
    }
}

@SuppressFBWarnings(value = "UNENCRYPTED_SOCKET", justification = "unencrypted socket is okay for testing")
@Test
public void test() throws Exception {
    Properties props = getClientProperties();
    try (AccumuloClient c = Accumulo.newClient().from(props).build()) {
        String[] tableNames = getUniqueNames(3);
        for (String tableName : tableNames) {
            c.tableOperations().create(tableName);
        }
        c.tableOperations().list();
        String zooKeepers = ClientProperty.INSTANCE_ZOOKEEPERS.getValue(props);
        // expect about 30-45 base + about 12 per table in a single-node 3-tserver instance
        final long MIN = 75L;
        final long MAX = 300L;
        long total = 0;
        final HostAndPort hostAndPort = HostAndPort.fromString(zooKeepers);
        for (int i = 0; i < 5; i++) {
            try (Socket socket = new Socket(hostAndPort.getHost(), hostAndPort.getPort())) {
                socket.getOutputStream().write("wchs\n".getBytes(UTF_8), 0, 5);
                byte[] buffer = new byte[1024];
                int n = socket.getInputStream().read(buffer);
                String response = new String(buffer, 0, n, UTF_8);
                total = Long.parseLong(response.split(":")[1].trim());
                log.info("Total: {}", total);
                if (total > MIN && total < MAX) {
                    break;
                }
                log.debug("Expected number of watchers to be contained in ({}, {}), currently have {}" + ". Sleeping and retrying", MIN, MAX, total);
                Thread.sleep(5000);
            }
        }
        log.info("Number of watchers to be expected in range: ({}, {}), currently have {}", MIN, MAX, total);
        assertTrue(total > MIN && total < MAX, "Expected number of watchers to be contained in (" + MIN + ", " + MAX + "), but actually was " + total);
    }
}

