@Test
public void test() throws Exception {
    // make a table
    final String tableName = getUniqueNames(1)[0];
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        client.tableOperations().create(tableName);
        // make the world's slowest scanner
        try (Scanner scanner = client.createScanner(tableName, Authorizations.EMPTY)) {
            final IteratorSetting cfg = new IteratorSetting(100, SlowIterator.class);
            // Wait long enough to be sure we can catch it, but not indefinitely.
            SlowIterator.setSeekSleepTime(cfg, MINUTES.toMillis(1));
            scanner.addScanIterator(cfg);
            // create a thread to interrupt the slow scan
            final Thread scanThread = Thread.currentThread();
            Thread thread = new Thread(() -> {
                try {
                    // ensure the scan is running: not perfect, the metadata tables could be scanned, too.
                    ServerId tserver = client.instanceOperations().getServers(ServerId.Type.TABLET_SERVER).iterator().next();
                    do {
                        ArrayList<ActiveScan> scans = new ArrayList<>(client.instanceOperations().getActiveScans(List.of(tserver)));
                        // Remove scans not against our table and not owned by us
                        scans.removeIf(scan -> !getAdminPrincipal().equals(scan.getUser()) || !tableName.equals(scan.getTable()));
                        if (!scans.isEmpty()) {
                            // We found our scan
                            break;
                        }
                    } while (true);
                } catch (Exception e) {
                    e.printStackTrace();
                }
                // BAM!
                scanThread.interrupt();
            });
            thread.start();
            try {
                // Use the scanner, expect problems
                assertThrows(RuntimeException.class, () -> Iterators.size(scanner.iterator()), "Scan should not succeed");
            } finally {
                thread.join();
            }
        }
    }
}

