public void testClientConfiguration() throws Exception {
    // Ensure no scan servers running
    Wait.waitFor(() -> getCluster().getServerContext().getServerPaths().getScanServer(rg -> true, AddressSelector.all(), true).isEmpty());
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        final String tableName = getUniqueNames(1)[0];
        final int ingestedEntryCount = ScanServerIT.createTableAndIngest(client, tableName, null, 10, 10, "colf");
        assertEquals(100, ingestedEntryCount);
        try (Scanner scanner = client.createScanner(tableName, Authorizations.EMPTY)) {
            scanner.setRange(new Range());
            scanner.setConsistencyLevel(ConsistencyLevel.EVENTUAL);
            assertEquals(ingestedEntryCount, Iterables.size(scanner), "The scanner should fall back to the tserver and should have seen all ingested and flushed entries");
            // Allow one scan server to be started at this time
            getCluster().getConfig().getClusterServerConfiguration().setNumDefaultScanServers(1);
            // Start a ScanServer. No group specified, should be in the default group.
            getCluster().getClusterControl().start(ServerType.SCAN_SERVER, "localhost");
            Wait.waitFor(() -> getCluster().getServerContext().getServerPaths().getScanServer(rg -> true, AddressSelector.all(), true).size() == 1, 30_000);
            Wait.waitFor(() -> getCluster().getServerContext().getServerPaths().getScanServer(rg -> rg.equals(ScanServerSelector.DEFAULT_SCAN_SERVER_GROUP_NAME), AddressSelector.all(), true).size() > 0);
            assertEquals(ingestedEntryCount, Iterables.size(scanner), "The scan server scanner should have seen all ingested and flushed entries");
            // if scanning against tserver would see the following, but should not on scan server
            final int additionalIngest1 = ScanServerIT.ingest(client, tableName, 10, 10, 10, "colf", true);
            assertEquals(100, additionalIngest1);
            // A a scan server for resource group GROUP1
            getCluster().getConfig().getClusterServerConfiguration().addScanServerResourceGroup("GROUP1", 1);
            getCluster().getClusterControl().start(ServerType.SCAN_SERVER);
            Wait.waitFor(() -> getCluster().getServerContext().getServerPaths().getScanServer(rg -> true, AddressSelector.all(), true).size() == 2, 30_000);
            Wait.waitFor(() -> getCluster().getServerContext().getServerPaths().getScanServer(rg -> rg.equals(ScanServerSelector.DEFAULT_SCAN_SERVER_GROUP_NAME), AddressSelector.all(), true).size() == 1);
            Wait.waitFor(() -> getCluster().getServerContext().getServerPaths().getScanServer(rg -> rg.equals("GROUP1"), AddressSelector.all(), true).size() == 1);
            scanner.setExecutionHints(Map.of("scan_type", "use_group1"));
            assertEquals(ingestedEntryCount + additionalIngest1, Iterables.size(scanner), "The scan server scanner should have seen all ingested and flushed entries");
            // if scanning against tserver would see the following, but should not on scan server
            final int additionalIngest2 = ScanServerIT.ingest(client, tableName, 10, 10, 20, "colf", false);
            assertEquals(100, additionalIngest2);
            assertEquals(ingestedEntryCount + additionalIngest1, Iterables.size(scanner), "The scan server scanner should have seen all ingested and flushed entries");
            scanner.setConsistencyLevel(ConsistencyLevel.IMMEDIATE);
            assertEquals(ingestedEntryCount + additionalIngest1 + additionalIngest2, Iterables.size(scanner), "Scanning against tserver should have resulted in seeing all ingested entries");
        }
    }
}

