        setExpectedTabletAvailability(expectedTabletAvailability, tableId, "h", "d", TabletAvailability.ONDEMAND);
        setExpectedTabletAvailability(expectedTabletAvailability, tableId, "m", "h", TabletAvailability.UNHOSTED);
        setExpectedTabletAvailability(expectedTabletAvailability, tableId, "q", "m", TabletAvailability.UNHOSTED);
        setExpectedTabletAvailability(expectedTabletAvailability, tableId, "v", "q", TabletAvailability.HOSTED);
        setExpectedTabletAvailability(expectedTabletAvailability, tableId, null, "v", TabletAvailability.HOSTED);
        verifyTabletAvailabilities(tableName, new Range(), expectedTabletAvailability);
    } finally {
        accumuloClient.tableOperations().delete(tableName);
    }
}

@Test
public void test() throws Exception {
    try (AccumuloClient client = Accumulo.newClient().from(getClientProperties()).build()) {
        Wait.waitFor(() -> !client.instanceOperations().getServers(ServerId.Type.TABLET_SERVER).isEmpty());
        final String tableName = getUniqueNames(1)[0];
        client.tableOperations().create(tableName);
        // do an initial write to host the tablet and get its location in cache as we may not be able
        // to read the metadata table later
        try (var writer = client.createBatchWriter(tableName)) {
            Mutation m = new Mutation("001");
            m.put("a", "b", "c");
            writer.addMutation(m);
        }
        // Kill dfs
        cluster.getMiniDfs().shutdown();
        // ask the tserver to do something
        final AtomicReference<Exception> ex = new AtomicReference<>();
        Thread backgroundWriter = new Thread(() -> {
            try {
                for (int i = 0; i < 100; i++) {
                    // These writes should cause the tserver to attempt to write to walog, which should
                    // repeatedly fail. Relying on the client side cache to have the tablet location so the
                    // writes make it to the tserver where the wal write fails.
                    try (var writer = client.createBatchWriter(tableName)) {
                        Mutation m = new Mutation("001");
                        m.put("a", "b", "c");
                        writer.addMutation(m);
                    }
                }
            } catch (Exception e) {
                ex.set(e);
            }
        });
        backgroundWriter.start();
        // wait for the tserver to give up on writing to the WAL
        while (client.instanceOperations().getServers(ServerId.Type.TABLET_SERVER).size() == 1) {
            Thread.sleep(SECONDS.toMillis(1));
        }
    }
}

