@Test
public void test() throws Exception {
    // make some tablets, spread 'em around
    try (AccumuloClient c = Accumulo.newClient().from(getClientProperties()).build()) {
        ServerContext serverContext = cluster.getServerContext();
        String table = this.getUniqueNames(1)[0];
        SortedSet<Text> partitions = new TreeSet<>();
        for (String part : "a b c d e f g h i j k l m n o p q r s t u v w x y z".split(" ")) {
            partitions.add(new Text(part));
        }
        NewTableConfiguration ntc = new NewTableConfiguration().withSplits(partitions).withInitialTabletAvailability(TabletAvailability.HOSTED);
        c.tableOperations().create(table, ntc);
        var tableId = serverContext.getTableId(table);
        var extent1 = new KeyExtent(tableId, new Text("m"), new Text("l"));
        var loc1 = TabletMetadata.Location.current("192.168.1.1:9997", "56");
        var loc2 = TabletMetadata.Location.future("192.168.1.2:9997", "67");
        // set multiple locations for a tablet
        serverContext.getAmple().mutateTablet(extent1).putLocation(loc1).putLocation(loc2).mutate();
        // This operation will fail when there are two locations set on a tablet
        assertThrows(AccumuloException.class, () -> c.tableOperations().setTabletAvailability(table, new Range(), TabletAvailability.HOSTED));
        try (var scanner = c.createScanner(table)) {
            // should not be able to scan the table when a tablet has multiple locations
            assertThrows(IllegalStateException.class, () -> scanner.stream().count());
        }
        // The following check ensures that Ample throws an exception when a tablet has multiple
        // locations and the location is being read.
        try (var tabletsMeta = serverContext.getAmple().readTablets().forTable(tableId).build()) {
            assertThrows(IllegalStateException.class, () -> tabletsMeta.stream().count());
        }
        // should fail when reading an individual tablet
        assertThrows(IllegalStateException.class, () -> serverContext.getAmple().readTablet(extent1));
        // when not reading a tablets location, ample should not fail
        assertEquals(extent1, serverContext.getAmple().readTablet(extent1, TabletMetadata.ColumnType.FILES).getExtent());
        // fix the tablet metadata
        serverContext.getAmple().mutateTablet(extent1).deleteLocation(loc1).deleteLocation(loc2).mutate();
        try (var scanner = c.createScanner(table)) {
            assertEquals(0, scanner.stream().count());
        }
        // should be able to scan using ample now
        try (var tabletsMeta = serverContext.getAmple().readTablets().forTable(tableId).build()) {
            assertEquals(27, tabletsMeta.stream().count());
        }
        // this should no longer fail
        c.tableOperations().setTabletAvailability(table, new Range(), TabletAvailability.HOSTED);
    }
}

@SuppressFBWarnings(value = "URLCONNECTION_SSRF_FD", justification = "url is not from user")
@Test
public void testMonitorService() throws Exception {
    final MiniAccumuloClusterImpl cluster = (MiniAccumuloClusterImpl) getCluster();
    Collection<ProcessReference> monitors = cluster.getProcesses().get(ServerType.MONITOR);
    // Need to start one monitor and let it become active.
    if (monitors == null || monitors.isEmpty()) {
        getClusterControl().start(ServerType.MONITOR, "localhost");
    }
    while (true) {
        try {
            MonitorUtil.getLocation(getServerContext());
            break;
        } catch (Exception e) {
            LOG.debug("Failed to find active monitor location, retrying", e);
            Thread.sleep(1000);
        }
    }
    LOG.debug("Found active monitor");
    int freePort = PortUtils.getRandomFreePort();
    String monitorUrl = "http://localhost:" + freePort;
    Process monitor = null;
    try {
        LOG.debug("Starting standby monitor on {}", freePort);
        monitor = startProcess(cluster, ServerType.MONITOR, freePort);
        while (true) {
            URL url = new URL(monitorUrl);
            try {
                HttpURLConnection cnxn = (HttpURLConnection) url.openConnection();
                final int responseCode = cnxn.getResponseCode();
                String errorText;
                // This is our "assertion", but we want to re-check it if it's not what we expect
                if (responseCode == HttpURLConnection.HTTP_OK) {
                    return;
                } else {
                    errorText = FunctionalTestUtils.readAll(cnxn.getErrorStream());
                }
                LOG.debug("Unexpected responseCode and/or error text, will retry: '{}' '{}'", responseCode, errorText);
            } catch (Exception e) {
                LOG.debug("Caught exception trying to fetch monitor info", e);
            }
            // Wait before trying again
            Thread.sleep(1000);
            // Make sure the process is still up. Possible the "randomFreePort" we got wasn't actually
            // free and the process
            // died trying to bind it. Pick a new port and restart it in that case.
            if (!monitor.isAlive()) {
                freePort = PortUtils.getRandomFreePort();
                monitorUrl = "http://localhost:" + freePort;
                LOG.debug("Monitor died, restarting it listening on {}", freePort);
                monitor = startProcess(cluster, ServerType.MONITOR, freePort);
            }
        }
    } finally {
        if (monitor != null) {
            monitor.destroyForcibly();
        }
    }
}

