@Test
public void test() throws Exception {
    try (AccumuloClient c = Accumulo.newClient().from(getClientProperties()).build()) {
        c.instanceOperations().setProperty(Property.TSERV_TOTAL_MUTATION_QUEUE_MAX.getKey(), "" + SMALL_QUEUE_SIZE);
        String tableName = getUniqueNames(1)[0];
        c.tableOperations().create(tableName);
        c.tableOperations().setProperty(tableName, Property.TABLE_MAJC_RATIO.getKey(), "9999");
        c.tableOperations().setProperty(tableName, Property.TABLE_FILE_MAX.getKey(), "999");
        Thread.sleep(SECONDS.toMillis(1));
        // get an idea of how fast the syncs occur
        byte[] row = new byte[250];
        BatchWriterConfig cfg = new BatchWriterConfig();
        cfg.setMaxWriteThreads(10);
        cfg.setMaxLatency(1, SECONDS);
        cfg.setMaxMemory(1024 * 1024);
        long realSyncs = getSyncs(c);
        long now = System.currentTimeMillis();
        long bytesSent = 0;
        try (BatchWriter bw = c.createBatchWriter(tableName, cfg)) {
            for (int i = 0; i < N; i++) {
                RANDOM.get().nextBytes(row);
                Mutation m = new Mutation(row);
                m.put("", "", "");
                bw.addMutation(m);
                bytesSent += m.estimatedMemoryUsed();
            }
        }
        long diff = System.currentTimeMillis() - now;
        double secs = diff / 1000.;
        double syncs = bytesSent / SMALL_QUEUE_SIZE;
        double syncsPerSec = syncs / secs;
        System.out.printf("Sent %d bytes in %f secs approximately %d syncs (%f syncs per sec)%n", bytesSent, secs, ((long) syncs), syncsPerSec);
        long update = getSyncs(c);
        System.out.println("Syncs " + (update - realSyncs));
        realSyncs = update;
        // Now with a much bigger total queue
        c.instanceOperations().setProperty(Property.TSERV_TOTAL_MUTATION_QUEUE_MAX.getKey(), "" + LARGE_QUEUE_SIZE);
        c.tableOperations().flush(tableName, null, null, true);
        Thread.sleep(SECONDS.toMillis(1));
        try (BatchWriter bw = c.createBatchWriter(tableName, cfg)) {
            now = System.currentTimeMillis();
            bytesSent = 0;
            for (int i = 0; i < N; i++) {
                RANDOM.get().nextBytes(row);
                Mutation m = new Mutation(row);
                m.put("", "", "");
                bw.addMutation(m);
                bytesSent += m.estimatedMemoryUsed();
            }
        }
        diff = System.currentTimeMillis() - now;
        secs = diff / 1000.;
        syncs = bytesSent / LARGE_QUEUE_SIZE;
        syncsPerSec = syncs / secs;
        System.out.printf("Sent %d bytes in %f secs approximately %d syncs (%f syncs per sec)%n", bytesSent, secs, ((long) syncs), syncsPerSec);
        update = getSyncs(c);
        System.out.println("Syncs " + (update - realSyncs));
        assertTrue(update - realSyncs < realSyncs);
    }
}

@Test
public void testCachedTransport() throws InterruptedException {
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        Wait.waitFor(() -> !client.instanceOperations().getServers(ServerId.Type.TABLET_SERVER).isEmpty());
        ClientContext context = (ClientContext) client;
        long rpcTimeout = ConfigurationTypeHelper.getTimeInMillis(Property.GENERAL_RPC_TIMEOUT.getDefaultValue());
        List<ThriftTransportKey> servers = client.instanceOperations().getServers(ServerId.Type.TABLET_SERVER).stream().map(tsi -> {
            return new ThriftTransportKey(ThriftClientTypes.CLIENT, HostAndPort.fromParts(tsi.getHost(), tsi.getPort()), rpcTimeout, context);
        }).collect(Collectors.toList());
        // only want to use one server for all subsequent test
        ThriftTransportKey ttk = servers.get(0);
        ThriftTransportPool pool = context.getTransportPool();
        TTransport first = getAnyTransport(ttk, pool, true);
        assertNotNull(first);
        // Return it to unreserve it
        pool.returnTransport(first);
        TTransport second = getAnyTransport(ttk, pool, true);
        // We should get the same transport
        assertSame(first, second, "Expected the first and second to be the same instance");
        pool.returnTransport(second);
        // Ensure does not get cached connection just returned
        TTransport third = getAnyTransport(ttk, pool, false);
        assertNotSame(second, third, "Expected second and third transport to be different instances");
        TTransport fourth = getAnyTransport(ttk, pool, false);
        assertNotSame(third, fourth, "Expected third and fourth transport to be different instances");
        pool.returnTransport(third);
        pool.returnTransport(fourth);
        // The following three asserts ensure the per server queue is LIFO
        TTransport fifth = getAnyTransport(ttk, pool, true);
        assertSame(fourth, fifth, "Expected fourth and fifth transport to be the same instance");
        TTransport sixth = getAnyTransport(ttk, pool, true);
        assertSame(third, sixth, "Expected third and sixth transport to be the same instance");
        TTransport seventh = getAnyTransport(ttk, pool, true);
        assertSame(second, seventh, "Expected second and seventh transport to be the same instance");
        pool.returnTransport(fifth);
        pool.returnTransport(sixth);
        pool.returnTransport(seventh);
    }
}

