@Test
public void testSerializedRecovery() throws Exception {
    // make a table with many splits
    String tableName = getUniqueNames(1)[0];
    try (AccumuloClient c = Accumulo.newClient().from(getClientProperties()).build()) {
        // create splits
        SortedSet<Text> splits = new TreeSet<>();
        for (int i = 0; i < 200; i++) {
            splits.add(new Text(randomHex(8)));
        }
        // create table with config
        NewTableConfiguration ntc = new NewTableConfiguration().withSplits(splits);
        c.tableOperations().create(tableName, ntc);
        // load data to give the recovery something to do
        try (BatchWriter bw = c.createBatchWriter(tableName)) {
            for (int i = 0; i < 50000; i++) {
                Mutation m = new Mutation(randomHex(8));
                m.put("", "", "");
                bw.addMutation(m);
            }
        }
        // kill the tserver
        for (ProcessReference ref : getCluster().getProcesses().get(ServerType.TABLET_SERVER)) {
            getCluster().killProcess(ServerType.TABLET_SERVER, ref);
        }
        final ProcessInfo ts = cluster.exec(TabletServer.class);
        // wait for recovery
        try (Scanner scanner = c.createScanner(tableName, Authorizations.EMPTY)) {
            scanner.forEach((k, v) -> {
            });
        }
        assertEquals(0, cluster.exec(Admin.class, "stopAll").getProcess().waitFor());
        ts.getProcess().waitFor();
        String result = ts.readStdOut();
        log.info(result);
        // walk through the output, verifying that only a single normal recovery was running at one
        // time
        boolean ongoingRecovery = false;
        int recoveries = 0;
        var pattern = Pattern.compile(".*recovered \\d+ mutations creating \\d+ entries from \\d+ walogs.*");
        for (String line : result.split("\n")) {
            // ignore metadata and root tables
            if (line.contains(AccumuloTable.METADATA.tableId().canonical()) || line.contains(AccumuloTable.ROOT.tableId().canonical())) {
                continue;
            }
            if (line.contains("recovering data from walogs")) {
                assertFalse(ongoingRecovery, "Saw recovery start before previous recovery finished");
                ongoingRecovery = true;
                recoveries++;
            }
            if (pattern.matcher(line).matches()) {
                assertTrue(ongoingRecovery, "Saw recovery end without recovery start");
                ongoingRecovery = false;
            }
        }
        assertFalse(ongoingRecovery, "Expected no ongoing recovery at end of test");
        assertTrue(recoveries > 0, "Expected at least one recovery to have occurred");
    }
}

