@Test
public void testHdfsConfigOverrides() throws Exception {
    try (AccumuloClient c = Accumulo.newClient().from(getClientProperties()).build()) {
        Map<String, String> siteConfig = c.instanceOperations().getSiteConfiguration();
        assertEquals("10485760", siteConfig.get(Property.INSTANCE_VOLUME_CONFIG_PREFIX.getKey() + vol1 + ".dfs.blocksize"));
        assertEquals("51200000", siteConfig.get(Property.INSTANCE_VOLUME_CONFIG_PREFIX.getKey() + vol2 + ".dfs.blocksize"));
        assertEquals("true", siteConfig.get(Property.INSTANCE_VOLUME_CONFIG_PREFIX.getKey() + vol1 + ".dfs.client.use.datanode.hostname"));
        assertEquals("false", siteConfig.get(Property.INSTANCE_VOLUME_CONFIG_PREFIX.getKey() + vol2 + ".dfs.client.use.datanode.hostname"));
        assertEquals("0", siteConfig.get(Property.INSTANCE_VOLUME_CONFIG_PREFIX.getKey() + vol1 + ".dfs.client.hedged.read.threadpool.size"));
        assertEquals("1", siteConfig.get(Property.INSTANCE_VOLUME_CONFIG_PREFIX.getKey() + vol2 + ".dfs.client.hedged.read.threadpool.size"));
        String[] names = getUniqueNames(2);
        String t1 = names[0];
        String t2 = names[1];
        NewTableConfiguration ntc1 = new NewTableConfiguration();
        ntc1.setProperties(Map.of("table.custom.volume.preferred", vol1));
        c.tableOperations().create(t1, ntc1);
        ReadWriteIT.ingest(c, 10, 10, 100, 0, t1);
        c.tableOperations().flush(t1, null, null, true);
        NewTableConfiguration ntc2 = new NewTableConfiguration();
        ntc2.setProperties(Map.of("table.custom.volume.preferred", vol2));
        c.tableOperations().create(t2, ntc2);
        ReadWriteIT.ingest(c, 10, 10, 100, 0, t2);
        c.tableOperations().flush(t2, null, null, true);
        String tid1 = c.tableOperations().tableIdMap().get(t1);
        String tid2 = c.tableOperations().tableIdMap().get(t2);
        assertNotNull(tid1);
        assertNotNull(tid2);
        // Confirm that table 1 has a block size of 10485760
        FileSystem fs = this.cluster.getMiniDfs().getFileSystem();
        // t1 is configured to use vol1, which is the second in the volumes list
        final Path tablePath1 = new Path(cluster.getSiteConfiguration().get(Property.INSTANCE_VOLUMES).split(",")[1] + "/" + Constants.TABLE_DIR + "/" + tid1);
        RemoteIterator<LocatedFileStatus> iter1 = fs.listFiles(tablePath1, true);
        while (iter1.hasNext()) {
            LocatedFileStatus stat = iter1.next();
            if (stat.isFile()) {
                assertEquals(10485760, stat.getBlockSize());
            }
        }
        // Confirm that table 1 has a block size of 51200000
        // t2 is configured to use vol2, which is the first in the volumes list
        final Path tablePath2 = new Path(cluster.getSiteConfiguration().get(Property.INSTANCE_VOLUMES).split(",")[0] + "/" + Constants.TABLE_DIR + "/" + tid2);
        RemoteIterator<LocatedFileStatus> iter2 = fs.listFiles(tablePath2, true);
        while (iter2.hasNext()) {
            LocatedFileStatus stat = iter2.next();
            if (stat.isFile()) {
                assertEquals(51200000, stat.getBlockSize());
            }
        }
    }
}

