@Test
public void testBatchScanWithSplits() throws Exception {
    // make a table
    final String tableName = getUniqueNames(1)[0];
    TreeSet<Text> splits = new TreeSet<>();
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        client.tableOperations().create(tableName);
        List<Range> ranges = new ArrayList<>();
        final int alphabetLength = 26;
        try (BatchWriter writer = client.createBatchWriter(tableName, new BatchWriterConfig())) {
            for (int i = 0; i < alphabetLength; i++) {
                byte[] row = new byte[] { (byte) (START_ROW + i) };
                Text beginRow = new Text(row);
                Mutation m = new Mutation(beginRow);
                m.put(new Text(), new Text(), new Value());
                writer.addMutation(m);
                Text endRow = new Text(row);
                endRow.append("\0".getBytes(UTF_8), 0, 1);
                ranges.add(new Range(new Text(row), endRow));
                if (i % 4 == 0) {
                    splits.add(beginRow);
                }
            }
            client.tableOperations().addSplits(tableName, splits);
            writer.flush();
        }
        log.info("Creating batch scanner");
        try (BatchScanner scanner = client.createBatchScanner(tableName, Authorizations.EMPTY, 1)) {
            final IteratorSetting cfg = new IteratorSetting(100, YieldingIterator.class);
            scanner.addScanIterator(cfg);
            scanner.setRanges(ranges);
            final AtomicInteger keyCount = new AtomicInteger();
            scanner.stream().sorted(Map.Entry.comparingByKey()).forEach(entry -> {
                log.info("{}: Got key '{}' with value '{}'", keyCount, entry.getKey(), entry.getValue());
                // verify we got the expected key
                char expected = (char) (START_ROW + keyCount.get());
                assertEquals(Character.toString(expected), entry.getKey().getRow().toString(), "Unexpected row");
                keyCount.getAndIncrement();
            });
            assertEquals(alphabetLength, keyCount.get(), "Did not get the expected number of results");
        }
    }
}

/**
 * This test ensure that scans threads that run forever do not prevent tablets from unloading.
 */
@Test
public void testZombieScan() throws Exception {
    String table = getUniqueNames(1)[0];
    try (AccumuloClient c = Accumulo.newClient().from(getClientProperties()).build()) {
        var splits = new TreeSet<Text>();
        splits.add(new Text("3"));
        splits.add(new Text("5"));
        splits.add(new Text("7"));
        var ntc = new NewTableConfiguration().withSplits(splits);
        c.tableOperations().create(table, ntc);
        try (var writer = c.createBatchWriter(table)) {
            for (var row : List.of("2", "4", "6", "8")) {
                Mutation m = new Mutation(row);
                m.put("f", "q", "v");
                writer.addMutation(m);
            }
        }
        // Flush the data otherwise when the tablet attempts to close with an active scan reading from
        // the in memory map it will wait for 15 seconds for the scan
        c.tableOperations().flush(table, null, null, true);
        var executor = Executors.newCachedThreadPool();
        // start two zombie scans that should never return using a normal scanner
        List<Future<String>> futures = new ArrayList<>();
        for (var row : List.of("2", "4")) {
            var future = executor.submit(() -> {
                try (var scanner = c.createScanner(table)) {
                    IteratorSetting iter = new IteratorSetting(100, "Z", ZombieIterator.class);
                    scanner.addScanIterator(iter);
                    scanner.setRange(new Range(row));
                    return scanner.stream().findFirst().map(e -> e.getKey().getRowData().toString()).orElse("none");
                }
            });
            futures.add(future);
        }
        // start two zombie scans that should never return using a batch scanner
        for (var row : List.of("6", "8")) {
            var future = executor.submit(() -> {
                try (var scanner = c.createBatchScanner(table)) {
                    IteratorSetting iter = new IteratorSetting(100, "Z", ZombieIterator.class);
                    scanner.addScanIterator(iter);
                    scanner.setRanges(List.of(new Range(row)));
                    return scanner.stream().findFirst().map(e -> e.getKey().getRowData().toString()).orElse("none");
                }
            });
            futures.add(future);
        }
        // should eventually see the four zombie scans running against four tablets
        Wait.waitFor(() -> countDistinctTabletsScans(table, c) == 4);
        assertEquals(1, c.instanceOperations().getServers(ServerId.Type.TABLET_SERVER).size());
        // Start 3 new tablet servers, this should cause the table to balance and the tablets with
        // zombie scans to unload. The Zombie scans should not prevent the table from unloading. The
        // scan threads will still be running on the old tablet servers.
        getCluster().getConfig().getClusterServerConfiguration().setNumDefaultTabletServers(4);
        getCluster().getClusterControl().start(ServerType.TABLET_SERVER, Map.of(), 4);
        // Wait for all tablets servers
        Wait.waitFor(() -> c.instanceOperations().getServers(ServerId.Type.TABLET_SERVER).size() == 4);
        // The table should eventually balance across the 4 tablet servers
        Wait.waitFor(() -> countLocations(table, c) == 4);
        // The zombie scans should still be running
        assertTrue(futures.stream().noneMatch(Future::isDone));
        // Should be able to scan all the tablets at the new locations.
        try (var scanner = c.createScanner(table)) {
            var rows = scanner.stream().map(e -> e.getKey().getRowData().toString()).collect(Collectors.toSet());
            assertEquals(Set.of("2", "4", "6", "8"), rows);
        }
        try (var scanner = c.createBatchScanner(table)) {
            scanner.setRanges(List.of(new Range()));
            var rows = scanner.stream().map(e -> e.getKey().getRowData().toString()).collect(Collectors.toSet());
            assertEquals(Set.of("2", "4", "6", "8"), rows);
        }
        // The zombie scans should migrate with the tablets, taking up more scan threads in the
        // system.
        Set<ServerId> tabletServersWithZombieScans = new HashSet<>();
        for (ServerId tserver : c.instanceOperations().getServers(ServerId.Type.TABLET_SERVER)) {
            if (c.instanceOperations().getActiveScans(List.of(tserver)).stream().flatMap(activeScan -> activeScan.getSsiList().stream()).anyMatch(scanIters -> scanIters.contains(ZombieIterator.class.getName()))) {
                tabletServersWithZombieScans.add(tserver);
            }
        }
        assertEquals(4, tabletServersWithZombieScans.size());
        // This check may be outside the scope of this test but works nicely for this check and is
        // simple enough to include
        assertValidScanIds(c);
        executor.shutdownNow();
    }
}

/**
 * Create some zombie scans and ensure metrics for them show up.
 */
@ParameterizedTest
@EnumSource
public void testMetrics(ConsistencyLevel consistency) throws Exception {
    Wait.waitFor(() -> {
        var zsmc = getZombieScansMetric();
        return zsmc == -1 || zsmc == 0;
    });
    String table = getUniqueNames(1)[0];
    final ServerType serverType = consistency == IMMEDIATE ? TABLET_SERVER : SCAN_SERVER;
    try (AccumuloClient c = Accumulo.newClient().from(getClientProperties()).build()) {
        if (serverType == SCAN_SERVER) {
            // Scans will fall back to tablet servers when no scan servers are present. So wait for scan
            // servers to show up in zookeeper. Can remove this in 3.1.
            Wait.waitFor(() -> !c.instanceOperations().getServers(ServerId.Type.SCAN_SERVER).isEmpty());
        }
        c.tableOperations().create(table);
        var executor = Executors.newCachedThreadPool();
        // start four stuck scans that should never return data
        List<Future<String>> futures = new ArrayList<>();
        for (var row : List.of("2", "4")) {
            // start a scan with an iterator that gets stuck and can not be interrupted
            futures.add(startStuckScan(c, table, executor, row, false, consistency));
            // start a scan with an iterator that gets stuck and can be interrupted
            futures.add(startStuckScan(c, table, executor, row, true, consistency));
        }
        // start four stuck scans, using a batch scanner, that should never return data
        for (var row : List.of("6", "8")) {
            // start a scan with an iterator that gets stuck and can not be interrupted
            futures.add(startStuckBatchScan(c, table, executor, row, false, consistency));
            // start a scan with an iterator that gets stuck and can be interrupted
            futures.add(startStuckBatchScan(c, table, executor, row, true, consistency));
        }
        // should eventually see the eight stuck scans running
        Wait.waitFor(() -> countActiveScans(c, serverType, table) == 8);
        // Cancel the scan threads. This will cause the sessions on the server side to timeout and
        // become inactive. The stuck threads on the server side related to the timed out sessions
        // will be interrupted.
        Wait.waitFor(() -> {
            futures.forEach(future -> future.cancel(true));
            return futures.stream().allMatch(Future::isDone);
        });
        // Four of the eight running scans should respond to thread interrupts and exit
        Wait.waitFor(() -> countActiveScans(c, serverType, table) == 4);
        Wait.waitFor(() -> getZombieScansMetric() == 4);
        assertEquals(4, countActiveScans(c, serverType, table));
        // start four more stuck scans with two that will ignore interrupts
        futures.clear();
        futures.add(startStuckScan(c, table, executor, "0", false, consistency));
        futures.add(startStuckScan(c, table, executor, "0", true, consistency));
        futures.add(startStuckBatchScan(c, table, executor, "99", false, consistency));
        futures.add(startStuckBatchScan(c, table, executor, "0", true, consistency));
        Wait.waitFor(() -> countActiveScans(c, serverType, table) == 8);
        // Cancel the client side scan threads. Should cause the server side threads to be
        // interrupted.
        Wait.waitFor(() -> {
            futures.forEach(future -> future.cancel(true));
            return futures.stream().allMatch(Future::isDone);
        });
        // Two of the stuck threads should respond to interrupts on the server side and exit.
        Wait.waitFor(() -> countActiveScans(c, serverType, table) == 6);
        Wait.waitFor(() -> getZombieScansMetric() == 6);
        assertEquals(6, countActiveScans(c, serverType, table));
        executor.shutdownNow();
    }
}

@Test
public void testGetChildren() throws Exception {
    final String root = Constants.ZROOT + UUID.randomUUID().toString();
    final String base = root + Constants.ZTSERVERS;
    TestZooCache zooCache = new TestZooCache(zk, Set.of(base));
    zrw.mkdirs(base + "/test2");
    zrw.mkdirs(base + "/test3/c1");
    zrw.mkdirs(base + "/test3/c2");
    // cache non-existence of /test1 and existence of /test2 and /test3
    long uc1 = zooCache.getUpdateCount();
    assertNull(zooCache.getChildren(base + "/test1"));
    long uc2 = zooCache.getUpdateCount();
    assertTrue(uc1 < uc2);
    assertEquals(List.of(), zooCache.getChildren(base + "/test2"));
    long uc3 = zooCache.getUpdateCount();
    assertTrue(uc2 < uc3);
    assertEquals(Set.of("c1", "c2"), Set.copyOf(zooCache.getChildren(base + "/test3")));
    long uc4 = zooCache.getUpdateCount();
    assertTrue(uc3 < uc4);
    // The cache should be stable now and new accesses should not change the update count
    assertNull(zooCache.getChildren(base + "/test1"));
    // once getChildren discovers that a node does not exists, then get data will also know this
    assertNull(zooCache.get(base + "/test1"));
    assertEquals(List.of(), zooCache.getChildren(base + "/test2"));
    assertEquals(Set.of("c1", "c2"), Set.copyOf(zooCache.getChildren(base + "/test3")));
    assertEquals(uc4, zooCache.getUpdateCount());
    // Had cached non-existence of "/test1", should get a notification that it was created
    zrw.mkdirs(base + "/test1");
    Wait.waitFor(() -> {
        var children = zooCache.getChildren(base + "/test1");
        return children != null && children.isEmpty();
    });
    long uc5 = zooCache.getUpdateCount();
    assertTrue(uc4 < uc5);
    assertEquals(List.of(), zooCache.getChildren(base + "/test1"));
    assertEquals(List.of(), zooCache.getChildren(base + "/test2"));
    assertEquals(Set.of("c1", "c2"), Set.copyOf(zooCache.getChildren(base + "/test3")));
    long uc5b = zooCache.getUpdateCount();
    assertTrue(uc5 < uc5b);
    // add a child to /test3, should get a notification of the change
    zrw.mkdirs(base + "/test3/c3");
    Wait.waitFor(() -> {
        var children = zooCache.getChildren(base + "/test3");
        return children != null && children.size() == 3;
    });
    long uc6 = zooCache.getUpdateCount();
    assertTrue(uc5b < uc6);
    assertEquals(List.of(), zooCache.getChildren(base + "/test1"));
    assertEquals(List.of(), zooCache.getChildren(base + "/test2"));
    assertEquals(Set.of("c1", "c2", "c3"), Set.copyOf(zooCache.getChildren(base + "/test3")));
    assertEquals(uc6, zooCache.getUpdateCount());
    // remove a child from /test3
    zrw.delete(base + "/test3/c2");
    Wait.waitFor(() -> {
        var children = zooCache.getChildren(base + "/test3");
        return children != null && children.size() == 2;
    });
    long uc7 = zooCache.getUpdateCount();
    assertTrue(uc6 < uc7);
    assertEquals(List.of(), zooCache.getChildren(base + "/test1"));
    assertEquals(List.of(), zooCache.getChildren(base + "/test2"));
    assertEquals(Set.of("c1", "c3"), Set.copyOf(zooCache.getChildren(base + "/test3")));
    assertEquals(uc7, zooCache.getUpdateCount());
    // remove /test2, should start caching that it does not exist
    zrw.delete(base + "/test2");
    Wait.waitFor(() -> zooCache.getChildren(base + "/test2") == null);
    long uc8 = zooCache.getUpdateCount();
    assertTrue(uc7 < uc8);
    assertEquals(List.of(), zooCache.getChildren(base + "/test1"));
    assertNull(zooCache.getChildren(base + "/test2"));
    assertEquals(Set.of("c1", "c3"), Set.copyOf(zooCache.getChildren(base + "/test3")));
    long uc8b = zooCache.getUpdateCount();
    assertTrue(uc8 < uc8b);
    // add /test2 back, should update
    zrw.mkdirs(base + "/test2");
    Wait.waitFor(() -> zooCache.getChildren(base + "/test2") != null);
    long uc9 = zooCache.getUpdateCount();
    assertTrue(uc8 < uc9);
    assertEquals(List.of(), zooCache.getChildren(base + "/test1"));
    assertEquals(List.of(), zooCache.getChildren(base + "/test2"));
    assertEquals(Set.of("c1", "c3"), Set.copyOf(zooCache.getChildren(base + "/test3")));
    long uc9b = zooCache.getUpdateCount();
    assertTrue(uc9 < uc9b);
    // make multiple changes. the cache should see all of these
    zrw.delete(base + "/test1");
    zrw.mkdirs(base + "/test2/ca");
    zrw.delete(base + "/test3/c1");
    zrw.mkdirs(base + "/test3/c4");
    zrw.delete(base + "/test3/c4");
    zrw.mkdirs(base + "/test3/c5");
    Wait.waitFor(() -> {
        var children1 = zooCache.getChildren(base + "/test1");
        var children2 = zooCache.getChildren(base + "/test2");
        var children3 = zooCache.getChildren(base + "/test3");
        return children1 == null && children2 != null && children2.size() == 1 && children3 != null && Set.copyOf(children3).equals(Set.of("c3", "c5"));
    });
    long uc10 = zooCache.getUpdateCount();
    assertTrue(uc9b < uc10);
    assertNull(zooCache.getChildren(base + "/test1"));
    assertEquals(List.of("ca"), zooCache.getChildren(base + "/test2"));
    assertEquals(Set.of("c3", "c5"), Set.copyOf(zooCache.getChildren(base + "/test3")));
    assertEquals(uc10, zooCache.getUpdateCount());
    // wait for the cache to evict and clear watches
    TestZooCache.ticker.advance();
    Wait.waitFor(() -> {
        // the cache will not run its eviction handler unless accessed, so access something that is
        // not expected to be evicted
        zooCache.getChildren(base + "/test4");
        return zooCache.childrenCached(base + "/test1") == false && zooCache.childrenCached(base + "/test2") == false && zooCache.childrenCached(base + "/test3") == false;
    });
}

@Test
public void testDataWatches() throws Exception {
    // register watcher
    var stat = chrootZk.exists(relativeNodePath, watcher);
    assertNull(stat);
    // create and watch for the event
    rootZk.create(absoluteNodePath, "something".getBytes(UTF_8), ZooUtil.PUBLIC, CreateMode.PERSISTENT);
    Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeCreated)));
    // prepare for data changed event
    // re-register fired watcher for data changed
    stat = chrootZk.exists(relativeNodePath, watcher);
    assertNotNull(stat);
    // change data
    stat = rootZk.setData(absoluteNodePath, "somethingElse".getBytes(UTF_8), stat.getVersion());
    assertNotNull(stat);
    Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeCreated, NodeDataChanged)));
    // prepare for delete event
    // re-register fired watcher for delete
    stat = chrootZk.exists(relativeNodePath, watcher);
    assertNotNull(stat);
    // delete and watch for the event
    rootZk.delete(absoluteNodePath, stat.getVersion());
    Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeCreated, NodeDataChanged, NodeDeleted)));
    stat = chrootZk.exists(relativeNodePath, null);
    assertNull(stat);
}

@Test
public void testChildWatches() throws Exception {
    // create parent to watch
    rootZk.create(absoluteNodePath, "something".getBytes(UTF_8), ZooUtil.PUBLIC, CreateMode.PERSISTENT);
    var children = chrootZk.getChildren(relativeNodePath, watcher);
    assertTrue(children.isEmpty());
    rootZk.create(absoluteNodePath + "/child1", "itsagirl".getBytes(UTF_8), ZooUtil.PUBLIC, CreateMode.PERSISTENT);
    Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeChildrenChanged)));
    // check children without re-registering the watcher
    children = chrootZk.getChildren(relativeNodePath, null);
    assertEquals(List.of("child1"), children);
    rootZk.create(absoluteNodePath + "/child2", "itsaboy".getBytes(UTF_8), ZooUtil.PUBLIC, CreateMode.PERSISTENT);
    Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeChildrenChanged)));
    // check children and re-register the watcher
    children = chrootZk.getChildren(relativeNodePath, watcher);
    // sort order is not guaranteed from ZK
    children.sort(String::compareTo);
    assertEquals(List.of("child1", "child2"), children);
    rootZk.create(absoluteNodePath + "/pet", "itsacat".getBytes(UTF_8), ZooUtil.PUBLIC, CreateMode.PERSISTENT);
    Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeChildrenChanged, NodeChildrenChanged)));
    // check children and re-register the watcher for deletes
    children = chrootZk.getChildren(relativeNodePath, watcher);
    // sort order is not guaranteed from ZK
    children.sort(String::compareTo);
    assertEquals(List.of("child1", "child2", "pet"), children);
    // check delete
    rootZk.delete(absoluteNodePath + "/pet", 0);
    Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeChildrenChanged, NodeChildrenChanged, NodeChildrenChanged)));
    // check children and re-register the watcher for more deletes
    children = chrootZk.getChildren(relativeNodePath, watcher);
    // sort order is not guaranteed from ZK
    children.sort(String::compareTo);
    assertEquals(List.of("child1", "child2"), children);
    // delete another node, but do it recursively to ensure the watched event fires on the parent
    ZKUtil.deleteRecursive(rootZk, absoluteNodePath + "/child2");
    Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeChildrenChanged, NodeChildrenChanged, NodeChildrenChanged, NodeChildrenChanged)));
    // check children and re-register the watcher for more deletes
    children = chrootZk.getChildren(relativeNodePath, watcher);
    assertEquals(List.of("child1"), children);
    // delete the parent recursively to ensure the watcher still fires
    ZKUtil.deleteRecursive(rootZk, absoluteNodePath);
    Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeChildrenChanged, NodeChildrenChanged, NodeChildrenChanged, NodeChildrenChanged, NodeChildrenChanged)));
    var stat = chrootZk.exists(relativeNodePath, null);
    assertNull(stat);
}

@Test
public void testPersistentRecursiveWatches() throws Exception {
    // this test does not cover the edge case described in ZOOKEEPER-4475, which was fixed in 3.9.0;
    // the extra events received in that edge case are of the same type tested in the
    // testChildWatches test method elsewhere in this test class; we have no reason to believe that
    // they would somehow contain extra path information when sent to the persistent recursive
    // watcher that was not supposed to receive them; a correctly implemented persistent recursive
    // watcher should ignore those extra events anyway, so even if they did contain extra path
    // information, it shouldn't matter
    try (var directChrootZk = testZk.createDirectZk(ROOT)) {
        // watcher set on node, but it doesn't exist yet
        directChrootZk.addWatch(relativeNodePath, watcher, AddWatchMode.PERSISTENT_RECURSIVE);
        // create node
        rootZk.create(absoluteNodePath, null, ZooUtil.PUBLIC, CreateMode.PERSISTENT);
        Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeCreated)) && childPathEvents.isEmpty());
        // change data
        var stat = rootZk.setData(absoluteNodePath, "somethingElse".getBytes(UTF_8), 0);
        assertNotNull(stat);
        Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeCreated, NodeDataChanged)) && childPathEvents.isEmpty());
        // add a child
        rootZk.create(absoluteNodePath + "/child", null, ZooUtil.PUBLIC, CreateMode.PERSISTENT);
        Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeCreated, NodeDataChanged)) && childPathEvents.equals(List.of(NodeCreated)));
        // change child data
        var childStat = rootZk.setData(absoluteNodePath + "/child", "somethingElse".getBytes(UTF_8), 0);
        assertNotNull(childStat);
        Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeCreated, NodeDataChanged)) && childPathEvents.equals(List.of(NodeCreated, NodeDataChanged)));
        // delete child
        ZKUtil.deleteRecursive(rootZk, absoluteNodePath);
        Wait.waitFor(() -> exactPathEvents.equals(List.of(NodeCreated, NodeDataChanged, NodeDeleted)) && childPathEvents.equals(List.of(NodeCreated, NodeDataChanged, NodeDeleted)));
    }
}

