@Test
@Timeout(30)
public void testTablePropUtils() throws AccumuloException, TableExistsException, AccumuloSecurityException, TableNotFoundException {
    ServerContext context = getCluster().getServerContext();
    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
        final String tableName = getUniqueNames(1)[0];
        client.tableOperations().create(tableName);
        Map<String, String> idMap = client.tableOperations().tableIdMap();
        String tid = idMap.get(tableName);
        Map<String, String> properties = client.tableOperations().getConfiguration(tableName);
        assertEquals("false", properties.get(Property.TABLE_BLOOM_ENABLED.getKey()));
        final TablePropKey tablePropKey = TablePropKey.of(TableId.of(tid));
        PropUtil.setProperties(context, tablePropKey, Map.of(Property.TABLE_BLOOM_ENABLED.getKey(), "true"));
        // add a sleep to give the property change time to propagate
        properties = client.tableOperations().getConfiguration(tableName);
        while (properties.get(Property.TABLE_BLOOM_ENABLED.getKey()).equals("false")) {
            try {
                Thread.sleep(250);
            } catch (InterruptedException e) {
                fail("Thread interrupted while waiting for tablePropUtil update");
            }
            properties = client.tableOperations().getConfiguration(tableName);
        }
        PropUtil.removeProperties(context, tablePropKey, List.of(Property.TABLE_BLOOM_ENABLED.getKey()));
        properties = client.tableOperations().getConfiguration(tableName);
        while (properties.get(Property.TABLE_BLOOM_ENABLED.getKey()).equals("true")) {
            try {
                Thread.sleep(250);
            } catch (InterruptedException e) {
                fail("Thread interrupted while waiting for tablePropUtil update");
            }
            properties = client.tableOperations().getConfiguration(tableName);
        }
        // Add invalid property
        assertThrows(IllegalArgumentException.class, () -> PropUtil.setProperties(context, tablePropKey, Map.of("NOT_A_PROPERTY", "not_a_value")), "Expected IllegalArgumentException to be thrown.");
    }
}

